window.ANSWER_TERMS = {"prionziekte":{"match":"prionziekten|prionziektes|prionziekte|spongiforme encefalopathieën|spongiforme encefalopathie|overdraagbare spongiforme encefalopathie","title":"Prionziekten","short":"Prionziekten zijn zeldzame, dodelijke hersenziekten waarbij een verkeerd gevouwen eiwit (PrP) zich ophoopt en het hersenweefsel sponsachtig maakt — zoals de ziekte van Creutzfeldt-Jakob en BSE.","definition":"<p><strong>Prionziekten</strong> (overdraagbare spongiforme encefalopathieën) zijn zeldzame, altijd dodelijke neurodegeneratieve ziekten. De oorzaak is geen micro-organisme maar een <em>eiwit</em>: het lichaamseigen PrP<sup>C</sup> klapt om naar de pathologische PrP<sup>Sc</sup>-vorm, die aggregeert in plaques en het hersenweefsel vol microscopische vacuolen zet — vandaar de <em>spongiforme</em> (sponsachtige) aanblik.</p><p>Bij de mens: de <em>ziekte van Creutzfeldt-Jakob</em> (sporadisch, erfelijk via PRNP-mutaties, of verworven), <em>kuru</em>, <em>fatale familiaire insomnie</em> en <em>GSS</em>. Bij dieren: <em>BSE</em> (“gekkekoeienziekte”) en <em>scrapie</em>. Klinisch: snel progressieve dementie, myoclonieën en ataxie, met overlijden meestal binnen een jaar.</p><p>Prionen zijn extreem resistent: gewone sterilisatie, koken, straling en de meeste desinfectantia inactiveren ze niet — een reële bron van iatrogene overdracht via instrumenten en transplantaten.</p>","image_url":"","wiki_titles":["Transmissible spongiform encephalopathy","Creutzfeldt–Jakob disease"]},"PrP":{"match":"PrPSc|PrPC|PrP|prioneiwit|prion-eiwit","title":"PrP (prioneiwit)","short":"PrP is een lichaamseigen eiwit in hersencellen. In de normale vorm (PrP^C) zit het vol alfa-helices; in de ziektevorm (PrP^Sc) is het omgevouwen tot beta-sheets en slaat het onoplosbaar neer.","definition":"<p><strong>PrP</strong> (prion protein) wordt gecodeerd door het <em>PRNP</em>-gen en komt normaal voor op het membraan van vooral neuronen. De gezonde vorm <strong>PrP<sup>C</sup></strong> (cellular) is rijk aan <em>alfa-helices</em>, goed oplosbaar en wordt gewoon afgebroken door proteasen.</p><p>De ziektevorm <strong>PrP<sup>Sc</sup></strong> (scrapie) heeft dezelfde aminozuurvolgorde — alleen de vouwing verschilt: veel <em>beta-sheets</em>, waardoor hydrofobe zijketens aan het oppervlak komen. Daardoor is PrP<sup>Sc</sup> onoplosbaar, protease-resistent en plakt het aan elkaar tot fibrillen en amyloïde plaques.</p><p>Het besmettelijke zit in de vorm: PrP<sup>Sc</sup> werkt als mal en dwingt gezond PrP<sup>C</sup> in dezelfde vouwing — een kettingreactie zonder DNA of RNA.</p>","image_url":"","wiki_titles":["Major prion protein","Prion"]},"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"actine":{"title":"Actine","short":"Eiwit dat microfilamenten vormt; betrokken bij celvorm, celbeweging en spiercontractie.","definition":"<p><b>Actine</b> is een van de meest voorkomende eiwitten in de cel. Losse moleculen (G-actine) polymeriseren tot dunne draden (F-actine): de microfilamenten van het cytoskelet.</p><p>Actinefilamenten geven de cel vorm, maken beweging en deling mogelijk en vormen samen met myosine het contractiele apparaat van spiercellen.</p>","image_url":"","wiki_title":"Actin","match":"actine|actinefilamenten|actinefilament"},"myosine":{"title":"Myosine","short":"Motoreiwit dat langs actinefilamenten beweegt en zo spiercontractie en intracellulair transport aandrijft.","definition":"<p><b>Myosine</b> is een motoreiwit dat onder verbruik van ATP kracht levert door langs actinefilamenten te 'lopen'.</p><p>In spiercellen glijden myosine- en actinefilamenten langs elkaar, wat de spier doet samentrekken (het glijdende-filamentmodel).</p>","image_url":"","wiki_title":"Myosin","match":"myosine|myosinefilamenten|myosinefilament"},"microtubuli":{"title":"Microtubuli","short":"Holle buisjes van tubuline; het stevigste onderdeel van het cytoskelet, sporen voor transport en de mitosespoel.","definition":"<p><b>Microtubuli</b> zijn holle buisjes opgebouwd uit tubuline-dimeren. Ze zijn dynamisch: ze groeien en krimpen aan hun uiteinden.</p><p>Ze geven de cel structuur, vormen de rails voor de motoreiwitten kinesine en dyneïne, en bouwen tijdens de celdeling de mitosespoel.</p>","image_url":"","wiki_title":"Microtubule","match":"microtubuli|microtubulus"},"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"keratinocyt":{"title":"Keratinocyt","short":"De hoofdcel van de epidermis; produceert keratine en bouwt al opschuivend de huidbarrière op.","definition":"<p>De <b>keratinocyt</b> maakt ongeveer 90% van de epidermiscellen uit. Vanuit het stratum basale schuift hij omhoog terwijl hij steeds meer keratine vormt.</p><p>Bovenaan aangekomen is hij een dode, verhoornde cel die de barrière vormt en uiteindelijk afschilfert.</p>","image_url":"","wiki_title":"Keratinocyte","match":"keratinocyt|keratinocyten"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"macula":{"title":"Macula","short":"Vlakke, niet-voelbare huidverandering die alleen in kleur verschilt (een 'vlek').","definition":"<p>Een <b>macula</b> is een plat, met de vinger niet-voelbaar plekje dat zich alleen door kleur onderscheidt van de omgeving.</p><p>Voorbeelden zijn een sproet of een café-au-lait-vlek. Wordt hij groter dan ~1 cm, dan spreekt men van een patch.</p>","image_url":"","wiki_title":"Skin condition","match":"macula|maculae"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"pustula":{"title":"Pustula","short":"Met pus gevuld blaasje in de huid (een 'puistje').","definition":"<p>Een <b>pustula</b> (pustel) is een verheven blaasje gevuld met pus (dode neutrofielen).</p><p>Pustels kunnen steriel zijn (psoriasis pustulosa) of door bacteriën ontstaan; ze zijn kenmerkend voor acne.</p>","image_url":"","wiki_title":"Pustule","match":"pustula|pustel|pustels|pustula|pustulae"},"crusta":{"title":"Crusta","short":"Korstje van ingedroogd wondvocht, bloed of pus op het huidoppervlak.","definition":"<p>Een <b>crusta</b> (korst) is opgedroogd exsudaat — wondvocht, bloed of pus — op de huid.</p><p>Het is een secundaire efflorescentie die ontstaat nadat een blaasje of wondje is opengegaan.</p>","image_url":"","wiki_title":"Crust (dermatology)","match":"crusta|crustae|korst"},"squama":{"title":"Squama","short":"Zichtbare hoornschilfer door versnelde of gestoorde verhoorning van de opperhuid.","definition":"<p>Een <b>squama</b> (schilfer) is een loskomend plaatje hoorncellen van het stratum corneum.</p><p>Overmatige schilfering is typerend voor psoriasis en ichthyosis.</p>","image_url":"","wiki_title":"Desquamation","match":"squama|squamae|schilfer|schilfering"},"erosie":{"title":"Erosie","short":"Oppervlakkig huiddefect beperkt tot de epidermis, dat zonder litteken geneest.","definition":"<p>Een <b>erosie</b> is een oppervlakkig verlies van epidermis, bijvoorbeeld nadat een blaasje is opengegaan.</p><p>Omdat de dermis intact blijft, geneest een erosie zonder litteken.</p>","image_url":"","wiki_title":"Erosion (dermatology)","match":"erosie|erosies"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"basaalcelcarcinoom":{"title":"Basaalcelcarcinoom","short":"Meest voorkomende, langzaam groeiende huidkanker die vrijwel nooit uitzaait.","definition":"<p>Het <b>basaalcelcarcinoom</b> is de meest voorkomende vorm van huidkanker, uitgaand van de basale keratinocyten. Het groeit langzaam en zaait vrijwel nooit uit, maar kan lokaal in de diepte woekeren.</p><p>Typisch is een glanzend, huidkleurig knobbeltje met teleangiëctasieën, vaak in het gezicht na jarenlange zonschade.</p>","image_url":"","wiki_title":"Basal-cell carcinoma","match":"basaalcelcarcinoom|basaalcel carcinoom|basaalcelcarinoom|basaalcarcinoom"},"melanoom":{"title":"Melanoom","short":"Kwaadaardige tumor van melanocyten; relatief zeldzaam maar het gevaarlijkst door vroege uitzaaiing.","definition":"<p>Het <b>melanoom</b> is een kwaadaardige tumor van de pigmentcellen (melanocyten).</p><p>Het is de dodelijkste huidkanker omdat het vroeg kan uitzaaien. De ABCDE-regel (Asymmetrie, Begrenzing, Kleur, Diameter, Evolutie) helpt bij herkenning; de Breslowdikte bepaalt de prognose.</p>","image_url":"","wiki_title":"Melanoma","match":"melanoom|melanomen"},"teleangiectasie":{"title":"Teleangiëctasie","short":"Blijvend verwijde, met het blote oog zichtbare kleine bloedvaatjes in de huid.","definition":"<p>Een <b>teleangiëctasie</b> is een permanent verwijd klein bloedvaatje dat als een fijn rood lijntje zichtbaar is en met een glaasje weg te drukken is.</p><p>Ze komen voor bij rosacea, na langdurig corticosteroïdgebruik, bij zonschade en als kenmerk van het basaalcelcarcinoom.</p>","image_url":"","wiki_title":"Telangiectasia","match":"teleangiectasie|teleangiëctasie|telangiëctasie|telangiectasie"},"cryotherapie":{"title":"Cryotherapie","short":"Bevriezen van huidafwijkingen met vloeibare stikstof, o.a. bij wratten en actinische keratose.","definition":"<p><b>Cryotherapie</b> (cryochirurgie) vernietigt weefsel door het te bevriezen, meestal met vloeibare stikstof (−196 °C).</p><p>De ijskristallen doden de cellen. Het wordt gebruikt bij wratten, actinische keratosen en sommige oppervlakkige huidtumoren.</p>","image_url":"","wiki_title":"Cryotherapy","match":"cryotherapie|cryochirurgie|cryotherapie/cryochirurgie"},"excisie":{"title":"Excisie","short":"Chirurgisch wegsnijden van een huidafwijking, meestal met een marge gezond weefsel.","definition":"<p>Een <b>excisie</b> is het operatief wegsnijden van een laesie, doorgaans met een randje gezonde huid (marge).</p><p>Bij een diagnostische excisie wordt de hele afwijking verwijderd voor onderzoek; bij huidkanker is de marge afhankelijk van het type en de dikte.</p>","image_url":"","wiki_title":"Wide local excision","match":"excisie|diagnostische excisie"},"radiotherapie":{"title":"Radiotherapie","short":"Behandeling met ioniserende straling die het DNA van tumorcellen beschadigt.","definition":"<p><b>Radiotherapie</b> (bestraling) gebruikt ioniserende straling om het DNA van kankercellen zodanig te beschadigen dat ze afsterven.</p><p>In de dermatologie is het een alternatief voor chirurgie bij bijvoorbeeld basaal- en plaveiselcelcarcinomen, vooral bij oudere patiënten of moeilijke locaties.</p>","image_url":"","wiki_title":"Radiation therapy","match":"radiotherapie"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"autosomaal recessief":{"title":"Autosomaal recessief","short":"Overervingspatroon waarbij twee afwijkende genen nodig zijn voor ziekte; dragers zijn gezond.","definition":"<p>Bij <b>autosomaal recessieve</b> overerving moeten beide allelen van een autosomaal gen gemuteerd zijn voor ziekte.</p><p>Dragers met één mutatie zijn gezond; twee dragers hebben 25% kans op een aangedaan kind. De aandoening slaat vaak generaties over.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal recessief"},"puntmutatie":{"title":"Puntmutatie","short":"Verandering van één enkele DNA-base.","definition":"<p>Een <b>puntmutatie</b> is de vervanging, invoeging of verwijdering van één enkele base in het DNA.</p><p>Afhankelijk van het effect op het codon spreekt men van een stille, missense of nonsense mutatie.</p>","image_url":"","wiki_title":"Point mutation","match":"puntmutatie"},"frameshift mutatie":{"title":"Frameshift-mutatie","short":"Invoeging of verwijdering van basen die het leesraam verschuift, waardoor alle volgende codons veranderen.","definition":"<p>Een <b>frameshift-mutatie</b> ontstaat als een aantal basen (niet deelbaar door drie) wordt toegevoegd of verwijderd.</p><p>Daardoor verschuift het leesraam en veranderen alle codons erna, meestal met een sterk afwijkend, verkort eiwit tot gevolg.</p>","image_url":"","wiki_title":"Frameshift mutation","match":"frameshift mutatie|frameshift-mutatie"},"candida albicans":{"title":"Candida albicans","short":"Candida albicans is een gist die normaal op slijmvliezen voorkomt en bij verminderde weerstand spruw, vaginale schimmelinfectie of invasieve infecties geeft.","definition":"<p><strong><em>Candida albicans</em></strong> is een gist (schimmel) die bij veel mensen in mond, darm en vagina voorkomt. Hij kan zowel als ronde gistcel als met (pseudo)hyfen groeien.</p><p>Bij een verstoorde flora (antibiotica) of verminderde afweer veroorzaakt hij oppervlakkige infecties zoals spruw (orale candidiasis), vaginale candidiasis en intertrigo. Bij ernstig immuungecompromitteerden of patiënten met lijnen kan een invasieve candidemie ontstaan.</p>","image_url":"","wiki_title":"Candida albicans","match":"candida albicans|c. albicans|candida","option_only":true},"adenovirus":{"title":"Adenovirus","short":"Adenovirussen zijn niet-omhulde DNA-virussen die verkoudheid, keelontsteking, conjunctivitis en gastro-enteritis veroorzaken.","definition":"<p><strong>Adenovirussen</strong> zijn niet-omhulde, dubbelstrengs DNA-virussen. Omdat ze geen envelop hebben, zijn ze stabiel in de omgeving en lastig te inactiveren.</p><p>Ze veroorzaken vooral bij kinderen infecties van de bovenste luchtwegen (faryngitis), conjunctivitis (o.a. faryngoconjunctivale koorts), gastro-enteritis en soms pneumonie. Ze worden ook gebruikt als vector in vaccins en gentherapie.</p>","image_url":"","wiki_title":"Adenoviridae","match":"adenovirus|adenovirussen","option_only":true},"poliomyelitis":{"title":"Poliomyelitis","short":"Polio is een virale infectie (poliovirus, enterovirus) die bij een klein deel van de patiënten motorische voorhoorncellen beschadigt en slappe verlamming geeft.","definition":"<p><strong>Poliomyelitis</strong> wordt veroorzaakt door het poliovirus, een niet-omhuld RNA-enterovirus dat fecaal-oraal wordt overgedragen.</p><p>De meeste infecties verlopen zonder of met milde klachten. Bij een klein deel infecteert het virus de motorische <em>voorhoorncellen</em> van het ruggenmerg, met asymmetrische slappe verlamming zonder gevoelsverlies. Door vaccinatie (DKTP) is polio in Nederland vrijwel verdwenen.</p>","image_url":"","wiki_title":"Polio","match":"poliomyelitis|polio|poliovirus","option_only":true},"cytomegalovirus":{"title":"Cytomegalovirus (CMV)","short":"CMV is een herpesvirus dat bij gezonden mild verloopt, maar gevaarlijk is bij immuungecompromitteerden en de belangrijkste congenitale virale infectie is.","definition":"<p>Het <strong>cytomegalovirus</strong> is een herpesvirus (HHV-5) dat na infectie levenslang latent aanwezig blijft. Geïnfecteerde cellen worden groot met kenmerkende ‘uilenoog’-inclusies.</p><p>Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleosebeeld. Bij transplantatie- en hiv-patiënten kan CMV retinitis, pneumonie en colitis veroorzaken. Congenitale CMV is de belangrijkste infectieuze oorzaak van aangeboren doofheid en ontwikkelingsachterstand.</p>","image_url":"","wiki_title":"Cytomegalovirus","match":"cytomegalovirus|cmv","option_only":true},"meningitis":{"title":"Meningitis","short":"Meningitis is een ontsteking van de hersenvliezen, met hoofdpijn, koorts, nekstijfheid en verminderd bewustzijn; bacteriële meningitis is een spoedgeval.","definition":"<p><strong>Meningitis</strong> is een ontsteking van de leptomeningen (pia en arachnoidea) en de liquor. Oorzaken zijn bacteriën (bij volwassenen vooral pneumokok en meningokok), virussen (vaak milder) en zelden schimmels.</p><p>Klassieke symptomen: hoofdpijn, koorts, nekstijfheid en een verlaagd bewustzijn; bij meningokokken soms petechiën. Diagnose via lumbaalpunctie (liquoronderzoek). Bacteriële meningitis vereist direct antibiotica en dexamethason.</p>","image_url":"","wiki_title":"Meningitis","match":"meningitis|hersenvliesontsteking|bacteriële meningitis","option_only":true},"endocarditis":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"endocarditis|infectieuze endocarditis|bacteriële endocarditis","option_only":true},"amoxicilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxicilline|amoxicillin","option_only":true},"metoprolol":{"title":"Metoprolol","short":"Metoprolol is een cardioselectieve bètablokker (β1) die hartfrequentie en contractiekracht verlaagt; gebruikt bij hypertensie, angina pectoris en hartfalen.","definition":"<p><strong>Metoprolol</strong> is een <em>β1-selectieve</em> bètablokker. Door blokkade van β1-receptoren in het hart dalen hartfrequentie, contractiliteit en geleidingssnelheid in de AV-knoop; in de nier remt het de reninesecretie.</p><p>Indicaties: hypertensie, angina pectoris, na een myocardinfarct, hartfalen en ritmestoornissen (frequentiecontrole). Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten. Bij hoge doses verdwijnt de selectiviteit en kan bronchoconstrictie optreden.</p>","image_url":"","wiki_title":"Metoprolol","match":"metoprolol","option_only":true},"hydrochloorthiazide":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"hydrochloorthiazide|hctz|thiazide|thiazidediureticum|thiazide diureticum|hydrochloortiazide","option_only":true},"paracetamol":{"title":"Paracetamol","short":"Paracetamol is een pijnstiller en koortsverlager zonder relevante ontstekingsremmende werking; bij overdosering levertoxisch.","definition":"<p><strong>Paracetamol</strong> werkt pijnstillend en koortsverlagend, vermoedelijk via remming van prostaglandinesynthese in het centrale zenuwstelsel. Perifeer is het nauwelijks ontstekingsremmend en het remt de bloedplaatjes niet.</p><p>Het is bij gewone dosering veilig en daarom eerste stap van de pijnladder. Bij overdosering raakt glutathion in de lever uitgeput en hoopt de toxische metaboliet NAPQI zich op, met levernecrose; het antidotum is acetylcysteïne.</p>","image_url":"","wiki_title":"Paracetamol","match":"paracetamol|acetaminofen","option_only":true},"metformine":{"title":"Metformine","short":"Metformine is het eerstekeusmiddel bij diabetes mellitus type 2; het remt vooral de glucoseproductie door de lever.","definition":"<p><strong>Metformine</strong> is een biguanide dat de <em>gluconeogenese in de lever</em> remt en de insulinegevoeligheid van spier verbetert. Het stimuleert de insulineafgifte niet en geeft daarom op zichzelf geen hypoglykemie.</p><p>Het is eerste keus bij diabetes type 2 en is gewichtsneutraal. Bijwerkingen zijn vooral maag-darmklachten; zeldzaam is lactaatacidose (risico bij ernstige nierfunctiestoornis). Langdurig gebruik kan vitamine B12-tekort geven.</p>","image_url":"","wiki_title":"Metformin","match":"metformine|metformin","option_only":true},"prednison":{"title":"Prednison / prednisolon","short":"Prednison(olon) is een synthetisch glucocorticoïd met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p><strong>Prednison</strong> is een prodrug die in de lever wordt omgezet in het actieve <strong>prednisolon</strong>. Beide zijn synthetische <em>glucocorticoïden</em>: ze binden aan de intracellulaire glucocorticoïdreceptor en veranderen de gentranscriptie.</p><p>Daardoor remmen ze de vorming van allerlei ontstekingsmediatoren en de activatie van ontstekingscellen. Gebruikt bij astma/COPD-exacerbaties, auto-immuunziekten en allergieën. Bijwerkingen bij langdurig gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infectierisico en bijnierschorsremming.</p>","image_url":"","wiki_title":"Prednisolone","match":"prednison|prednisolon|prednisone|prednisolone","option_only":true},"chemotherapie":{"title":"Chemotherapie","short":"Chemotherapie is behandeling met cytostatica: medicijnen die snel delende (kanker)cellen doden of hun deling remmen.","definition":"<p><strong>Chemotherapie</strong> is behandeling met <em>cytostatica</em>. Deze grijpen in op de celdeling, bijvoorbeeld door DNA te beschadigen (alkylerende middelen, platinaverbindingen), de DNA-synthese te remmen (antimetabolieten) of de mitosespoel te verstoren (taxanen, vinca-alkaloïden).</p><p>Omdat ook gezonde, snel delende cellen geraakt worden, zijn bijwerkingen beenmergsuppressie, haaruitval, mucositis en misselijkheid. Chemotherapie kan curatief, (neo)adjuvant of palliatief worden ingezet.</p>","image_url":"","wiki_title":"Chemotherapy","match":"chemotherapie|chemo|cytostatica","option_only":true},"acetylcholine":{"title":"Acetylcholine","short":"Acetylcholine is de neurotransmitter van de neuromusculaire overgang, van alle autonome ganglia en van het parasympathische zenuwstelsel.","definition":"<p><strong>Acetylcholine</strong> wordt gemaakt uit choline en acetyl-CoA en na afgifte snel afgebroken door <em>acetylcholinesterase</em>.</p><p>Het werkt op <em>nicotinerge</em> receptoren (ionkanalen: neuromusculaire eindplaat, autonome ganglia, bijniermerg) en <em>muscarinerge</em> receptoren (G-eiwitgekoppeld: doelorganen van het parasympathicus en de zweetklieren). Centraal speelt het een rol bij aandacht en geheugen; bij de ziekte van Alzheimer is er een cholinerg tekort.</p>","image_url":"","wiki_title":"Acetylcholine","match":"acetylcholine|ach","option_only":true},"serotonine":{"title":"Serotonine","short":"Serotonine (5-HT) is een monoamine uit tryptofaan; neurotransmitter voor stemming, slaap en eetlust en in de darm en bloedplaatjes actief.","definition":"<p><strong>Serotonine</strong> (5-hydroxytryptamine) wordt gemaakt uit het aminozuur <em>tryptofaan</em>. Het meeste zit in enterochromaffiene cellen van de darm en wordt in bloedplaatjes opgeslagen.</p><p>In het brein komen serotonerge neuronen uit de raphekernen van de hersenstam; ze beïnvloeden stemming, angst, slaap, eetlust en pijn. SSRI's remmen de heropname en worden bij depressie en angststoornissen gebruikt. In de darm stimuleert serotonine de motiliteit; perifeer veroorzaakt het vasoconstrictie of -dilatatie afhankelijk van het vaatbed.</p>","image_url":"","wiki_title":"Serotonin","match":"serotonine|5-ht|5-hydroxytryptamine|serotonin","option_only":true},"foliumzuur":{"title":"Foliumzuur","short":"Foliumzuur (vitamine B11/B9) is nodig voor DNA-synthese; tekort geeft megaloblastaire anemie en verhoogt het risico op een neuralebuisdefect.","definition":"<p><strong>Foliumzuur</strong> (folaat) is als tetrahydrofolaat een drager van één-koolstofgroepen, nodig voor de synthese van purines en thymidine en dus voor <em>DNA-synthese</em> en celdeling.</p><p>Tekort geeft een <em>megaloblastaire (macrocytaire) anemie</em>. Een tekort rond de conceptie verhoogt het risico op neuralebuisdefecten (spina bifida); daarom wordt vrouwen met kinderwens aangeraden vanaf 4 weken voor de conceptie tot 10 weken zwangerschap foliumzuur te slikken.</p>","image_url":"","wiki_title":"Folate","match":"foliumzuur|folaat|vitamine b11|vitamine b9","option_only":true},"vitamine b1":{"title":"Vitamine B1 (thiamine)","short":"Thiamine is een cofactor voor o.a. pyruvaatdehydrogenase; tekort (vaak bij alcoholisme) geeft beriberi en Wernicke-encefalopathie.","definition":"<p><strong>Thiamine</strong> (vitamine B1) is als thiaminepyrofosfaat cofactor van enzymen in het koolhydraatmetabolisme, zoals <em>pyruvaatdehydrogenase</em>, α-ketoglutaraatdehydrogenase en transketolase.</p><p>Tekort komt vooral voor bij alcoholmisbruik en ondervoeding. Het geeft <em>beriberi</em> (neuropathie, hartfalen) en de <em>Wernicke-encefalopathie</em> (verwardheid, ataxie, oogbewegingsstoornissen), eventueel gevolgd door het syndroom van Korsakov. Geef thiamine vóór glucose bij een risicopatiënt.</p>","image_url":"","wiki_title":"Thiamine","match":"vitamine b1|thiamine|thiamine (vitamine b1)","option_only":true},"vitamine b6":{"title":"Vitamine B6 (pyridoxine)","short":"Vitamine B6 is als pyridoxaalfosfaat cofactor bij het aminozuurmetabolisme en de synthese van neurotransmitters en heem.","definition":"<p><strong>Vitamine B6</strong> (pyridoxine) wordt omgezet in <em>pyridoxaalfosfaat</em>, de cofactor van transaminasen en decarboxylasen. Het is nodig voor het aminozuurmetabolisme, de synthese van neurotransmitters (GABA, serotonine, dopamine) en van heem.</p><p>Tekort is zeldzaam en kan optreden bij gebruik van isoniazide; het geeft perifere neuropathie, glossitis en een sideroblastaire anemie. Overdosering geeft eveneens neuropathie.</p>","image_url":"","wiki_title":"Vitamin B6","match":"vitamine b6|pyridoxine|pyridoxaalfosfaat","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"roken":{"title":"Roken","short":"Roken is de belangrijkste vermijdbare oorzaak van ziekte en sterfte: het veroorzaakt o.a. longkanker, COPD en hart- en vaatziekten.","definition":"<p>Tabaksrook bevat nicotine (verslavend), koolmonoxide, teer en tientallen kankerverwekkende stoffen. <strong>Roken</strong> beschadigt het luchtwegepitheel en het endotheel en bevordert ontsteking en trombose.</p><p>Het is een hoofdoorzaak van longkanker en andere kankers (o.a. mond, slokdarm, blaas), COPD, atherosclerose (myocardinfarct, CVA, perifeer arterieel vaatlijden) en complicaties in de zwangerschap. Stoppen loont op elke leeftijd.</p>","image_url":"","wiki_title":"Tobacco smoking","match":"roken|tabaksgebruik|tabak","option_only":true},"n. musculocutaneus":{"title":"N. musculocutaneus","short":"De n. musculocutaneus (C5–C7) innerveert de flexoren van de bovenarm (m. biceps, m. brachialis, m. coracobrachialis) en de huid van de laterale onderarm.","definition":"<p>De <strong>n. musculocutaneus</strong> komt uit de fasciculus lateralis van de plexus brachialis (C5–C7). Hij doorboort de m. coracobrachialis en loopt tussen de m. biceps brachii en de m. brachialis.</p><p>Motorisch innerveert hij de voorste spiergroep van de bovenarm: <em>m. coracobrachialis, m. biceps brachii en m. brachialis</em> (flexie in de elleboog, supinatie). Zijn sensibele eindtak (n. cutaneus antebrachii lateralis) verzorgt de huid van de laterale onderarm.</p>","image_url":"","wiki_title":"Musculocutaneous nerve","match":"n. musculocutaneus|nervus musculocutaneus|n musculocutaneus","option_only":true},"n. axillaris":{"title":"N. axillaris","short":"De n. axillaris (C5–C6) innerveert de m. deltoideus en m. teres minor en de huid over de deltoideus; kwetsbaar bij een schouderluxatie of collum chirurgicum-fractuur.","definition":"<p>De <strong>n. axillaris</strong> ontspringt uit de fasciculus posterior van de plexus brachialis (C5–C6). Hij loopt door de laterale okselspleet (spatium quadrangulare) samen met de a. circumflexa humeri posterior, rond het collum chirurgicum van de humerus.</p><p>Hij innerveert de <em>m. deltoideus</em> (abductie van de arm voorbij ±15°) en de <em>m. teres minor</em> (exorotatie), en sensibel de huid over het onderste deel van de deltoideus (‘regimental badge area’). Letsel bij schouderluxatie of fractuur van het collum chirurgicum.</p>","image_url":"","wiki_title":"Axillary nerve","match":"n. axillaris|nervus axillaris|n axillaris","option_only":true},"n. ulnaris":{"title":"N. ulnaris","short":"De n. ulnaris (C8–T1) loopt achter de epicondylus medialis (‘telefoonbotje’) en innerveert de meeste intrinsieke handspieren en de huid van de pink.","definition":"<p>De <strong>n. ulnaris</strong> komt uit de fasciculus medialis van de plexus brachialis (C8–T1). Hij loopt achter de epicondylus medialis van de humerus door de sulcus nervi ulnaris en via het kanaal van Guyon naar de hand.</p><p>In de onderarm innerveert hij de m. flexor carpi ulnaris en het ulnaire deel van de m. flexor digitorum profundus; in de hand de meeste intrinsieke spieren (mm. interossei, hypothenar, mm. lumbricales III–IV, m. adductor pollicis). Sensibel: de pink en ulnaire helft van de ringvinger. Uitval geeft een klauwhand en een positief teken van Froment.</p>","image_url":"","wiki_title":"Ulnar nerve","match":"n. ulnaris|nervus ulnaris|n ulnaris","option_only":true},"n. radialis":{"title":"N. radialis","short":"De n. radialis (C5–T1) innerveert alle extensoren van boven- en onderarm; letsel (bijv. bij een humerusschachtfractuur) geeft een dropshand.","definition":"<p>De <strong>n. radialis</strong> is de grootste tak van de fasciculus posterior van de plexus brachialis (C5–T1). Hij loopt in de sulcus nervi radialis spiraalsgewijs om de achterkant van de humerusschacht.</p><p>Motorisch innerveert hij de <em>extensoren</em>: m. triceps brachii, m. brachioradialis, en via de r. profundus de extensoren van pols en vingers en de m. supinator. Sensibel verzorgt hij de achterzijde van arm en onderarm en de dorsale zijde van de radiale hand (eerste webspace). Letsel geeft een <em>dropshand</em>.</p>","image_url":"","wiki_title":"Radial nerve","match":"n. radialis|nervus radialis|n radialis","option_only":true},"n. suprascapularis":{"title":"N. suprascapularis","short":"De n. suprascapularis (C5–C6) innerveert de m. supraspinatus en m. infraspinatus.","definition":"<p>De <strong>n. suprascapularis</strong> komt uit de truncus superior van de plexus brachialis (C5–C6). Hij loopt over de schouder naar dorsaal en gaat door de incisura scapulae onder het lig. transversum scapulae superius.</p><p>Hij innerveert twee spieren van de rotator cuff: de <em>m. supraspinatus</em> (start van abductie) en de <em>m. infraspinatus</em> (exorotatie), en geeft sensibele takjes aan het schoudergewricht.</p>","image_url":"","wiki_title":"Suprascapular nerve","match":"n. suprascapularis|nervus suprascapularis","option_only":true},"hersenstam":{"title":"Hersenstam","short":"De hersenstam (mesencephalon, pons, medulla oblongata) verbindt grote hersenen en ruggenmerg en bevat kernen van hersenzenuwen en centra voor ademhaling en circulatie.","definition":"<p>De <strong>hersenstam</strong> bestaat uit het mesencephalon (middenhersenen), de pons en de medulla oblongata. Alle opstijgende en afdalende banen tussen hersenen en ruggenmerg lopen erdoorheen.</p><p>Hij bevat de kernen van de hersenzenuwen III–XII, de formatio reticularis (bewustzijn, slaap-waakritme) en vitale centra voor ademhaling en hart- en vaatregulatie. Uitval van de hersenstam is daardoor snel levensbedreigend; hersenstamreflexen worden getest bij de vaststelling van hersendood.</p>","image_url":"","wiki_title":"Brainstem","match":"hersenstam|truncus cerebri|truncus encephali","option_only":true},"hypothalamus":{"title":"Hypothalamus","short":"De hypothalamus is het regelcentrum van de homeostase: hij stuurt hypofyse, autonoom zenuwstelsel, temperatuur, honger, dorst en circadiaan ritme.","definition":"<p>De <strong>hypothalamus</strong> is een klein deel van het diencephalon, onder de thalamus en rond de derde ventrikel. Hij is via het infundibulum verbonden met de hypofyse.</p><p>Hij maakt releasing- en inhibiting-hormonen (o.a. TRH, CRH, GnRH, GHRH, dopamine) die via het portale systeem de voorkwab sturen, en ADH en oxytocine die in de achterkwab worden afgegeven. Daarnaast regelt hij lichaamstemperatuur, honger en verzadiging, dorst, het slaap-waakritme (nucleus suprachiasmaticus) en het autonome zenuwstelsel.</p>","image_url":"","wiki_title":"Hypothalamus","match":"hypothalamus","option_only":true},"thalamus":{"title":"Thalamus","short":"De thalamus is het grote schakelstation in het diencephalon: vrijwel alle sensorische informatie (behalve reuk) wordt hier verwerkt op weg naar de cortex.","definition":"<p>De <strong>thalamus</strong> is een paarige, eivormige kern in het diencephalon aan weerszijden van de derde ventrikel. Hij bestaat uit veel subkernen met elk een eigen corticale projectie.</p><p>Sensorische banen (somatosensoriek via de VPL/VPM, zien via het corpus geniculatum laterale, horen via het corpus geniculatum mediale) schakelen hier om naar de cortex. Ook motorische lussen van basale kernen en cerebellum lopen via de thalamus, en hij speelt een rol bij bewustzijn en aandacht.</p>","image_url":"","wiki_title":"Thalamus","match":"thalamus","option_only":true},"globus pallidus pars externa":{"title":"Globus pallidus pars externa (GPe)","short":"De GPe is onderdeel van de basale kernen en vormt een schakel in de indirecte route; hij remt de nucleus subthalamicus.","definition":"<p>De <strong>globus pallidus pars externa</strong> is het laterale deel van de globus pallidus. Hij ontvangt remmende (GABA-erge) input van het striatum en stuurt zelf remmende projecties naar de nucleus subthalamicus.</p><p>Hij is een kernschakel van de <em>indirecte route</em> van de basale kernen (cortex → striatum → GPe → nucleus subthalamicus → GPi/SNr → thalamus), die beweging per saldo afremt.</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus pars externa|gpe|globus pallidus externus|globus pallidus externa","option_only":true},"globus pallidus pars interna":{"title":"Globus pallidus pars interna (GPi)","short":"De GPi is de belangrijkste uitgangskern van de basale kernen; hij remt (GABA-erg) de motorische thalamus.","definition":"<p>De <strong>globus pallidus pars interna</strong> is samen met de substantia nigra pars reticulata de <em>uitgangskern</em> van de basale kernen. Hij geeft tonisch remmende GABA-erge output naar de motorische kernen van de thalamus.</p><p>De directe route (striatum → GPi) remt de GPi en ontremt zo de thalamus (meer beweging); de indirecte route versterkt via de nucleus subthalamicus juist de remming. De GPi is een doelwit bij diepe hersenstimulatie (o.a. dystonie, Parkinson).</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus pars interna|gpi|globus pallidus internus|globus pallidus interna","option_only":true},"nucleus subthalamicus":{"title":"Nucleus subthalamicus","short":"De nucleus subthalamicus is een exciterende (glutamaterge) kern van de basale kernen in de indirecte route; laesie geeft hemiballisme.","definition":"<p>De <strong>nucleus subthalamicus</strong> ligt onder de thalamus, boven de substantia nigra. Het is de enige <em>exciterende</em> (glutamaterge) kern van de basale kernen.</p><p>Hij ontvangt remmende input van de GPe en prikkelt de GPi en substantia nigra pars reticulata, waardoor de thalamus sterker geremd wordt (indirecte route). Een laesie (bijv. een lacunair infarct) geeft contralateraal <em>hemiballisme</em>. Het is ook een doelwit voor diepe hersenstimulatie bij de ziekte van Parkinson.</p>","image_url":"","wiki_title":"Subthalamic nucleus","match":"nucleus subthalamicus|stn|subthalamische kern","option_only":true},"aquaductus cerebri":{"title":"Aquaductus cerebri","short":"De aquaductus cerebri is het nauwe kanaal in het mesencephalon dat de derde en vierde ventrikel verbindt.","definition":"<p>De <strong>aquaductus cerebri</strong> (van Sylvius) loopt door het mesencephalon en verbindt de <em>derde ventrikel</em> met de <em>vierde ventrikel</em>. Eromheen ligt de periaqueductale grijze stof.</p><p>Omdat hij zo nauw is, is het een typische plek voor obstructie (bijv. aangeboren stenose of een tumor in de pijnappelklierregio). Dat geeft een niet-communicerende hydrocephalus met verwijding van de laterale en derde ventrikels.</p>","image_url":"","wiki_title":"Cerebral aqueduct","match":"aquaductus cerebri|aqueductus cerebri|aquaduct van sylvius|aqueduct van sylvius","option_only":true},"laterale ventrikels":{"title":"Laterale ventrikels","short":"De laterale ventrikels zijn de twee grootste liquorholtes, één in elke hersenhelft; ze staan via de foramina van Monro in verbinding met de derde ventrikel.","definition":"<p>De <strong>laterale ventrikels</strong> liggen in de beide hemisferen van het telencephalon en hebben een C-vorm met een voorhoorn, lichaam, achterhoorn en onderhoorn (in de temporaalkwab).</p><p>Ze bevatten plexus choroideus, die liquor produceert. Via de foramina interventricularia (Monro) stroomt de liquor naar de derde ventrikel, daarna via de aquaductus naar de vierde ventrikel en de subarachnoïdale ruimte.</p>","image_url":"","wiki_title":"Lateral ventricles","match":"laterale ventrikels|laterale ventrikel|ventriculi laterales|zijventrikels","option_only":true},"canalis centralis":{"title":"Canalis centralis","short":"De canalis centralis is het smalle, met ependym beklede kanaal in het midden van het ruggenmerg; de voortzetting van de vierde ventrikel.","definition":"<p>De <strong>canalis centralis</strong> loopt door het midden van de grijze stof van het ruggenmerg en is een restant van het lumen van de neurale buis. Het is bekleed met ependymcellen en sluit aan op de vierde ventrikel.</p><p>Bij volwassenen is het kanaal vaak deels dichtgegroeid. Een abnormale verwijding heet hydromyelie; een holte in het ruggenmerg (syringomyelie) kan kruisende pijn- en temperatuurvezels beschadigen.</p>","image_url":"","wiki_title":"Central canal","match":"canalis centralis|centraal kanaal|centrale kanaal","option_only":true},"n. oculomotorius":{"title":"N. oculomotorius (III)","short":"De n. oculomotorius (III) innerveert de meeste uitwendige oogspieren, de ooglidheffer en (parasympathisch) de pupilvernauwer en accommodatie.","definition":"<p>De <strong>n. oculomotorius</strong> komt uit het mesencephalon en innerveert de m. rectus superior, inferior en medialis, de m. obliquus inferior en de m. levator palpebrae superioris.</p><p>Parasympathische vezels (uit de kern van Edinger-Westphal, schakeling in het ganglion ciliare) innerveren de m. sphincter pupillae (miosis) en de m. ciliaris (accommodatie). Uitval geeft een oog dat naar buiten-onder staat, ptosis en een wijde, lichtstijve pupil.</p>","image_url":"","wiki_title":"Oculomotor nerve","match":"n. oculomotorius|nervus oculomotorius|n. iii|hersenzenuw iii","option_only":true},"n. trochlearis":{"title":"N. trochlearis (IV)","short":"De n. trochlearis (IV) innerveert alleen de m. obliquus superior; hij is de enige hersenzenuw die dorsaal uit de hersenstam treedt.","definition":"<p>De <strong>n. trochlearis</strong> is de dunste hersenzenuw en de enige die aan de <em>dorsale</em> zijde van de hersenstam uittreedt (onder de colliculi inferiores) en kruist.</p><p>Hij innerveert de <em>m. obliquus superior</em>, die het oog vooral naar beneden draait als het naar binnen kijkt, en intorsie geeft. Uitval geeft verticale dubbelbeelden, vooral bij naar beneden kijken (traplopen, lezen), met compenserende hoofdkanteling naar de gezonde kant.</p>","image_url":"","wiki_title":"Trochlear nerve","match":"n. trochlearis|nervus trochlearis|n. iv|hersenzenuw iv","option_only":true},"arteria cerebri anterior":{"title":"A. cerebri anterior","short":"De a. cerebri anterior voorziet de mediale zijde van frontaal- en pariëtaalkwab; een infarct geeft vooral uitval van het contralaterale been.","definition":"<p>De <strong>a. cerebri anterior</strong> is een eindtak van de a. carotis interna. Beide aa. cerebri anteriores zijn verbonden via de a. communicans anterior (cirkel van Willis) en lopen over het corpus callosum naar achteren.</p><p>Zij verzorgen de mediale oppervlakte van de frontaal- en pariëtaalkwab, inclusief het deel van de motorische en sensorische cortex voor <em>been en voet</em>. Een infarct geeft daardoor vooral een contralaterale parese en gevoelsstoornis van het been, soms met gedragsveranderingen en incontinentie.</p>","image_url":"","wiki_title":"Anterior cerebral artery","match":"arteria cerebri anterior|a. cerebri anterior|aca","option_only":true},"oligodendroglioom":{"title":"Oligodendroglioom","short":"Een oligodendroglioom is een diffuus gliaal hersentumor van oligodendrogliale oorsprong, met 1p/19q-codeletie; vaak presentatie met epilepsie.","definition":"<p>Een <strong>oligodendroglioom</strong> is een diffuus infiltrerend glioom met als moleculaire kenmerken een <em>IDH-mutatie</em> en <em>codeletie van 1p/19q</em>. Het komt vooral voor bij volwassenen, meestal in de frontaalkwab.</p><p>Patiënten presenteren zich vaak met epileptische aanvallen. Microscopisch hebben de cellen een rond kern met een helder perinucleair halo (‘gebakken ei’). De prognose is relatief gunstig vergeleken met andere diffuse gliomen.</p>","image_url":"","wiki_title":"Oligodendroglioma","match":"oligodendroglioom|oligodendrogliomen","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"allergie":{"title":"Allergie","short":"Een allergie is een overdreven immuunreactie op een onschuldige stof (allergeen), klassiek IgE-gemedieerd: een type I-overgevoeligheidsreactie.","definition":"<p>Bij een <strong>allergie</strong> reageert het immuunsysteem op een onschadelijk antigeen, zoals pollen, huisstofmijt of voedsel. Bij de eerste blootstelling ontstaat <em>sensibilisatie</em>: B-cellen maken onder invloed van Th2-cellen IgE, dat zich aan mestcellen bindt.</p><p>Bij herblootstelling binden allergenen dat IgE, waardoor mestcellen histamine, leukotriënen en prostaglandinen afgeven (type I-reactie): niezen, jeuk, urticaria, astma of anafylaxie. Een late fase met eosinofielen kan volgen.</p>","image_url":"","wiki_title":"Allergy","match":"allergie|allergische reactie|type i-overgevoeligheid","option_only":true},"psoriasis vulgaris":{"title":"Psoriasis vulgaris","short":"Psoriasis is een chronische ontstekingsziekte van de huid met scherp begrensde rode plaques met zilverwitte schilfers, vaak op ellebogen, knieën en hoofdhuid.","definition":"<p>Bij <strong>psoriasis vulgaris</strong> stimuleert een T-cel-gemedieerde ontsteking (o.a. de IL-23/Th17-as) een sterk versnelde deling en onvolledige verhoorning van keratinocyten.</p><p>Dat geeft scherp begrensde, erythemateuze plaques met <em>zilverwitte schilfering</em>, typisch op de strekzijden (ellebogen, knieën), de hoofdhuid en de bilnaad. Kenmerkend zijn het köbnerfenomeen en nagelafwijkingen (putjes, olievlekken). Een deel van de patiënten ontwikkelt artritis psoriatica.</p>","image_url":"","wiki_title":"Psoriasis","match":"psoriasis vulgaris|psoriasis","option_only":true},"inclusion body myositis":{"title":"Inclusion body myositis","short":"Inclusion body myositis is een langzaam progressieve spierziekte bij ouderen, met typisch zwakte van de vingerbuigers en de m. quadriceps.","definition":"<p><strong>Inclusion body myositis</strong> is de meest voorkomende verworven spierziekte boven de 50 jaar. Er is een combinatie van ontsteking (T-cellen in de spier) en degeneratie met <em>‘rimmed vacuoles’</em> en eiwitophopingen in de spiervezels.</p><p>De zwakte is vaak asymmetrisch en treft typisch de diepe vingerflexoren (moeite met knijpen) en de m. quadriceps (vallen, moeite met opstaan); ook slikklachten komen voor. In tegenstelling tot polymyositis reageert IBM nauwelijks op immunosuppressieve behandeling.</p>","image_url":"","wiki_title":"Inclusion body myositis","match":"inclusion body myositis|ibm|inclusion-body myositis","option_only":true},"epilepsie":{"title":"Epilepsie","short":"Epilepsie is een hersenaandoening met herhaalde, niet-uitgelokte epileptische aanvallen door abnormale, synchrone ontladingen van neuronen.","definition":"<p>Bij <strong>epilepsie</strong> heeft iemand de neiging tot herhaalde epileptische aanvallen. Een aanval ontstaat door een plotselinge, overmatige en gesynchroniseerde ontlading van groepen neuronen.</p><p>Aanvallen kunnen focaal beginnen (in één hersengebied; met of zonder bewustzijnsdaling) of gegeneraliseerd (beide hemisferen; bijv. tonisch-klonische aanvallen of absences). Oorzaken: genetisch, structureel (litteken, tumor, ontwikkelingsstoornis), infectieus, metabool of onbekend. Diagnostiek met anamnese/heteroanamnese, EEG en MRI.</p>","image_url":"","wiki_title":"Epilepsy","match":"epilepsie","option_only":true},"astigmatisme":{"title":"Astigmatisme","short":"Bij astigmatisme is het hoornvlies (of de lens) ongelijk gekromd, waardoor licht niet in één punt wordt gefocust en alles wat wazig of vervormd is.","definition":"<p>Bij <strong>astigmatisme</strong> is de breking van het oog niet in alle richtingen gelijk, meestal omdat het hoornvlies meer de vorm van een rugbybal dan van een voetbal heeft.</p><p>Lichtstralen in verschillende vlakken worden op verschillende afstanden gefocust, zodat er op het netvlies geen scherp punt ontstaat: zowel dichtbij als veraf is het beeld wazig of vervormd. Correctie met een <em>cilinderglas</em> (bril of torische lens).</p>","image_url":"","wiki_title":"Astigmatism","match":"astigmatisme|cilindrische afwijking","option_only":true},"ablatio retinae":{"title":"Ablatio retinae","short":"Bij een ablatio retinae laat het netvlies los van de onderliggende pigmentlaag; klachten zijn lichtflitsen, mouches volantes en een gordijn voor het oog.","definition":"<p>Bij een <strong>ablatio retinae</strong> (netvliesloslating) raakt de neurosensorische retina los van het retinale pigmentepitheel. Meestal begint het met een scheurtje in het netvlies, waardoor vocht uit het glasvocht onder het netvlies loopt (rhegmatogeen); risicofactoren zijn myopie, leeftijd en eerdere oogoperaties.</p><p>Klachten: lichtflitsen, plotseling veel ‘vliegjes’ (mouches volantes) en een zich uitbreidende schaduw of gordijn in het gezichtsveld, zonder pijn. Het is een spoedgeval: chirurgisch herstel voordat de macula loslaat.</p>","image_url":"","wiki_title":"Retinal detachment","match":"ablatio retinae|netvliesloslating|amotio retinae","option_only":true},"hyposfagma":{"title":"Hyposfagma","short":"Een hyposfagma is een onschuldige bloeding onder het bindvlies van het oog: een scherp begrensde felrode vlek, zonder pijn of visusklachten.","definition":"<p>Bij een <strong>hyposfagma</strong> knapt een bloedvaatje onder de conjunctiva. Het oog krijgt een scherp begrensde, felrode vlek op het oogwit, zonder pijn, afscheiding of slechter zien.</p><p>Oorzaken: hoesten, persen, niezen, wrijven, hypertensie of antistolling; vaak is er geen oorzaak. Het verdwijnt vanzelf binnen 1–3 weken. Alleen bij trauma, herhaling of bloedingsneiging is verder onderzoek nodig.</p>","image_url":"","wiki_title":"Subconjunctival bleeding","match":"hyposfagma|subconjunctivale bloeding","option_only":true},"tia":{"title":"Transient ischaemic attack (TIA)","short":"Een TIA is een kortdurende uitval van een hersenfunctie door tijdelijke ischemie, zonder blijvend infarct; een belangrijk waarschuwingssignaal voor een herseninfarct.","definition":"<p>Bij een <strong>TIA</strong> (transient ischaemic attack) ontstaan plotseling focale neurologische klachten (bijv. halfzijdige verlamming, afasie, monoculaire blindheid) die meestal binnen enkele minuten tot een uur volledig verdwijnen, zonder infarct op beeldvorming.</p><p>De oorzaak is meestal een embolie (vanuit de carotis of het hart, bijv. bij boezemfibrilleren) of een kleine-vatenafwijking. Na een TIA is het risico op een herseninfarct in de eerste dagen sterk verhoogd; snelle analyse en secundaire preventie (antistolling of plaatjesremmers, statine, bloeddruk) zijn nodig.</p>","image_url":"","wiki_title":"Transient ischemic attack","match":"tia|transient ischaemic attack|transient ischemic attack","option_only":true},"bof":{"title":"Bof","short":"Bof is een virale infectie (paramyxovirus) met pijnlijke zwelling van de oorspeekselklieren; complicaties zijn orchitis, meningitis en doofheid.","definition":"<p><strong>Bof</strong> (parotitis epidemica) wordt veroorzaakt door het bofvirus, een omhuld RNA-virus. Het wordt via druppels overgedragen.</p><p>Het typische beeld is een pijnlijke zwelling van één of beide <em>glandulae parotideae</em>, met koorts en malaise. Complicaties zijn orchitis (vooral na de puberteit), oöforitis, pancreatitis, meningitis en eenzijdige doofheid. Er wordt tegen gevaccineerd met het BMR-vaccin.</p>","image_url":"","wiki_title":"Mumps","match":"bof|parotitis epidemica|bofvirus","option_only":true},"vitamine b12":{"title":"Vitamine B12 (cobalamine)","short":"Vitamine B12 is nodig voor DNA-synthese en de myelinevorming; opname vereist intrinsieke factor uit de maag en een gezond terminaal ileum.","definition":"<p><strong>Vitamine B12</strong> komt alleen uit dierlijke producten. In de maag bindt het aan intrinsieke factor (van pariëtale cellen); het complex wordt in het terminale ileum opgenomen. B12 is cofactor van methioninesynthase (koppeling met foliumzuur) en methylmalonyl-CoA-mutase. Tekort ontstaat door bijv. auto-immuungastritis (pernicieuze anemie), maag- of ileumresectie, metformine of veganisme, en geeft macrocytaire anemie en neurologische schade.</p>","image_url":"","wiki_title":"Vitamin B12","match":"vitamine b12|cobalamine|b12","option_only":true},"calcium":{"title":"Calcium","short":"Calcium is nodig voor botten, spiercontractie, zenuwgeleiding en stolling; de bloedspiegel wordt geregeld door PTH, vitamine D en calcitonine.","definition":"<p>Het meeste <strong>calcium</strong> zit in botten als hydroxyapatiet. In het bloed is ongeveer de helft eiwitgebonden (vooral aan albumine) en de rest vrij geïoniseerd, de biologisch actieve vorm. Calcium is tweede boodschapper in cellen en essentieel voor spiercontractie, neurotransmitterafgifte en stolling. Afwijkingen geven bijv. tetanie (hypocalciëmie) of dorst, obstipatie en verwardheid (hypercalciëmie).</p>","image_url":"","wiki_title":"Calcium in biology","match":"calcium|ca2+|calciumion","option_only":true},"dopamine":{"title":"Dopamine","short":"Dopamine is een catecholamine-neurotransmitter, belangrijk voor motoriek, beloning en de remming van prolactine.","definition":"<p><strong>Dopamine</strong> wordt gemaakt uit tyrosine via L-DOPA. Belangrijke dopaminerge banen zijn de nigrostriatale baan (motoriek; verlies bij Parkinson), de mesolimbische en mesocorticale banen (beloning, motivatie, psychose) en de tubero-infundibulaire baan (remming van prolactine). Antipsychotica blokkeren D2-receptoren.</p>","image_url":"","wiki_title":"Dopamine","match":"dopamine","option_only":true},"glutamaat":{"title":"Glutamaat (glutaminezuur)","short":"Glutamaat is de belangrijkste prikkelende neurotransmitter in het centrale zenuwstelsel en een centraal aminozuur in de stofwisseling.","definition":"<p><strong>Glutamaat</strong> werkt op ionotrope receptoren (AMPA, NMDA, kainaat) en metabotrope receptoren. NMDA-receptoren spelen een sleutelrol bij leren en geheugen (langetermijnpotentiëring). Overmatige activatie leidt tot instroom van calcium en celdood (excitotoxiciteit), bijvoorbeeld bij ischemie. In de stofwisseling is glutamaat een knooppunt van transaminering en stikstofafvoer.</p>","image_url":"","wiki_title":"Glutamic acid","match":"glutamaat|glutaminezuur|glutamate","option_only":true},"verapamil":{"title":"Verapamil","short":"Verapamil is een calciumantagonist die vooral op het hart werkt: het remt de AV-geleiding en verlaagt de hartfrequentie.","definition":"<p><strong>Verapamil</strong> (een fenylalkylamine) blokkeert L-type calciumkanalen in hart en vaten. Het vertraagt de geleiding in de AV-knoop en vermindert de contractiekracht. Indicaties: supraventriculaire tachycardieën, frequentiecontrole bij boezemfibrilleren, angina pectoris en hypertensie. Niet combineren met bètablokkers (risico op bradycardie en AV-blok); obstipatie is een bekende bijwerking.</p>","image_url":"","wiki_title":"Verapamil","match":"verapamil","option_only":true},"simvastatine":{"title":"Simvastatine","short":"Simvastatine is een statine: een HMG-CoA-reductaseremmer die het LDL-cholesterol verlaagt.","definition":"<p><strong>Simvastatine</strong> remt HMG-CoA-reductase, het snelheidsbepalende enzym van de cholesterolsynthese in de lever. De lever maakt daardoor meer LDL-receptoren aan en haalt meer LDL uit het bloed. Statines verlagen het risico op hart- en vaatziekten. Bijwerkingen: spierklachten (zelden rabdomyolyse) en leverenzymstijging; simvastatine heeft veel interacties via CYP3A4.</p>","image_url":"","wiki_title":"Simvastatin","match":"simvastatine|statine|statines","option_only":true},"clopidogrel":{"title":"Clopidogrel","short":"Clopidogrel is een plaatjesremmer die de ADP-receptor P2Y12 op bloedplaatjes onomkeerbaar blokkeert.","definition":"<p><strong>Clopidogrel</strong> is een prodrug die via CYP2C19 in de lever wordt geactiveerd. De actieve metaboliet blokkeert de P2Y12-receptor, zodat ADP de plaatjes niet meer kan activeren. Het wordt gebruikt na een acuut coronair syndroom en stentplaatsing (vaak samen met acetylsalicylzuur) en bij herseninfarct en perifeer vaatlijden. Bijwerking: bloedingen.</p>","image_url":"","wiki_title":"Clopidogrel","match":"clopidogrel","option_only":true},"vena emissaria":{"title":"Vena emissaria","short":"Venae emissariae zijn klapvrije venen die door de schedel heen de durale sinussen verbinden met venen buiten de schedel.","definition":"<p><strong>Venae emissariae</strong> lopen door kleine openingen in de schedel (bijv. het foramen mastoideum). Ze hebben geen kleppen, zodat bloed in beide richtingen kan stromen. Daardoor kunnen infecties van de hoofdhuid of het gezicht zich naar de durale sinussen verspreiden.</p>","image_url":"","wiki_title":"Emissary veins","match":"vena emissaria|venae emissariae|emissaire venen","option_only":true},"m. deltoideus":{"title":"M. deltoideus","short":"De m. deltoideus is de driehoekige schouderspier die de arm abduceert; geïnnerveerd door de n. axillaris.","definition":"<p>De <strong>m. deltoideus</strong> ontspringt van de clavicula, het acromion en de spina scapulae en hecht aan op de tuberositas deltoidea van de humerus. Het middelste deel abduceert de arm (vooral boven ±15°), het voorste deel helpt bij anteflexie en endorotatie, het achterste deel bij retroflexie en exorotatie. Innervatie: n. axillaris (C5–C6).</p>","image_url":"","wiki_title":"Deltoid muscle","match":"m. deltoideus|musculus deltoideus|deltaspier","option_only":true},"n. abducens":{"title":"N. abducens (VI)","short":"De n. abducens (VI) innerveert de m. rectus lateralis, die het oog naar buiten beweegt.","definition":"<p>De <strong>n. abducens</strong> ontspringt aan de grens van pons en medulla en heeft een lang intracraniëel verloop, door de sinus cavernosus naar de orbita. Daardoor is hij gevoelig voor verhoogde intracraniële druk. Uitval geeft horizontale dubbelbeelden en een oog dat niet goed naar buiten kan bewegen.</p>","image_url":"","wiki_title":"Abducens nerve","match":"n. abducens|nervus abducens|hersenzenuw vi|n. vi","option_only":true},"n. opticus":{"title":"N. opticus (II)","short":"De n. opticus (II) voert visuele informatie van de retina naar het chiasma opticum.","definition":"<p>De <strong>n. opticus</strong> bestaat uit de axonen van de retinale ganglioncellen. Strikt genomen is het een baan van het centrale zenuwstelsel: hij is omgeven door hersenvliezen en gemyeliniseerd door oligodendrocyten (daarom aangedaan bij MS). In het chiasma kruisen de vezels van de nasale netvlieshelften.</p>","image_url":"","wiki_title":"Optic nerve","match":"n. opticus|nervus opticus|oogzenuw|hersenzenuw ii","option_only":true},"n. infraorbitalis":{"title":"N. infraorbitalis","short":"De n. infraorbitalis is een tak van de n. maxillaris (V2) die de huid van wang, onderooglid, zijkant neus en bovenlip verzorgt.","definition":"<p>De <strong>n. infraorbitalis</strong> loopt over de orbitabodem door de canalis infraorbitalis en komt via het foramen infraorbitale op het gezicht. Bij een orbitabodemfractuur (blow-out) kan de zenuw beschadigd raken, met gevoelloosheid van wang en bovenlip als gevolg.</p>","image_url":"","wiki_title":"Infraorbital nerve","match":"n. infraorbitalis|nervus infraorbitalis","option_only":true},"derde ventrikel":{"title":"Derde ventrikel","short":"De derde ventrikel is een smalle liquorholte in de middellijn, tussen beide thalami.","definition":"<p>De <strong>derde ventrikel</strong> ligt in het diencephalon. Ze ontvangt liquor uit de laterale ventrikels via de foramina van Monro en staat via de aquaductus cerebri in verbinding met de vierde ventrikel. In de wanden liggen de thalamus en hypothalamus; het dak bevat plexus choroideus.</p>","image_url":"","wiki_title":"Third ventricle","match":"derde ventrikel|ventriculus tertius","option_only":true},"vierde ventrikel":{"title":"Vierde ventrikel","short":"De vierde ventrikel is de liquorholte tussen hersenstam en cerebellum, met openingen naar de subarachnoïdale ruimte.","definition":"<p>De <strong>vierde ventrikel</strong> ligt achter pons en medulla oblongata en vóór het cerebellum; de bodem heet de fossa rhomboidea. Via het mediane foramen van Magendie en de laterale foramina van Luschka stroomt liquor naar de subarachnoïdale ruimte (o.a. de cisterna magna). Naar caudaal loopt hij over in de canalis centralis.</p>","image_url":"","wiki_title":"Fourth ventricle","match":"vierde ventrikel|ventriculus quartus","option_only":true},"cisterna interpeduncularis":{"title":"Cisterna interpeduncularis","short":"De cisterna interpeduncularis is een verwijding van de subarachnoïdale ruimte tussen de hersenstelen (crura cerebri).","definition":"<p>De <strong>cisterna interpeduncularis</strong> ligt aan de voorzijde van het mesencephalon, tussen de pedunculi cerebri. Erin liggen de splitsing van de a. basilaris en het begin van de n. oculomotorius. Bij een subarachnoïdale bloeding kan hier bloed op CT zichtbaar zijn.</p>","image_url":"","wiki_title":"Interpeduncular cistern","match":"cisterna interpeduncularis","option_only":true},"cortex cerebri":{"title":"Cortex cerebri (hersenschors)","short":"De cortex cerebri is de buitenste laag grijze stof van de grote hersenen, sterk geplooid in gyri en sulci.","definition":"<p>De <strong>cortex cerebri</strong> is 2–4 mm dik en grotendeels opgebouwd uit zes lagen (neocortex). Er worden primaire gebieden (bijv. motorische en somatosensorische cortex), unimodale associatiegebieden en multimodale associatiegebieden onderscheiden. De indeling in Brodmann-gebieden is gebaseerd op verschillen in celopbouw.</p>","image_url":"","wiki_title":"Cerebral cortex","match":"cortex cerebri|hersenschors|cerebrale cortex","option_only":true},"hippocampus":{"title":"Hippocampus","short":"De hippocampus ligt in de mediale temporaalkwab en is essentieel voor het vastleggen van nieuwe herinneringen.","definition":"<p>De <strong>hippocampus</strong> is onderdeel van het limbisch systeem en ligt in de bodem van de onderhoorn van de laterale ventrikel. Hij is nodig om nieuwe episodische en ruimtelijke herinneringen op te slaan (consolidatie). De belangrijkste uitgang is de fornix. Hij is gevoelig voor hypoxie en wordt vroeg aangetast bij de ziekte van Alzheimer.</p>","image_url":"","wiki_title":"Hippocampus","match":"hippocampus","option_only":true},"tractus opticus":{"title":"Tractus opticus","short":"De tractus opticus loopt van het chiasma opticum naar het corpus geniculatum laterale en bevat vezels van beide ogen voor de tegenovergestelde gezichtshelft.","definition":"<p>Na de kruising in het chiasma bevat elke <strong>tractus opticus</strong> de vezels van het temporale netvlies van hetzelfde oog en het nasale netvlies van het andere oog. Een laesie geeft daarom een homonieme hemianopsie aan de tegenovergestelde kant. Een klein deel van de vezels gaat naar de pretectale kernen voor de pupilreflex.</p>","image_url":"","wiki_title":"Optic tract","match":"tractus opticus","option_only":true},"a. cerebri media":{"title":"A. cerebri media","short":"De a. cerebri media is de grootste eindtak van de a. carotis interna en voorziet de laterale zijde van de hemisfeer.","definition":"<p>De <strong>a. cerebri media</strong> loopt door de fissura lateralis (Sylvii) en voorziet het grootste deel van de laterale hemisfeer, inclusief de motorische en sensorische cortex voor gezicht en arm en (in de dominante hemisfeer) de taalgebieden. Lenticulostriatale takjes voorzien de basale kernen en de capsula interna. Een infarct geeft o.a. contralaterale uitval van gezicht en arm en afasie of neglect.</p>","image_url":"","wiki_title":"Middle cerebral artery","match":"a. cerebri media|arteria cerebri media|acm|mca","option_only":true},"a. cerebri posterior":{"title":"A. cerebri posterior","short":"De a. cerebri posterior ontstaat uit de a. basilaris en voorziet de occipitaalkwab, de onderkant van de temporaalkwab en de thalamus.","definition":"<p>De <strong>a. cerebri posterior</strong> ontstaat uit de splitsing van de a. basilaris en is via de a. communicans posterior verbonden met de carotiscirculatie. Ze voorziet de occipitaalkwab (visuele cortex), de mediale onderkant van de temporaalkwab en via perforerende takjes de thalamus en het mesencephalon. Een infarct geeft typisch een contralaterale homonieme hemianopsie.</p>","image_url":"","wiki_title":"Posterior cerebral artery","match":"a. cerebri posterior|arteria cerebri posterior|acp|pca","option_only":true},"a. meningea media":{"title":"A. meningea media","short":"De a. meningea media voorziet de dura mater; ze loopt aan de binnenkant van de schedel onder het pterion.","definition":"<p>De <strong>a. meningea media</strong> is een tak van de a. maxillaris en komt de schedel binnen via het foramen spinosum. Ze loopt tussen dura en schedelbot en heeft een voorste tak die onder het dunne pterion ligt. Een schedelfractuur op die plek kan de arterie scheuren, met een epiduraal hematoom als gevolg.</p>","image_url":"","wiki_title":"Middle meningeal artery","match":"a. meningea media|arteria meningea media","option_only":true},"neuritis vestibularis":{"title":"Neuritis vestibularis","short":"Neuritis vestibularis is een (vermoedelijk virale) ontsteking van de n. vestibularis met acute, dagenlange draaiduizeligheid zonder gehoorverlies.","definition":"<p>Bij <strong>neuritis vestibularis</strong> valt het evenwichtsorgaan aan één kant plotseling uit. Dat geeft heftige draaiduizeligheid, misselijkheid, braken en een horizontale nystagmus naar de gezonde kant, zonder gehoorverlies of andere neurologische uitval. De head-impulstest is afwijkend. Het herstel verloopt over dagen tot weken via centrale compensatie.</p>","image_url":"","wiki_title":"Vestibular neuritis","match":"neuritis vestibularis|neuronitis vestibularis","option_only":true},"neuropathie":{"title":"Neuropathie","short":"Neuropathie is een aandoening van perifere zenuwen, met gevoelsstoornissen, krachtsverlies en/of verlaagde reflexen.","definition":"<p>Een <strong>neuropathie</strong> kan één zenuw treffen (mononeuropathie, bijv. carpaletunnelsyndroom), meerdere zenuwen asymmetrisch (mononeuritis multiplex) of symmetrisch veel zenuwen tegelijk (polyneuropathie, typisch beginnend in de voeten). Oorzaken zijn o.a. diabetes, alcohol, vitamine B12-tekort, medicatie (chemotherapie), auto-immuniteit en erfelijke aandoeningen.</p>","image_url":"","wiki_title":"Peripheral neuropathy","match":"neuropathie|perifere neuropathie","option_only":true},"ziekte van parkinson":{"title":"Ziekte van Parkinson","short":"De ziekte van Parkinson is een neurodegeneratieve ziekte door verlies van dopaminerge neuronen in de substantia nigra, met rusttremor, bradykinesie en rigiditeit.","definition":"<p>Bij de <strong>ziekte van Parkinson</strong> gaan dopaminerge neuronen in de substantia nigra pars compacta verloren, met Lewy-lichaampjes (alfa-synucleïne). Kernsymptomen zijn bradykinesie, rigiditeit, rusttremor en later houdingsinstabiliteit; vaak ook niet-motorische klachten zoals reukverlies, obstipatie, depressie en slaapstoornissen. Behandeling met levodopa en dopamine-agonisten.</p>","image_url":"","wiki_title":"Parkinson's disease","match":"ziekte van parkinson|parkinson|morbus parkinson","option_only":true},"spanningshoofdpijn":{"title":"Spanningshoofdpijn","short":"Spanningshoofdpijn is een drukkende, dubbelzijdige hoofdpijn van lichte tot matige intensiteit, zonder misselijkheid.","definition":"<p><strong>Spanningshoofdpijn</strong> is de meest voorkomende vorm van hoofdpijn. Ze voelt als een band of druk rond het hoofd, verergert niet bij lichamelijke inspanning en gaat niet gepaard met braken; licht- of geluidsovergevoeligheid komt hooguit één van beide voor. Ze kan episodisch of chronisch (≥15 dagen per maand) zijn. Overmatig pijnstillergebruik kan medicatie-overgebruikshoofdpijn geven.</p>","image_url":"","wiki_title":"Tension headache","match":"spanningshoofdpijn|spanningstype hoofdpijn|episodische spanningshoofdpijn","option_only":true},"migraine ophthalmique":{"title":"Migraine met visuele aura","short":"Bij migraine met visuele aura gaan neurologische, meestal visuele verschijnselen (zoals flikkerende zigzaglijnen) aan de hoofdpijn vooraf.","definition":"<p>Bij een <strong>visuele aura</strong> ziet iemand flikkerende lichtjes, zigzaglijnen (fortificatiespectrum) of een uitbreidende blinde vlek, die zich in 5–60 minuten ontwikkelen en weer verdwijnen. Men denkt dat een golf van depolarisatie over de cortex (cortical spreading depression) hieraan ten grondslag ligt. Daarna volgt meestal een migraineaanval, soms blijft de hoofdpijn weg.</p>","image_url":"","wiki_title":"Migraine","match":"migraine ophthalmique|migraine met aura|oftalmische migraine","option_only":true},"epileptische aanval":{"title":"Epileptische aanval","short":"Een epileptische aanval is een kortdurende verandering in gedrag, bewustzijn of waarneming door een abnormale, overmatige ontlading van neuronen.","definition":"<p>Een <strong>epileptische aanval</strong> kan focaal beginnen (in één hersengebied, met of zonder bewustzijnsdaling) of gegeneraliseerd zijn (bijv. tonisch-klonisch of absence). Een aanval kan uitgelokt worden (bijv. door hypoglykemie, alcoholonthouding of koorts bij jonge kinderen) of passen bij epilepsie. Een aanval die langer dan 5 minuten duurt wordt behandeld als status epilepticus.</p>","image_url":"","wiki_title":"Epileptic seizure","match":"epileptische aanval|insult|epileptisch insult","option_only":true},"sinustrombose":{"title":"Cerebrale sinustrombose","short":"Bij een sinustrombose is een durale veneuze sinus afgesloten door een stolsel, met hoofdpijn en tekenen van verhoogde intracraniële druk.","definition":"<p>Een <strong>cerebrale sinustrombose</strong> komt vaker voor bij jonge vrouwen, met risicofactoren als orale anticonceptie, zwangerschap en kraambed, trombofilie, infecties en dehydratie. Klachten zijn hoofdpijn (vaak progressief), papiloedeem, epileptische aanvallen, focale uitval en verminderd bewustzijn; veneuze infarcten zijn vaak hemorragisch. Diagnose met CT- of MR-venografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Cerebral venous sinus thrombosis","match":"sinustrombose|cerebrale veneuze trombose|sinus trombose","option_only":true},"herseninfarct":{"title":"Herseninfarct","short":"Een herseninfarct ontstaat door afsluiting van een hersenarterie, waardoor hersenweefsel afsterft; het geeft plotselinge focale uitval.","definition":"<p>Een <strong>herseninfarct</strong> wordt veroorzaakt door trombose (bijv. bij atherosclerose of kleine-vatenziekte) of embolie (vaak uit het hart bij boezemfibrilleren of uit de carotis). Klachten ontstaan plotseling, afhankelijk van het vaatgebied: halfzijdige verlamming, gevoelsstoornis, afasie, gezichtsvelduitval. Acute behandeling binnen het tijdvenster: intraveneuze trombolyse en/of trombectomie.</p>","image_url":"","wiki_title":"Ischemic stroke","match":"herseninfarct|ischemisch cva|stroke (herseninfarct)|ischemisch herseninfarct","option_only":true},"acusticusneurinoom":{"title":"Acusticusneurinoom (vestibulair schwannoom)","short":"Een acusticusneurinoom is een goedaardige tumor van de Schwann-cellen van de n. vestibularis, in de inwendige gehoorgang of brughoek.","definition":"<p>Een <strong>vestibulair schwannoom</strong> groeit langzaam vanuit de n. vestibularis (VIII). Klassiek begint het met eenzijdig, geleidelijk perceptief gehoorverlies en oorsuizen; grotere tumoren in de brughoek kunnen de n. facialis, n. trigeminus en het cerebellum en de hersenstam drukken. Dubbelzijdige schwannomen passen bij neurofibromatose type 2. Diagnose met MRI.</p>","image_url":"","wiki_title":"Vestibular schwannoma","match":"acusticusneurinoom|vestibulair schwannoom|brughoektumor","option_only":true},"hypofyse-adenoom":{"title":"Hypofyseadenoom","short":"Een hypofyseadenoom is een goedaardige tumor van de hypofysevoorkwab, al dan niet hormoonproducerend.","definition":"<p><strong>Hypofyseadenomen</strong> worden ingedeeld naar grootte (micro- &lt;1 cm, macroadenoom ≥1 cm) en naar hormoonproductie: o.a. prolactinoom, groeihormoon (acromegalie), ACTH (ziekte van Cushing) of niet-functionerend. Grote adenomen kunnen het chiasma opticum drukken (bitemporale hemianopsie) en uitval van andere hypofysehormonen geven.</p>","image_url":"","wiki_title":"Pituitary adenoma","match":"hypofyse-adenoom|hypofyseadenoom|hypofysetumor","option_only":true},"pilocytair astrocytoom":{"title":"Pilocytair astrocytoom","short":"Een pilocytair astrocytoom is een goed begrensde, laaggradige (WHO graad 1) hersentumor, vooral bij kinderen en vaak in het cerebellum.","definition":"<p>Het <strong>pilocytair astrocytoom</strong> komt vooral voor bij kinderen en jongvolwassenen, in het cerebellum, rond de n. opticus (vooral bij NF1) of de hersenstam. Op beeldvorming is het vaak een cyste met een aankleurende wandnodulus. Microscopisch zijn er langgerekte haarachtige cellen en Rosenthal-vezels. Complete resectie geeft een uitstekende prognose.</p>","image_url":"","wiki_title":"Pilocytic astrocytoma","match":"pilocytair astrocytoom|pilocytisch astrocytoom","option_only":true},"laaggradig glioom":{"title":"Laaggradig glioom","short":"Een laaggradig glioom is een langzaam groeiende primaire hersentumor uitgaande van gliacellen (WHO graad 1–2).","definition":"<p><strong>Laaggradige gliomen</strong> omvatten o.a. diffuse astrocytomen en oligodendrogliomen (vaak met een IDH-mutatie) bij volwassenen, en pilocytaire astrocytomen bij kinderen. Ze presenteren zich vaak met epileptische aanvallen. Diffuse vormen groeien infiltrerend en kunnen in de loop van jaren overgaan in een hooggradig glioom.</p>","image_url":"","wiki_title":"Glioma","match":"laaggradig glioom|laaggradige glioom|low-grade glioom","option_only":true},"treponema pallidum":{"title":"Treponema pallidum","short":"Treponema pallidum is de spirocheet die syfilis veroorzaakt.","definition":"<p><strong><em>Treponema pallidum</em></strong> is een dunne, spiraalvormige bacterie die niet te kweken is en niet zichtbaar is met een gramkleuring. Ze wordt seksueel en via de placenta overgedragen. Diagnostiek gebeurt meestal serologisch (treponemale en non-treponemale tests) of met PCR uit een ulcus. Penicilline blijft het middel van keus.</p>","image_url":"","wiki_title":"Treponema pallidum","match":"treponema pallidum|treponema","option_only":true},"syfilis":{"title":"Syfilis (lues)","short":"Syfilis is een seksueel overdraagbare infectie door Treponema pallidum, die in stadia verloopt.","definition":"<p><strong>Syfilis</strong> begint (primair) met een pijnloos ulcus (sjanker) op de plek van besmetting. Weken later volgt het secundaire stadium met huiduitslag (ook op handpalmen en voetzolen), condylomata lata en algemene klachten. Na een latente fase kan na jaren tertiaire syfilis ontstaan (gummata, cardiovasculaire en neurosyfilis). Congenitale syfilis wordt voorkomen door screening in de zwangerschap.</p>","image_url":"","wiki_title":"Syphilis","match":"syfilis|lues|syphilis","option_only":true},"varicella-zostervirus":{"title":"Varicella-zostervirus (VZV)","short":"Het varicella-zostervirus veroorzaakt waterpokken en blijft daarna latent in sensibele ganglia, van waaruit het als gordelroos kan reactiveren.","definition":"<p>Het <strong>varicella-zostervirus</strong> (HHV-3) is zeer besmettelijk via aerosolen en blaasjesvocht. De primaire infectie, <em>waterpokken</em>, geeft koorts en jeukende blaasjes in verschillende stadia tegelijk. Het virus nestelt zich in sensibele ganglia; reactivatie geeft <em>herpes zoster</em>. Gevaarlijk is infectie bij zwangeren, pasgeborenen en afweergestoorden (pneumonie, encefalitis).</p>","image_url":"","wiki_title":"Varicella zoster virus","match":"varicella-zostervirus|varicella zoster|varicella zostervirus (vzv)|vzv|waterpokken|varicella","option_only":true},"virale meningitis":{"title":"Virale meningitis","short":"Virale meningitis is een ontsteking van de hersenvliezen door een virus; meestal milder dan bacteriële meningitis.","definition":"<p><strong>Virale meningitis</strong> wordt vaak veroorzaakt door enterovirussen, daarnaast o.a. door HSV-2 en VZV. Er zijn hoofdpijn, koorts, nekstijfheid en lichtschuwheid, meestal zonder verlaagd bewustzijn. Liquor toont een lymfocytaire pleiocytose met normaal glucose en licht verhoogd eiwit. Het beloop is meestal goedaardig.</p>","image_url":"","wiki_title":"Viral meningitis","match":"virale meningitis|aseptische meningitis","option_only":true},"tuberculeuze meningitis":{"title":"Tuberculeuze meningitis","short":"Tuberculeuze meningitis is een subacuut verlopende hersenvliesontsteking door Mycobacterium tuberculosis.","definition":"<p>Bij <strong>tuberculeuze meningitis</strong> ontstaan in dagen tot weken hoofdpijn, koorts, gedragsverandering en uitval van hersenzenuwen, vooral door ontsteking aan de schedelbasis. De liquor toont lymfocyten, een sterk verhoogd eiwit en een verlaagd glucose. Complicaties zijn hydrocephalus en infarcten. Behandeling met tuberculostatica en dexamethason.</p>","image_url":"","wiki_title":"Tuberculous meningitis","match":"tuberculeuze meningitis|tbc-meningitis","option_only":true},"toxoplasmose":{"title":"Toxoplasmose","short":"Toxoplasmose is een infectie met de parasiet Toxoplasma gondii, opgelopen via kattenpoep of onvoldoende verhit vlees.","definition":"<p><strong><em>Toxoplasma gondii</em></strong> heeft de kat als eindgastheer. Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleose-achtig beeld. Bij een eerste infectie in de zwangerschap kan de parasiet de foetus infecteren (chorioretinitis, hydrocephalus, intracraniële verkalkingen). Bij afweergestoorden kan reactivatie toxoplasma-encefalitis geven.</p>","image_url":"","wiki_title":"Toxoplasmosis","match":"toxoplasmose|toxoplasma gondii|toxoplasma","option_only":true},"rabies":{"title":"Rabiës (hondsdolheid)","short":"Rabiës is een vrijwel altijd dodelijke virale encefalitis, overgedragen via beten of krabben van besmette zoogdieren.","definition":"<p>Het <strong>rabiësvirus</strong> reist via perifere zenuwen naar het centrale zenuwstelsel; de incubatietijd varieert van weken tot maanden. Zodra klachten optreden (agitatie, hydrofobie, verlammingen) is de ziekte vrijwel altijd fataal. Na een risicovolle beet is direct wondverzorging en postexpositieprofylaxe (vaccinatie, zo nodig met immunoglobuline) nodig.</p>","image_url":"","wiki_title":"Rabies","match":"rabies|rabiës|hondsdolheid","option_only":true},"sinusitis":{"title":"Sinusitis (bijholteontsteking)","short":"Sinusitis is een ontsteking van het slijmvlies van neus en bijholten, met verstopte neus, pijn in het gezicht en afscheiding.","definition":"<p>Acute <strong>rhinosinusitis</strong> ontstaat meestal na een virale verkoudheid; soms volgt een bacteriële infectie (pneumokok, <em>H. influenzae</em>, <em>Moraxella</em>). Klachten zijn een verstopte neus, (purulente) afscheiding, pijn of drukgevoel boven de bijholten en verminderde reuk. Meestal herstelt het binnen enkele weken zonder antibiotica. Chronische sinusitis duurt langer dan 12 weken.</p>","image_url":"","wiki_title":"Sinusitis","match":"sinusitis|bijholteontsteking|rhinosinusitis","option_only":true},"longcarcinoom":{"title":"Longcarcinoom","short":"Longkanker is een kwaadaardige tumor uitgaande van het epitheel van de luchtwegen; roken is de belangrijkste oorzaak.","definition":"<p>Het <strong>longcarcinoom</strong> wordt ingedeeld in niet-kleincellig (o.a. adenocarcinoom en plaveiselcelcarcinoom) en kleincellig longcarcinoom. Klachten zijn o.a. aanhoudende hoest, hemoptoë, kortademigheid, gewichtsverlies en recidiverende pneumonieën; vaak wordt het pas laat ontdekt. Paraneoplastische syndromen (zoals SIADH, hypercalciëmie, Lambert-Eaton) komen voor.</p>","image_url":"","wiki_title":"Lung cancer","match":"longcarcinoom|longkanker|bronchuscarcinoom","option_only":true},"paroxysmaal atriumfibrilleren":{"title":"Paroxysmaal atriumfibrilleren","short":"Bij paroxysmaal atriumfibrilleren treden aanvallen van boezemfibrilleren op die binnen 7 dagen vanzelf stoppen.","definition":"<p>Bij <strong>atriumfibrilleren</strong> is de elektrische activiteit van de boezems chaotisch; de kamers slaan onregelmatig en vaak snel. In de paroxysmale vorm duren episodes korter dan een week en eindigen ze spontaan. Er is een verhoogd risico op trombo-embolie (vooral herseninfarct) vanuit het linkerhartoor; afhankelijk van de CHA₂DS₂-VASc-score wordt antistolling gegeven.</p>","image_url":"","wiki_title":"Atrial fibrillation","match":"paroxysmaal atriumfibrilleren|paroxysmaal boezemfibrilleren|atriumfibrilleren|boezemfibrilleren","option_only":true},"verlengd qt-syndroom":{"title":"Lang-QT-syndroom","short":"Bij een verlengd QT-interval duurt de repolarisatie van de kamers te lang, met risico op torsade de pointes en plotse dood.","definition":"<p>Het <strong>lange-QT-syndroom</strong> kan aangeboren zijn (mutaties in kalium- of natriumkanalen) of verworven, door geneesmiddelen (o.a. antiaritmica, sommige antipsychotica, antibiotica zoals macroliden en chinolonen) en elektrolytstoornissen (hypokaliëmie, hypomagnesiëmie). Klachten zijn syncope of plotse hartstilstand, soms uitgelokt door schrik, inspanning of zwemmen.</p>","image_url":"","wiki_title":"Long QT syndrome","match":"verlengd qt-syndroom|lang-qt-syndroom|long qt syndroom|qt-verlenging","option_only":true},"open foramen ovale":{"title":"Open foramen ovale (PFO)","short":"Een open foramen ovale is een niet volledig gesloten verbinding tussen de boezems, een restant van de foetale circulatie.","definition":"<p>Het <strong>foramen ovale</strong> laat in de foetale circulatie bloed van het rechter- naar het linkeratrium stromen. Na de geboorte stijgt de druk links en sluit het functioneel; bij ongeveer een kwart van de volwassenen blijft het anatomisch open. Meestal geeft dat geen klachten, maar het kan een paradoxale embolie (veneuze stolsel naar de systeemcirculatie) mogelijk maken.</p>","image_url":"","wiki_title":"Patent foramen ovale","match":"open foramen ovale|patent foramen ovale|pfo","option_only":true},"orthostatische hypotensie":{"title":"Orthostatische hypotensie","short":"Orthostatische hypotensie is een bloeddrukdaling bij het opstaan door onvoldoende compensatie van het autonome zenuwstelsel.","definition":"<p>Bij <strong>orthostatische hypotensie</strong> daalt de systolische bloeddruk met ≥20 mmHg (of de diastolische met ≥10 mmHg) binnen 3 minuten na overeind komen. Normaal zorgt de baroreflex voor vasoconstrictie en een hogere hartfrequentie. Oorzaken zijn o.a. ondervulling, medicatie (antihypertensiva, diuretica, antidepressiva) en autonome neuropathie. Klachten: duizeligheid, wazig zien en wegraking bij opstaan.</p>","image_url":"","wiki_title":"Orthostatic hypotension","match":"orthostatische hypotensie","option_only":true},"hypercholesterolemie":{"title":"Hypercholesterolemie","short":"Hypercholesterolemie is een verhoogd cholesterolgehalte in het bloed, vooral van LDL-cholesterol; een risicofactor voor atherosclerose.","definition":"<p><strong>Hypercholesterolemie</strong> ontstaat door een combinatie van leefstijl en aanleg. De erfelijke vorm, familiaire hypercholesterolemie, berust meestal op een mutatie in de LDL-receptor en geeft al op jonge leeftijd zeer hoge LDL-waarden, peesxanthomen en vroege hart- en vaatziekten. Behandeling: leefstijl en statines, eventueel ezetimibe of PCSK9-remmers.</p>","image_url":"","wiki_title":"Hypercholesterolemia","match":"hypercholesterolemie|hypercholesterolaemie|verhoogd cholesterol","option_only":true},"coloncarcinoom":{"title":"Coloncarcinoom (darmkanker)","short":"Coloncarcinoom is een kwaadaardige tumor van de dikke darm, meestal een adenocarcinoom dat ontstaat uit een poliep.","definition":"<p>Het <strong>colorectaal carcinoom</strong> ontstaat meestal via de adenoom-carcinoomsequentie, waarbij mutaties (o.a. in APC, KRAS, p53) zich opstapelen. Risicofactoren zijn leeftijd, familiaire belasting (FAP, Lynch-syndroom), IBD, rood en bewerkt vlees, alcohol en roken. Klachten: veranderd ontlastingspatroon, bloed bij de ontlasting en ijzergebreksanemie. In Nederland is er een bevolkingsonderzoek met de FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"coloncarcinoom|darmkanker|colorectaal carcinoom|dikkedarmkanker","option_only":true},"arteritis temporalis":{"title":"Arteriitis temporalis (reuscelarteriitis)","short":"Arteriitis temporalis is een granulomateuze vasculitis van grote en middelgrote arteriën bij ouderen, met risico op blindheid.","definition":"<p>Bij <strong>reuscelarteriitis</strong> zijn vooral takken van de a. carotis externa (zoals de a. temporalis) en soms de aorta en haar takken ontstoken. Klachten: nieuwe hoofdpijn, gevoelige slaapslagader, kauwclaudicatie, visusstoornissen en algemene malaise, met een sterk verhoogde BSE/CRP. Bij verdenking direct hoge dosis prednison om blindheid te voorkomen; diagnose met echo of biopt.</p>","image_url":"","wiki_title":"Giant cell arteritis","match":"arteritis temporalis|arteriitis temporalis|reuscelarteriitis|giant cell arteritis","option_only":true},"psoriasis":{"title":"Psoriasis","short":"Psoriasis is een chronische ontstekingsziekte van de huid met scherp begrensde rode plaques met zilverwitte schilfers.","definition":"<p>Bij <strong>psoriasis</strong> stimuleert een T-celreactie (IL-23/Th17) een sterk versnelde deling van keratinocyten. Er ontstaan schilferende plaques op strekzijden, hoofdhuid en bilnaad, met nagelafwijkingen en het köbnerfenomeen. Een deel van de patiënten krijgt artritis psoriatica. Behandeling met lokale middelen, lichttherapie of systemische en biologische middelen.</p>","image_url":"","wiki_title":"Psoriasis","match":"psoriasis","option_only":true},"conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"conjunctivitis|bindvliesontsteking","option_only":true},"keratitis marginalis":{"title":"Keratitis marginalis","short":"Keratitis marginalis is een ontsteking aan de rand van het hoornvlies, vaak door een overgevoeligheidsreactie op stafylokokken bij blefaritis.","definition":"<p>Bij <strong>keratitis marginalis</strong> ontstaan kleine infiltraten aan de rand van de cornea, met een heldere zone tussen het infiltraat en de limbus. Het is een immuunreactie op bacteriële antigenen, vaak bij chronische blefaritis. Klachten: rood, pijnlijk, lichtschuw oog. Behandeling van de blefaritis en eventueel kort corticosteroïddruppels onder controle.</p>","image_url":"","wiki_title":"Marginal keratitis","match":"keratitis marginalis|marginale keratitis","option_only":true},"acuut glaucoom":{"title":"Acuut (gesloten-kamerhoek) glaucoom","short":"Bij acuut glaucoom raakt de kamerhoek plotseling afgesloten, waardoor de oogdruk sterk stijgt; een spoedgeval.","definition":"<p>Bij een <strong>acuut gesloten-kamerhoekglaucoom</strong> blokkeert de iris de afvloed van kamerwater, vaak bij verziende ouderen met een ondiepe voorste oogkamer, uitgelokt door pupilverwijding (schemer, medicatie). Klachten: hevige oogpijn en hoofdpijn, misselijkheid en braken, wazig zien met halo's, een rood oog, een matte cornea en een middelwijde, lichtstijve pupil. Behandeling: oogdrukverlagende medicatie en laseriridotomie.</p>","image_url":"","wiki_title":"Angle-closure glaucoma","match":"acuut glaucoom|acuut gesloten-kamerhoekglaucoom|glaucoomaanval","option_only":true},"refractieafwijking":{"title":"Refractieafwijking","short":"Een refractieafwijking betekent dat het oog licht niet scherp op het netvlies focust: bijziendheid, verziendheid of astigmatisme.","definition":"<p>Bij <strong>myopie</strong> (bijziendheid) valt het brandpunt vóór de retina, bij <strong>hypermetropie</strong> (verziendheid) erachter, en bij <strong>astigmatisme</strong> is de breking niet in alle richtingen gelijk. Presbyopie is leeftijdsgebonden verlies van accommodatie. Verbetering van het zicht met een stenopeïsche opening wijst op een refractieprobleem. Correctie met bril, lenzen of refractiechirurgie.</p>","image_url":"","wiki_title":"Refractive error","match":"refractieafwijking|refractiefout","option_only":true},"anisometropie":{"title":"Anisometropie","short":"Anisometropie is een duidelijk verschil in sterkte (refractie) tussen beide ogen.","definition":"<p>Bij <strong>anisometropie</strong> verschilt de brekingskracht van de ogen, waardoor de beelden op de netvliezen verschillen in scherpte of grootte. Bij jonge kinderen kan het brein het onscherpe oog gaan onderdrukken, met amblyopie (lui oog) als gevolg. Vroege opsporing en correctie (eventueel met afplakken) zijn belangrijk.</p>","image_url":"","wiki_title":"Anisometropia","match":"anisometropie","option_only":true},"lagophthalmus":{"title":"Lagophthalmus","short":"Bij lagophthalmus kan het ooglid niet volledig sluiten, waardoor het hoornvlies uitdroogt.","definition":"<p><strong>Lagophthalmus</strong> ontstaat meestal door een parese van de m. orbicularis oculi bij een perifere facialisparese, of door littekens, exoftalmie (bijv. bij Graves) of na ooglidchirurgie. Het hoornvlies droogt uit, met risico op keratitis en ulcera. Behandeling met kunsttranen, oogzalf en ’s nachts afplakken.</p>","image_url":"","wiki_title":"Lagophthalmos","match":"lagophthalmus|lagoftalmus","option_only":true},"fotopsie":{"title":"Fotopsie","short":"Fotopsieën zijn lichtflitsen zonder dat er licht is, vaak door mechanische prikkeling van het netvlies.","definition":"<p><strong>Fotopsieën</strong> ontstaan vaak wanneer het glasvocht aan het netvlies trekt, bijvoorbeeld bij een achterste glasvochtloslating; ze worden dan vooral in het donker en bij oogbewegingen gezien. Plots nieuwe lichtflitsen met veel ‘vliegjes’ of een schaduw vereisen onderzoek naar een netvliesscheur of -loslating. Ook een migraine-aura kan lichtverschijnselen geven.</p>","image_url":"","wiki_title":"Photopsia","match":"fotopsie|lichtflitsen","option_only":true},"achterste glasvochtmembraanloslating":{"title":"Achterste glasvochtloslating","short":"Bij een achterste glasvochtloslating laat het verschrompelende glasvocht los van het netvlies, met lichtflitsen en mouches volantes.","definition":"<p>Met het ouder worden vervloeit het glasvocht en trekt het samen. Bij de <strong>achterste glasvochtloslating</strong> komt het los van de retina, wat lichtflitsen en zwevende vlekjes geeft. Meestal onschuldig, maar de trekkracht kan een netvliesscheur veroorzaken, met risico op netvliesloslating; daarom wordt het netvlies gecontroleerd.</p>","image_url":"","wiki_title":"Posterior vitreous detachment","match":"achterste glasvochtmembraanloslating|achterste glasvochtloslating|glasvochtloslating","option_only":true},"chromatopsie":{"title":"Chromatopsie","short":"Chromatopsie is het zien in een bepaalde kleurtint, bijvoorbeeld alles geel of groen.","definition":"<p>Bij <strong>chromatopsie</strong> lijkt de hele omgeving een kleurzweem te hebben. Een bekend voorbeeld is xanthopsie (geelzien) bij een digoxine-intoxicatie. Ook na een staaroperatie (meer blauw licht) en bij sommige andere geneesmiddelen kunnen kleurverschuivingen optreden.</p>","image_url":"","wiki_title":"Chromatopsia","match":"chromatopsie","option_only":true},"oscillopsie":{"title":"Oscillopsie","short":"Oscillopsie is de illusie dat de omgeving heen en weer beweegt of trilt.","definition":"<p><strong>Oscillopsie</strong> ontstaat als het beeld niet stabiel op het netvlies blijft, bijvoorbeeld bij dubbelzijdige uitval van het evenwichtsorgaan (vooral bij lopen of hoofdbewegingen) of bij verworven nystagmus. Bij aangeboren nystagmus komt het meestal niet voor, omdat het brein zich heeft aangepast.</p>","image_url":"","wiki_title":"Oscillopsia","match":"oscillopsie","option_only":true},"non-proliferatieve diabetische retinopathie":{"title":"Non-proliferatieve diabetische retinopathie","short":"Non-proliferatieve diabetische retinopathie is het vroege stadium van diabetische netvliesschade, zonder vaatnieuwvorming.","definition":"<p>Bij <strong>non-proliferatieve diabetische retinopathie</strong> beschadigt chronische hyperglykemie de kleine netvliesvaatjes. Er ontstaan microaneurysmata, puntbloedingen, harde exsudaten en later cotton-woolvlekken en veneuze afwijkingen. Lekkage in de macula (maculaoedeem) kan het zicht bedreigen. Bij progressie volgt de proliferatieve vorm met nieuwvorming van vaten.</p>","image_url":"","wiki_title":"Diabetic retinopathy","match":"non-proliferatieve diabetische retinopathie|achtergrondretinopathie","option_only":true},"hypertensieve retinopathie gr ii":{"title":"Hypertensieve retinopathie","short":"Hypertensieve retinopathie zijn netvliesafwijkingen door langdurig hoge bloeddruk, ingedeeld in graden.","definition":"<p>Bij <strong>hypertensieve retinopathie</strong> worden de netvliesarteriolen smaller en stugger. Lichte vormen tonen vernauwde arteriolen en ‘koperdraad’-reflexen, daarna arterioveneuze kruisingsfenomenen. Ernstigere graden geven bloedingen, cotton-woolvlekken en exsudaten, en bij maligne hypertensie papiloedeem.</p>","image_url":"","wiki_title":"Hypertensive retinopathy","match":"hypertensieve retinopathie gr ii|hypertensieve retinopathie","option_only":true},"tumarkin aanval":{"title":"Tumarkin-aanval (otolietcrisis)","short":"Een Tumarkin-aanval is een plotselinge val zonder bewustzijnsverlies bij de ziekte van Ménière, door een acute prikkeling van de otolietorganen.","definition":"<p>Bij een <strong>otolietcrisis van Tumarkin</strong> heeft de patiënt het gevoel plotseling geduwd of omvergetrokken te worden en valt, zonder duizeligheid vooraf en zonder bewustzijnsverlies. Het komt vooral voor in latere stadia van de ziekte van Ménière en kan tot letsel leiden.</p>","image_url":"","wiki_title":"Ménière's disease","match":"tumarkin aanval|tumarkin-aanval|otolietcrisis","option_only":true},"duplexonderzoek halsvaten":{"title":"Duplexonderzoek van de halsvaten","short":"Duplexonderzoek van de halsvaten combineert echo en dopplermeting om vernauwingen in de halsslagaders op te sporen.","definition":"<p>Met een <strong>carotisduplex</strong> worden de wand en de stroomsnelheid in de a. carotis communis, interna en externa en de a. vertebralis beoordeeld. Een verhoogde stroomsnelheid wijst op een stenose. Het wordt gedaan na een TIA of herseninfarct in het carotisgebied, omdat een ernstige symptomatische stenose een indicatie kan zijn voor endarteriëctomie.</p>","image_url":"","wiki_title":"Carotid ultrasonography","match":"duplexonderzoek halsvaten|duplex halsvaten|carotisduplex","option_only":true},"lamotrigine":{"title":"Lamotrigine","short":"Lamotrigine is een anti-epilepticum dat natriumkanalen blokkeert; ook gebruikt om depressieve episoden bij bipolaire stoornis te voorkomen.","definition":"<p><strong>Lamotrigine</strong> stabiliseert neuronale membranen door blokkade van spanningsafhankelijke natriumkanalen en vermindert de afgifte van glutamaat. Het moet langzaam worden opgehoogd vanwege het risico op ernstige huidreacties (Stevens-Johnson-syndroom). Valproaat verhoogt de spiegel; oestrogenen verlagen hem. Het is relatief veilig in de zwangerschap.</p>","image_url":"","wiki_title":"Lamotrigine","match":"lamotrigine","option_only":true},"amantadine":{"title":"Amantadine","short":"Amantadine is een middel tegen de ziekte van Parkinson (vooral bij dyskinesieën) en werd vroeger gebruikt tegen influenza A.","definition":"<p><strong>Amantadine</strong> verhoogt de afgifte van dopamine en is een zwakke NMDA-receptorantagonist. Het wordt bij Parkinson vooral ingezet om levodopa-geïnduceerde dyskinesieën te verminderen. Als antiviraal middel blokkeerde het het M2-ionkanaal van influenza A, maar door resistentie wordt het daarvoor niet meer gebruikt. Bijwerkingen: verwardheid, hallucinaties, livedo reticularis.</p>","image_url":"","wiki_title":"Amantadine","match":"amantadine","option_only":true},"beta-blokker":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"beta-blokker|bètablokker|betablokker|bètablokkers|beta-blokkers","option_only":true},"fragiele x syndroom":{"title":"Fragiele-X-syndroom","short":"Het fragiele-X-syndroom is de meest voorkomende erfelijke oorzaak van verstandelijke beperking, door een CGG-repeatexpansie in het FMR1-gen.","definition":"<p>Bij het <strong>fragiele-X-syndroom</strong> leidt een expansie van meer dan 200 CGG-herhalingen tot methylering en uitschakeling van het FMR1-gen. Jongens zijn meestal ernstiger aangedaan dan meisjes. Kenmerken: verstandelijke beperking, autistiforme kenmerken, een lang gezicht met grote oren en na de puberteit vergrote testes. Bij overdracht via de moeder kan de repeat groeien (anticipatie).</p>","image_url":"","wiki_title":"Fragile X syndrome","match":"fragiele x syndroom|fragiele-x-syndroom|fragile x","option_only":true},"n. medianus":{"title":"N. medianus","short":"De n. medianus (C6–T1) loopt door de carpale tunnel en innerveert o.a. de duimmuis en het gevoel van duim, wijs- en middelvinger.","definition":"<p>De <strong>n. medianus</strong> ontstaat uit de fasciculus lateralis en medialis van de plexus brachialis. Hij innerveert de meeste flexoren van de onderarm, de spieren van de duimmuis en de laterale mm. lumbricales, en sensibel de palmaire zijde van duim, wijs-, middel- en de radiale helft van de ringvinger. Bij een hoog letsel ontstaat een ‘eedhand’.</p>","image_url":"","wiki_title":"Median nerve","match":"n. medianus|nervus medianus","option_only":true},"n. thoracicus longus":{"title":"N. thoracicus longus","short":"De n. thoracicus longus (C5–C7) innerveert de m. serratus anterior.","definition":"<p>De <strong>n. thoracicus longus</strong> loopt over de laterale borstwand naar beneden, oppervlakkig op de m. serratus anterior. Daardoor is hij kwetsbaar bij okselklierdissectie, trauma en zware belasting van de schouder. Uitval geeft een scapula alata, vooral zichtbaar bij duwen tegen een muur.</p>","image_url":"","wiki_title":"Long thoracic nerve","match":"n. thoracicus longus|nervus thoracicus longus","option_only":true},"ziekte van mcardle":{"title":"Ziekte van McArdle (glycogeenstapelingsziekte type V)","short":"Bij de ziekte van McArdle ontbreekt spierglycogeenfosforylase, waardoor spieren bij inspanning geen glycogeen kunnen afbreken.","definition":"<p>Bij de <strong>ziekte van McArdle</strong> ontstaan bij inspanning snel spierpijn, krampen en vermoeidheid; na een korte rust kan het beter gaan (‘second wind’, door overschakelen op bloedglucose en vetzuren). Bij forse inspanning kan rabdomyolyse met myoglobinurie optreden. Bij een inspanningstest stijgt het lactaat niet. Het erft autosomaal recessief over.</p>","image_url":"","wiki_title":"Glycogen storage disease type V","match":"ziekte van mcardle|mcardle|glycogeenstapelingsziekte type v","option_only":true},"myopathie":{"title":"Myopathie","short":"Een myopathie is een ziekte van de spier zelf, meestal met proximale spierzwakte.","definition":"<p><strong>Myopathieën</strong> kunnen erfelijk zijn (bijv. spierdystrofieën, mitochondriale myopathieën) of verworven: inflammatoir (polymyositis, dermatomyositis), endocrien (hypothyreoïdie, Cushing), toxisch (statines, alcohol, corticosteroïden) of metabool. Het CK kan verhoogd zijn; een EMG en spierbiopt helpen bij de diagnose.</p>","image_url":"","wiki_title":"Myopathy","match":"myopathie|spierziekte","option_only":true},"myastheen syndroom":{"title":"Myasthenie (gravis) en myastheen syndroom","short":"Myasthene syndromen zijn stoornissen in de prikkeloverdracht van zenuw naar spier, met zwakte die toeneemt bij inspanning.","definition":"<p>Bij <strong>myasthenia gravis</strong> blokkeren antistoffen de acetylcholinereceptor; er is wisselende, inspanningsafhankelijke zwakte van oogspieren (ptosis, dubbelzien), bulbaire spieren en ledematen. Bij het <strong>Lambert-Eaton myasthene syndroom</strong> zijn antistoffen gericht tegen presynaptische calciumkanalen, vaak bij een kleincellig longcarcinoom; hier verbetert de kracht juist kort bij herhaald aanspannen en zijn de reflexen verlaagd.</p>","image_url":"","wiki_title":"Myasthenia gravis","match":"myastheen syndroom|lambert-eaton|lambert-eaton myastheen syndroom|myasthenia gravis|myasthenie","option_only":true},"ct scan":{"title":"CT-scan","short":"Een CT-scan maakt met röntgenstraling dwarsdoorsneden van het lichaam.","definition":"<p>Bij <strong>computertomografie</strong> draait een röntgenbuis rond de patiënt en wordt een driedimensionaal beeld berekend. CT is snel en zeer geschikt voor trauma, bloedingen in het hoofd, longen, buik en bot; met contrast ook voor vaten. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct scan|ct-scan|computertomografie","option_only":true},"herpes encefalitis":{"title":"Herpes-simplexencefalitis","short":"Herpes-simplexencefalitis is een ernstige virale ontsteking van de hersenen, typisch in de temporaalkwabben.","definition":"<p>Bij <strong>HSV-encefalitis</strong> (meestal HSV-1) ontstaan koorts, hoofdpijn, verwardheid, gedrags- en spraakstoornissen en epileptische aanvallen. MRI toont afwijkingen in de mediale temporaalkwab; de liquor toont lymfocyten en HSV-PCR is positief. Onbehandeld is de sterfte hoog; bij verdenking wordt direct aciclovir intraveneus gestart.</p>","image_url":"","wiki_title":"Herpes simplex encephalitis","match":"herpes encefalitis|herpesencefalitis|herpes simplex encefalitis|hsv-encefalitis","option_only":true},"diabetische retinopathie":{"title":"Diabetische retinopathie","short":"Diabetische retinopathie is schade aan de netvliesvaatjes door langdurig hoge bloedglucose.","definition":"<p>Bij <strong>diabetische retinopathie</strong> ontstaan eerst microaneurysmata, puntbloedingen en harde exsudaten (non-proliferatief). Bij ernstige ischemie groeien nieuwe, kwetsbare vaten (proliferatief), met risico op glasvochtbloedingen en tractieablatio. Maculaoedeem kan in elk stadium het zicht bedreigen. Behandeling met laser en anti-VEGF-injecties; screening voorkomt blindheid.</p>","image_url":"","wiki_title":"Diabetic retinopathy","match":"diabetische retinopathie","option_only":true},"maculadegeneratie":{"title":"Leeftijdsgebonden maculadegeneratie","short":"Bij maculadegeneratie raakt de gele vlek (het centrum van het netvlies) beschadigd, met verlies van het centrale zien.","definition":"<p>Bij <strong>LMD</strong> is er een droge vorm (drusen en atrofie) en een natte vorm (nieuwvorming van lekkende vaatjes onder het netvlies). Klachten zijn vervormd zien (rechte lijnen lijken krom), een vlek in het centrum en moeite met lezen en gezichten herkennen; het perifere zien blijft bewaard. Risicofactoren: leeftijd, roken en erfelijkheid. De natte vorm wordt met anti-VEGF-injecties behandeld.</p>","image_url":"","wiki_title":"Macular degeneration","match":"maculadegeneratie|leeftijdsgebonden maculadegeneratie|lmd|amd","option_only":true},"benigne paroxysmale positieveranderingsduizeligheid (bppd)":{"title":"BPPD","short":"BPPD is kortdurende draaiduizeligheid bij hoofdbewegingen, doordat losse otolieten in een halfcirkelvormig kanaal zijn terechtgekomen.","definition":"<p>Bij <strong>BPPD</strong> bewegen losgeraakte kalkkristallen bij een verandering van hoofdhouding (omdraaien in bed, opkijken) in meestal het achterste kanaal, wat seconden tot een minuut heftige draaiduizeligheid geeft. De Dix-Hallpike-test lokt een nystagmus uit. Behandeling met een repositiemanoeuvre (Epley).</p>","image_url":"","wiki_title":"Benign paroxysmal positional vertigo","match":"benigne paroxysmale positieveranderingsduizeligheid (bppd)|bppd|benigne paroxysmale positieduizeligheid","option_only":true},"n. obturatorius":{"title":"N. obturatorius","short":"De n. obturatorius (L2–L4) innerveert de adductoren van het bovenbeen en de huid aan de binnenkant van de dij.","definition":"<p>De <strong>n. obturatorius</strong> komt uit de plexus lumbalis, loopt langs de bekkenwand en verlaat het bekken via het canalis obturatorius. Hij innerveert de mediale (adductoren)loge. Letsel kan ontstaan bij bekkenchirurgie, bekkenfracturen of bevallingen, met zwakte bij adductie en gevoelsstoornissen aan de binnenzijde van de dij.</p>","image_url":"","wiki_title":"Obturator nerve","match":"n. obturatorius|nervus obturatorius","option_only":true},"n. femoralis":{"title":"N. femoralis","short":"De n. femoralis (L2–L4) innerveert de m. quadriceps en m. iliopsoas en de huid aan de voorkant van de dij en binnenkant van het onderbeen.","definition":"<p>De <strong>n. femoralis</strong> loopt langs de m. psoas en onder het lig. inguinale door, lateraal van de a. femoralis. Hij is nodig voor kniestrekking en de kniepeesreflex. Zijn sensibele eindtak, de n. saphenus, verzorgt de mediale zijde van het onderbeen. Uitval geeft een zwakke kniestrekking en een afwezige kniepeesreflex.</p>","image_url":"","wiki_title":"Femoral nerve","match":"n. femoralis|nervus femoralis","option_only":true},"m. gastrocnemius":{"title":"M. gastrocnemius","short":"De m. gastrocnemius is de oppervlakkige, tweekoppige kuitspier die de voet plantair flecteert en de knie helpt buigen.","definition":"<p>De <strong>m. gastrocnemius</strong> ontspringt boven de femurcondylen en hecht via de achillespees aan de calcaneus. Omdat hij over twee gewrichten loopt, is hij sterk betrokken bij lopen, rennen en springen. Een ‘tennis leg’ is een scheur in de mediale kop. Innervatie: n. tibialis.</p>","image_url":"","wiki_title":"Gastrocnemius muscle","match":"m. gastrocnemius|musculus gastrocnemius|kuitspier","option_only":true},"thiazidediuretica":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazidediuretica","option_only":true},"bofvirus":{"title":"Bof","short":"Bof is een virale infectie (paramyxovirus) met pijnlijke zwelling van de oorspeekselklieren; complicaties zijn orchitis, meningitis en doofheid.","definition":"<p><strong>Bof</strong> (parotitis epidemica) wordt veroorzaakt door het bofvirus, een omhuld RNA-virus. Het wordt via druppels overgedragen.</p><p>Het typische beeld is een pijnlijke zwelling van één of beide <em>glandulae parotideae</em>, met koorts en malaise. Complicaties zijn orchitis (vooral na de puberteit), oöforitis, pancreatitis, meningitis en eenzijdige doofheid. Er wordt tegen gevaccineerd met het BMR-vaccin.</p>","image_url":"","wiki_title":"Mumps","match":"bofvirus","option_only":true},"thiazide diureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazide diureticum","option_only":true},"hydrochloortiazide":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"hydrochloortiazide","option_only":true},"alcoholmisbruik":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcoholmisbruik","option_only":true},"globus pallidus externa":{"title":"Globus pallidus pars externa (GPe)","short":"De GPe is onderdeel van de basale kernen en vormt een schakel in de indirecte route; hij remt de nucleus subthalamicus.","definition":"<p>De <strong>globus pallidus pars externa</strong> is het laterale deel van de globus pallidus. Hij ontvangt remmende (GABA-erge) input van het striatum en stuurt zelf remmende projecties naar de nucleus subthalamicus.</p><p>Hij is een kernschakel van de <em>indirecte route</em> van de basale kernen (cortex → striatum → GPe → nucleus subthalamicus → GPi/SNr → thalamus), die beweging per saldo afremt.</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus externa","option_only":true},"globus pallidus interna":{"title":"Globus pallidus pars interna (GPi)","short":"De GPi is de belangrijkste uitgangskern van de basale kernen; hij remt (GABA-erg) de motorische thalamus.","definition":"<p>De <strong>globus pallidus pars interna</strong> is samen met de substantia nigra pars reticulata de <em>uitgangskern</em> van de basale kernen. Hij geeft tonisch remmende GABA-erge output naar de motorische kernen van de thalamus.</p><p>De directe route (striatum → GPi) remt de GPi en ontremt zo de thalamus (meer beweging); de indirecte route versterkt via de nucleus subthalamicus juist de remming. De GPi is een doelwit bij diepe hersenstimulatie (o.a. dystonie, Parkinson).</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus interna","option_only":true},"sarcoïdose":{"title":"Sarcoïdose","short":"Sarcoïdose is een systemische aandoening van onbekende oorzaak met niet-verkazende granulomen, vooral in longen en lymfeklieren.","definition":"<p>Bij <strong>sarcoïdose</strong> zijn vaak de hilaire lymfeklieren en het longweefsel aangedaan; ook huid (erythema nodosum), ogen (uveïtis), hart en zenuwstelsel kunnen betrokken zijn. Het ACE en calcium kunnen verhoogd zijn. Het syndroom van Löfgren (koorts, erythema nodosum, hilaire klieren, enkelartritis) heeft een goede prognose.</p>","image_url":"","wiki_title":"Sarcoidosis","match":"sarcoïdose|sarcoidose|ziekte van besnier-boeck","option_only":true},"creatinekinase":{"title":"Creatinekinase (CK)","short":"Creatinekinase is een enzym uit spieren; een verhoogde bloedwaarde wijst op spierschade.","definition":"<p><strong>CK</strong> zet creatinefosfaat en ADP om in creatine en ATP. Het stijgt bij spierschade: rabdomyolyse, myositis, spierdystrofieën, na intensieve inspanning, trauma of injecties, en door statines. De CK-MB-vorm werd vroeger gebruikt bij hartinfarcten.</p>","image_url":"","wiki_title":"Creatine kinase","match":"creatinekinase|ck|creatinine kinase|creatinekinase (ck)","option_only":true},"guillain-barré syndroom":{"title":"Syndroom van Guillain-Barré","short":"Het syndroom van Guillain-Barré is een acute auto-immuunpolyneuropathie met snel oplopende, symmetrische slappe verlamming en areflexie.","definition":"<p>Het <strong>Guillain-Barré-syndroom</strong> volgt vaak 1–4 weken na een infectie (bijv. <em>Campylobacter</em>, CMV). Zwakte begint meestal in de benen en stijgt op; ademhalingsspieren en hersenzenuwen kunnen betrokken raken, en er kunnen autonome stoornissen optreden. Liquor toont eiwit-celdissociatie. Behandeling met immunoglobulinen of plasmaferese.</p>","image_url":"","wiki_title":"Guillain–Barré syndrome","match":"guillain-barré syndroom|guillain-barrésyndroom|guillain-barre","option_only":true},"corpus alienum in de luchtweg":{"title":"Corpus alienum in de luchtweg","short":"Een corpus alienum in de luchtweg is een ingeademd vreemd voorwerp; bij jonge kinderen een belangrijke oorzaak van plotselinge benauwdheid.","definition":"<p>Bij <strong>aspiratie van een vreemd voorwerp</strong> (vaak pinda's, speelgoedonderdelen) ontstaan plotseling hoesten, verslikken en benauwdheid; later kan een eenzijdig piepen, verminderd ademgeruis of een recidiverende pneumonie optreden. Het voorwerp komt vaak in de rechter hoofdbronchus terecht. Verwijdering via een bronchoscopie.</p>","image_url":"","wiki_title":"Foreign body aspiration","match":"corpus alienum in de luchtweg|corpus alienum|vreemd voorwerp","option_only":true},"optokinetische nystagmus":{"title":"Optokinetische nystagmus","short":"Optokinetische nystagmus is een normale reflexmatige oogbeweging bij het volgen van een bewegend patroon, zoals uit het raam van een rijdende trein kijken.","definition":"<p>Bij <strong>optokinetische nystagmus</strong> volgen de ogen het bewegende beeld langzaam (volgbeweging) en springen dan snel terug (saccade). Het wordt gebruikt om het zien te testen bij baby's en mensen die niet kunnen communiceren, en om simulatie van blindheid uit te sluiten.</p>","image_url":"","wiki_title":"Optokinetic response","match":"optokinetische nystagmus|okn","option_only":true},"carotisstenose":{"title":"Carotisstenose","short":"Een carotisstenose is een vernauwing van de halsslagader (meestal de a. carotis interna) door atherosclerose, met risico op een herseninfarct.","definition":"<p>Een <strong>carotisstenose</strong> kan embolieën veroorzaken naar het oog (amaurosis fugax) of de hemisfeer (TIA of herseninfarct). Bij een symptomatische, ernstige stenose verlaagt een endarteriëctomie het risico op een nieuw infarct, mits snel uitgevoerd. Opsporing met duplexonderzoek.</p>","image_url":"","wiki_title":"Carotid artery stenosis","match":"carotisstenose|stenose arteria carotis interna rechts|stenose a. carotis interna","option_only":true},"granulationes arachnoidales":{"title":"Arachnoïdale granulaties","short":"Arachnoïdale granulaties zijn uitstulpingen van de arachnoidea in de durale sinussen, waarlangs liquor naar het veneuze bloed wordt afgevoerd.","definition":"<p>Via de <strong>arachnoïdale granulaties</strong> (vooral in de sinus sagittalis superior) wordt liquor geresorbeerd. Bij een verstoorde resorptie (bijv. na een subarachnoïdale bloeding of meningitis) kan een communicerende hydrocephalus ontstaan.</p>","image_url":"","wiki_title":"Arachnoid granulation","match":"granulationes arachnoidales|arachnoïdale villi|arachnoïdale granulaties|granulaties van pacchioni","option_only":true},"foramen van monro":{"title":"Foramen interventriculare (Monro)","short":"De foramina van Monro verbinden de laterale ventrikels met de derde ventrikel.","definition":"<p>Via de <strong>foramina interventricularia</strong> stroomt liquor van de laterale naar de derde ventrikel. Een colloïdcyste in de derde ventrikel kan deze openingen afsluiten, met een acute hydrocephalus van de laterale ventrikels.</p>","image_url":"","wiki_title":"Interventricular foramina (neuroanatomy)","match":"foramen van monro|foramen interventriculare|foramina van monro","option_only":true},"foramen van magendie":{"title":"Foramen van Magendie","short":"Het foramen van Magendie is de middelste opening van de vierde ventrikel naar de cisterna magna.","definition":"<p>Samen met de laterale foramina van Luschka laat het <strong>foramen van Magendie</strong> liquor van het ventrikelsysteem naar de subarachnoïdale ruimte stromen. Afsluiting hiervan (bijv. bij de Dandy-Walker-malformatie) geeft een hydrocephalus.</p>","image_url":"","wiki_title":"Median aperture","match":"foramen van magendie|apertura mediana","option_only":true},"episcleritis":{"title":"Episcleritis","short":"Episcleritis is een milde, meestal onschuldige ontsteking van de laag tussen bindvlies en sclera, met een lokaal rood oog.","definition":"<p>Bij <strong>episcleritis</strong> is een sectorvormig deel van het oog rood, met weinig pijn en normaal zicht. Het verdwijnt meestal vanzelf. Het onderscheid met scleritis (hevige, borende pijn; vaak bij systemische ziekten zoals reumatoïde artritis) is belangrijk.</p>","image_url":"","wiki_title":"Episcleritis","match":"episcleritis","option_only":true},"valaciclovir":{"title":"Valaciclovir","short":"Valaciclovir is een prodrug van aciclovir: een antiviraal middel tegen herpes simplex en varicella-zoster.","definition":"<p><strong>Aciclovir</strong> wordt in geïnfecteerde cellen door het virale thymidinekinase geactiveerd en remt dan het virale DNA-polymerase. Valaciclovir wordt beter opgenomen en hoeft minder vaak te worden ingenomen. Gebruik bij herpes zoster, genitale herpes en (intraveneus aciclovir) herpesencefalitis. Bij hoge doses kan nierschade optreden.</p>","image_url":"","wiki_title":"Valaciclovir","match":"valaciclovir|aciclovir","option_only":true},"diplopie":{"title":"Diplopie (dubbelzien)","short":"Diplopie is dubbelzien; binoculaire diplopie verdwijnt bij afdekken van één oog en wijst op een stoornis in de oogstand.","definition":"<p>Bij <strong>binoculaire diplopie</strong> kijken de ogen niet in dezelfde richting, door een parese van een hersenzenuw (III, IV, VI), een stoornis van de neuromusculaire overdracht (myasthenie), een probleem in de oogkas (Graves-orbitopathie, fractuur) of een centraal probleem. Monoculaire diplopie (blijft bij afdekken) wijst op een oogprobleem zoals cataract of astigmatisme.</p>","image_url":"","wiki_title":"Diplopia","match":"diplopie|dubbelzien|dubbelbeelden","option_only":true},"glaucoom":{"title":"Glaucoom","short":"Glaucoom is een groep oogziekten met schade aan de oogzenuw en gezichtsvelduitval, meestal samenhangend met een verhoogde oogdruk.","definition":"<p>Bij het meest voorkomende <strong>openkamerhoekglaucoom</strong> verloopt de schade langzaam en ongemerkt, met eerst uitval in het perifere gezichtsveld en een toenemende excavatie van de papil. Risicofactoren: hogere leeftijd, verhoogde oogdruk, familie, myopie en een donkere huidskleur. Behandeling met oogdrukverlagende druppels, laser of operatie. Acuut glaucoom is een apart, acuut ziektebeeld.</p>","image_url":"","wiki_title":"Glaucoma","match":"glaucoom|groene staar|openkamerhoekglaucoom","option_only":true},"een thiazidediureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"een thiazidediureticum","option_only":true},"een statine":{"title":"Simvastatine","short":"Simvastatine is een statine: een HMG-CoA-reductaseremmer die het LDL-cholesterol verlaagt.","definition":"<p><strong>Simvastatine</strong> remt HMG-CoA-reductase, het snelheidsbepalende enzym van de cholesterolsynthese in de lever. De lever maakt daardoor meer LDL-receptoren aan en haalt meer LDL uit het bloed. Statines verlagen het risico op hart- en vaatziekten. Bijwerkingen: spierklachten (zelden rabdomyolyse) en leverenzymstijging; simvastatine heeft veel interacties via CYP3A4.</p>","image_url":"","wiki_title":"Simvastatin","match":"een statine","option_only":true},"atorvastatine":{"title":"Simvastatine","short":"Simvastatine is een statine: een HMG-CoA-reductaseremmer die het LDL-cholesterol verlaagt.","definition":"<p><strong>Simvastatine</strong> remt HMG-CoA-reductase, het snelheidsbepalende enzym van de cholesterolsynthese in de lever. De lever maakt daardoor meer LDL-receptoren aan en haalt meer LDL uit het bloed. Statines verlagen het risico op hart- en vaatziekten. Bijwerkingen: spierklachten (zelden rabdomyolyse) en leverenzymstijging; simvastatine heeft veel interacties via CYP3A4.</p>","image_url":"","wiki_title":"Simvastatin","match":"atorvastatine","option_only":true},"sarco&iuml;dose":{"title":"Sarcoïdose","short":"Sarcoïdose is een systemische aandoening van onbekende oorzaak met niet-verkazende granulomen, vooral in longen en lymfeklieren.","definition":"<p>Bij <strong>sarcoïdose</strong> zijn vaak de hilaire lymfeklieren en het longweefsel aangedaan; ook huid (erythema nodosum), ogen (uveïtis), hart en zenuwstelsel kunnen betrokken zijn. Het ACE en calcium kunnen verhoogd zijn. Het syndroom van Löfgren (koorts, erythema nodosum, hilaire klieren, enkelartritis) heeft een goede prognose.</p>","image_url":"","wiki_title":"Sarcoidosis","match":"sarco&iuml;dose","option_only":true},"bacteriële endocarditis met s. aureus":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"bacteriële endocarditis met s. aureus","option_only":true},"endocarditis lenta":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"endocarditis lenta","option_only":true},"amyotrofische laterale sclerose":{"title":"Amyotrofische laterale sclerose (ALS)","short":"ALS is een progressieve, dodelijke ziekte van zowel het bovenste als het onderste motorneuron.","definition":"<p>Bij <strong>ALS</strong> ontstaan asymmetrische zwakte, atrofie en fasciculaties (onderste motorneuron) samen met spasticiteit en hyperreflexie (bovenste motorneuron), vaak met slik- en spraakproblemen. Gevoel, oogbewegingen en blaasfunctie blijven meestal gespaard. Een deel heeft ook frontotemporale dementie. Riluzol vertraagt het beloop iets.</p>","image_url":"","wiki_title":"Amyotrophic lateral sclerosis","match":"amyotrofische laterale sclerose|als","option_only":true},"uveitis anterior":{"title":"Uveïtis anterior","short":"Uveïtis anterior is een ontsteking van iris en corpus ciliare, met een pijnlijk rood oog, lichtschuwheid en wazig zien.","definition":"<p>Bij <strong>uveïtis anterior</strong> zijn er cellen en flare in de voorste oogkamer, ciliaire injectie en soms een nauwe of onregelmatige pupil (synechieën). Het kan samenhangen met HLA-B27-gerelateerde ziekten, sarcoïdose, JIA of infecties. Behandeling met corticosteroïd- en pupilverwijdende druppels.</p>","image_url":"","wiki_title":"Uveitis","match":"uveitis anterior|uveïtis anterior|iridocyclitis|iritis","option_only":true},"cornea erosie":{"title":"Cornea-erosie","short":"Een cornea-erosie is een oppervlakkig defect in het hoornvliesepitheel, met pijn, tranen en lichtschuwheid.","definition":"<p>Een <strong>cornea-erosie</strong> ontstaat vaak door een krasje (vingernagel, tak) of contactlens. Met fluoresceïne kleurt het defect groen aan. Het geneest meestal binnen enkele dagen; bij contactlensdragers moet aan een bacteriële keratitis worden gedacht.</p>","image_url":"","wiki_title":"Corneal abrasion","match":"cornea erosie|cornea-erosie|hoornvlieserosie","option_only":true},"vasovagaal":{"title":"Vasovagale syncope","short":"Een vasovagale syncope is een flauwte door een reflex met vaatverwijding en vertraging van de hartslag, uitgelokt door bijv. pijn, emotie of lang staan.","definition":"<p>Bij een <strong>vasovagale syncope</strong> gaan vaak voorboden vooraf: misselijkheid, zweten, warm gevoel en zwart voor de ogen. Na het vallen herstelt iemand snel. Het is de meest voorkomende oorzaak van wegraking bij jonge mensen en is onschuldig, al kan het letsel geven.</p>","image_url":"","wiki_title":"Vasovagal response","match":"vasovagaal|vasovagale syncope|vasovagale collaps","option_only":true},"glatirameeracetaat":{"title":"Glatirameeracetaat","short":"Glatirameeracetaat is een immunomodulerend middel bij relapsing-remitting multipele sclerose.","definition":"<p><strong>Glatirameeracetaat</strong> is een mengsel van peptiden dat lijkt op myeline-basiseiwit en de afweerreactie richting een minder ontstekingsbevorderend patroon verschuift. Het wordt subcutaan gespoten en vermindert het aantal schubs. Bijwerkingen zijn reacties op de injectieplaats.</p>","image_url":"","wiki_title":"Glatiramer acetate","match":"glatirameeracetaat|glatiramer","option_only":true},"sumatriptan":{"title":"Sumatriptan (triptanen)","short":"Sumatriptan is een triptan: een 5-HT1B/1D-agonist die een migraineaanval couperet.","definition":"<p><strong>Triptanen</strong> vernauwen verwijde schedelvaten en remmen de afgifte van ontstekingspeptiden (CGRP) uit trigeminusvezels. Ze worden bij het begin van de hoofdpijnfase ingenomen. Contra-indicaties zijn coronair lijden, een eerder herseninfarct en ongecontroleerde hypertensie.</p>","image_url":"","wiki_title":"Sumatriptan","match":"sumatriptan|triptanen|triptan","option_only":true},"natriumvalproaat":{"title":"Valproïnezuur","short":"Valproaat is een breed werkend anti-epilepticum en stemmingsstabilisator, maar sterk teratogeen.","definition":"<p><strong>Valproaat</strong> werkt o.a. via versterking van GABA en blokkade van natriumkanalen. Het werkt goed bij gegeneraliseerde epilepsieën en bij bipolaire stoornis. Bij gebruik in de zwangerschap is er een groot risico op aangeboren afwijkingen (neuralebuisdefecten) en ontwikkelingsproblemen; bij vrouwen in de vruchtbare leeftijd wordt het daarom zo veel mogelijk vermeden. Andere bijwerkingen: gewichtstoename, tremor, haaruitval, leverschade en hyperammoniëmie.</p>","image_url":"","wiki_title":"Valproate","match":"natriumvalproaat|valproïnezuur|valproaat|valproinezuur","option_only":true},"levetiracetam":{"title":"Levetiracetam","short":"Levetiracetam is een veelgebruikt anti-epilepticum dat bindt aan het synaptische blaasjeseiwit SV2A.","definition":"<p><strong>Levetiracetam</strong> heeft weinig interacties en kan snel worden opgehoogd, ook intraveneus (bijv. bij status epilepticus). Bekende bijwerkingen zijn prikkelbaarheid, stemmingsklachten en vermoeidheid.</p>","image_url":"","wiki_title":"Levetiracetam","match":"levetiracetam","option_only":true},"neuromusculaire transmissiestoornis":{"title":"Neuromusculaire transmissiestoornis","short":"Bij een neuromusculaire transmissiestoornis is de prikkeloverdracht van zenuw naar spier verstoord, met vermoeibare zwakte.","definition":"<p>Voorbeelden zijn <strong>myasthenia gravis</strong> (antistoffen tegen de acetylcholinereceptor), het Lambert-Eaton-syndroom (antistoffen tegen presynaptische calciumkanalen) en botulisme. Typisch is zwakte die toeneemt bij inspanning; reflexen en gevoel zijn normaal (bij Lambert-Eaton zijn de reflexen verlaagd).</p>","image_url":"","wiki_title":"Neuromuscular junction disease","match":"neuromusculaire transmissiestoornis|myasthenie","option_only":true},"voorhoornaandoening":{"title":"Voorhoornaandoening","short":"Bij een voorhoornaandoening gaan de motorneuronen in de voorhoorn van het ruggenmerg verloren, met zwakte, atrofie en fasciculaties.","definition":"<p>Voorbeelden zijn <strong>spinale musculaire atrofie</strong>, ALS (met ook bovenste-motorneuronbetrokkenheid), poliomyelitis en de progressieve spinale musculaire atrofie. Het gevoel blijft intact.</p>","image_url":"","wiki_title":"Motor neuron diseases","match":"voorhoornaandoening|voorhoorncelziekte|motorneuronziekte","option_only":true},"mononeuritis multiplex":{"title":"Mononeuritis multiplex","short":"Bij mononeuritis multiplex raken meerdere afzonderlijke zenuwen (asymmetrisch) aangedaan, vaak door vasculitis.","definition":"<p><strong>Mononeuritis multiplex</strong> ontstaat door ischemie van zenuwen (vasa nervorum), bijvoorbeeld bij vasculitis (polyarteriitis nodosa, ANCA-vasculitis), diabetes, reumatoïde artritis of lepra. Het geeft pijnlijke uitval van bijv. de n. fibularis of n. ulnaris.</p>","image_url":"","wiki_title":"Mononeuritis multiplex","match":"mononeuritis multiplex","option_only":true},"craniofaryngioom":{"title":"Craniofaryngioom","short":"Een craniofaryngioom is een goedaardige, vaak cysteuze tumor boven de sella, uitgaand van restanten van het zakje van Rathke.","definition":"<p>Een <strong>craniofaryngioom</strong> komt vooral bij kinderen en ouderen voor. Het kan het chiasma drukken (gezichtsvelduitval), hypothalamus en hypofyse aantasten (groeiachterstand, diabetes insipidus, obesitas) en hydrocephalus veroorzaken. Op beeldvorming zijn vaak verkalkingen te zien.</p>","image_url":"","wiki_title":"Craniopharyngioma","match":"craniofaryngioom","option_only":true},"neuro-fibrillary tangles":{"title":"Neurofibrillaire tangles","short":"Neurofibrillaire tangles zijn kluwens van afwijkend gefosforyleerd tau-eiwit in neuronen, kenmerkend voor de ziekte van Alzheimer.","definition":"<p>Het eiwit <strong>tau</strong> stabiliseert normaal microtubuli. Bij hyperfosforylering laat het los en klontert het in neuronen samen. De verspreiding van tangles door het brein correleert goed met de ernst van de dementie. Tauopathieën omvatten ook sommige vormen van frontotemporale dementie.</p>","image_url":"","wiki_title":"Neurofibrillary tangle","match":"neuro-fibrillary tangles|neurofibrillaire tangles|tau","option_only":true},"cervicale myelopathie":{"title":"Cervicale myelopathie","short":"Bij cervicale myelopathie wordt het ruggenmerg in de nek gedrukt, meestal door degeneratie van de wervelkolom.","definition":"<p><strong>Cervicale spondylotische myelopathie</strong> geeft geleidelijk onhandige handen, loopstoornissen, spasticiteit en hyperreflexie in de benen, soms met blaasproblemen. Het is een veelvoorkomende oorzaak van een spastische paraparese bij ouderen. Diagnose met MRI; bij progressie operatieve decompressie.</p>","image_url":"","wiki_title":"Degenerative cervical myelopathy","match":"cervicale myelopathie|cervicale kanaalstenose","option_only":true},"lumbale kanaalstenose":{"title":"Lumbale kanaalstenose","short":"Bij lumbale kanaalstenose is het wervelkanaal in de lage rug vernauwd, met pijn in de benen bij lopen die verbetert bij voorover buigen.","definition":"<p>Typisch voor <strong>neurogene claudicatio</strong> is dat de klachten verbeteren bij zitten of voorover buigen (fietsen gaat beter dan lopen), in tegenstelling tot vasculaire claudicatio, die bij stilstaan al verbetert. Behandeling: fysiotherapie, pijnstilling en eventueel decompressie.</p>","image_url":"","wiki_title":"Lumbar spinal stenosis","match":"lumbale kanaalstenose|neurogene claudicatio","option_only":true},"vasculair parkinsonisme":{"title":"Vasculair parkinsonisme","short":"Vasculair parkinsonisme is een parkinsonbeeld door vaatschade in het brein, vooral met loopstoornissen van de benen.","definition":"<p>Bij <strong>vasculair parkinsonisme</strong> staan schuifelend lopen en evenwichtsproblemen op de voorgrond (‘lower body parkinsonism’), meestal zonder rusttremor. Het reageert slecht op levodopa. MRI toont uitgebreide witte-stofafwijkingen of lacunaire infarcten.</p>","image_url":"","wiki_title":"Vascular parkinsonism","match":"vasculair parkinsonisme","option_only":true},"glasvochtbloeding":{"title":"Glasvochtbloeding","short":"Bij een glasvochtbloeding komt bloed in het glasvocht, met plotselinge wazigheid of veel zwarte vlekken.","definition":"<p>Oorzaken van een <strong>glasvochtbloeding</strong> zijn proliferatieve diabetische retinopathie, een netvliesscheur (bij glasvochtloslating), een venetakocclusie en trauma. Echografie is nodig als het netvlies niet zichtbaar is, om een netvliesloslating uit te sluiten.</p>","image_url":"","wiki_title":"Vitreous hemorrhage","match":"glasvochtbloeding","option_only":true},"ischemische opticus neuropathie":{"title":"Ischemische opticusneuropathie","short":"Bij ischemische opticusneuropathie ontstaat plotseling pijnloos visusverlies door verminderde doorbloeding van de oogzenuw.","definition":"<p>De niet-arteritische vorm komt voor bij vaatrisicofactoren en een kleine, ‘volle’ papil. De arteritische vorm wordt veroorzaakt door reuscelarteriitis en vraagt om directe behandeling met hoge dosis corticosteroïden om blindheid van het andere oog te voorkomen.</p>","image_url":"","wiki_title":"Ischemic optic neuropathy","match":"ischemische opticus neuropathie|ischemische opticusneuropathie|aion","option_only":true},"keratoconjunctivitis sicca":{"title":"Keratoconjunctivitis sicca (droge ogen)","short":"Keratoconjunctivitis sicca zijn droge ogen door te weinig of slechte traanfilm, met een branderig, zanderig gevoel.","definition":"<p><strong>Droge ogen</strong> komen veel voor bij ouderen, bij beeldschermwerk, blefaritis, medicatie (anticholinergica) en auto-immuunziekten zoals het syndroom van Sjögren. Behandeling met kunsttranen en behandeling van de oorzaak.</p>","image_url":"","wiki_title":"Dry eye syndrome","match":"keratoconjunctivitis sicca|droge ogen","option_only":true},"keratitis":{"title":"Keratitis","short":"Keratitis is een ontsteking van het hoornvlies, met pijn, lichtschuwheid, tranen en soms visusdaling.","definition":"<p><strong>Keratitis</strong> kan infectieus zijn (bacterieel, vooral bij contactlensdragers; herpes simplex met dendritische afwijkingen; acanthamoeba; schimmels) of niet-infectieus (droge ogen, lagophthalmus, UV). Bacteriële keratitis is een spoedgeval wegens risico op perforatie en littekens.</p>","image_url":"","wiki_title":"Keratitis","match":"keratitis|hoornvliesontsteking","option_only":true},"oculaire hypertensie":{"title":"Oculaire hypertensie","short":"Bij oculaire hypertensie is de oogdruk verhoogd zonder schade aan de oogzenuw of gezichtsvelduitval.","definition":"<p>Mensen met <strong>oculaire hypertensie</strong> hebben een verhoogd risico op glaucoom en worden gecontroleerd; bij een hoog risico wordt soms behandeld. Een dikke cornea kan een te hoge meting geven.</p>","image_url":"","wiki_title":"Ocular hypertension","match":"oculaire hypertensie","option_only":true},"normale-drukglaucoom":{"title":"Normale-drukglaucoom","short":"Bij normale-drukglaucoom ontstaat glaucomateuze schade aan de oogzenuw terwijl de oogdruk normaal is.","definition":"<p>Bij <strong>normale-drukglaucoom</strong> spelen waarschijnlijk een verminderde doorbloeding en een kwetsbare oogzenuw een rol. Risicofactoren zijn migraine, het fenomeen van Raynaud en lage bloeddruk ’s nachts. Ook hier wordt de oogdruk verder verlaagd.</p>","image_url":"","wiki_title":"Normal-tension glaucoma","match":"normale-drukglaucoom|normaledrukglaucoom","option_only":true},"maculopathie":{"title":"Maculopathie","short":"Maculopathie is een aandoening van de macula, het centrum van het netvlies, met verlies van het scherpe zien.","definition":"<p>Voorbeelden zijn leeftijdsgebonden maculadegeneratie, <strong>diabetisch maculaoedeem</strong> (lekkage uit beschadigde vaatjes), maculaoedeem na een veneuze occlusie of operatie, en erfelijke maculadystrofieën. Behandeling van oedeem vaak met anti-VEGF-injecties.</p>","image_url":"","wiki_title":"Macular edema","match":"maculopathie|macula oedeem|maculaoedeem|diabetisch macula oedeem","option_only":true},"retinale arteriële vaatocclusie":{"title":"Retinale arterieafsluiting","short":"Bij een afsluiting van de netvliesslagader ontstaat plotseling pijnloos ernstig visusverlies; een kersrode vlek in de macula is kenmerkend.","definition":"<p>Een <strong>a. centralis retinae-occlusie</strong> is meestal embolisch (carotis, hart) en geldt als een ‘oog-beroerte’: analyse van vaatrisicofactoren is nodig. Bij oudere patiënten moet aan reuscelarteriitis worden gedacht.</p>","image_url":"","wiki_title":"Central retinal artery occlusion","match":"retinale arteriële vaatocclusie|a. centralis retinae occlusie|retinale arterieocclusie","option_only":true},"rubeosis irides":{"title":"Rubeosis iridis","short":"Rubeosis iridis is nieuwvorming van bloedvaatjes op de iris, door ernstige ischemie van het netvlies.","definition":"<p><strong>Rubeosis iridis</strong> ontstaat bij proliferatieve diabetische retinopathie, centrale veneocclusie of ernstige carotisstenose. De vaatjes kunnen de kamerhoek afsluiten, met een neovasculair glaucoom als gevolg.</p>","image_url":"","wiki_title":"Rubeosis iridis","match":"rubeosis irides|rubeosis iridis|irisneovascularisatie","option_only":true},"opticopathie van leber (lhon)":{"title":"Leber's hereditaire opticusneuropathie (LHON)","short":"LHON is een mitochondriaal erfelijke aandoening met acuut, pijnloos visusverlies, eerst in één en daarna in het andere oog, vooral bij jonge mannen.","definition":"<p><strong>LHON</strong> erft maternaal over via mitochondriaal DNA. De retinale ganglioncellen gaan verloren, met een centraal scotoom. Roken en alcohol kunnen de ziekte uitlokken bij dragers.</p>","image_url":"","wiki_title":"Leber's hereditary optic neuropathy","match":"opticopathie van leber (lhon)|lhon|leber's hereditaire opticusneuropathie","option_only":true},"trigeminus neuralgie":{"title":"Trigeminusneuralgie","short":"Trigeminusneuralgie geeft korte, extreem hevige, schietende pijnaanvallen in een tak van de n. trigeminus, uitgelokt door aanraking, kauwen of praten.","definition":"<p><strong>Trigeminusneuralgie</strong> wordt meestal veroorzaakt door een bloedvat dat de zenuw bij de hersenstam drukt; bij jonge patiënten moet aan MS worden gedacht. Carbamazepine is het middel van eerste keus; bij onvoldoende effect een operatie (microvasculaire decompressie).</p>","image_url":"","wiki_title":"Trigeminal neuralgia","match":"trigeminus neuralgie|trigeminusneuralgie","option_only":true},"neuromyelitis optica":{"title":"Neuromyelitis optica","short":"Neuromyelitis optica is een auto-immuunziekte met ernstige ontsteking van oogzenuwen en ruggenmerg, door antistoffen tegen aquaporine-4.","definition":"<p>Bij <strong>NMO</strong> ontstaan ernstige opticus-neuritiden en een uitgebreide myelitis over drie of meer segmenten, soms een area postrema-syndroom (onbedwingbaar braken en hikken). Het onderscheid met MS is belangrijk, omdat sommige MS-middelen NMO verergeren.</p>","image_url":"","wiki_title":"Neuromyelitis optica","match":"neuromyelitis optica|nmo|devic","option_only":true},"myotone dystrofie type 1":{"title":"Myotone dystrofie type 1","short":"Myotone dystrofie type 1 is een autosomaal dominante spierziekte door een CTG-repeatexpansie, met spierzwakte, myotonie en klachten in veel organen.","definition":"<p>Bij <strong>myotone dystrofie</strong> (ziekte van Steinert) kunnen spieren na aanspannen moeilijk ontspannen (myotonie). Er is distale zwakte, ptosis, een smal gezicht, staar, hartgeleidingsstoornissen, endocriene problemen en vermoeidheid. Anticipatie is kenmerkend; de congenitale vorm wordt via de moeder doorgegeven.</p>","image_url":"","wiki_title":"Myotonic dystrophy","match":"myotone dystrofie type 1|myotone dystrofie|ziekte van steinert","option_only":true},"duchenne spierdystrofie":{"title":"Spierdystrofie van Duchenne","short":"De spierdystrofie van Duchenne is een X-gebonden ziekte bij jongens door afwezigheid van dystrofine, met progressieve spierzwakte vanaf de vroege kindertijd.","definition":"<p>Jongens met <strong>Duchenne</strong> beginnen laat met lopen, vallen vaak en staan op via het teken van Gowers. Er is pseudohypertrofie van de kuiten en een sterk verhoogd CK. Ze verliezen meestal rond de twaalf jaar het loopvermogen; cardiomyopathie en ademhalingsproblemen bepalen de prognose.</p>","image_url":"","wiki_title":"Duchenne muscular dystrophy","match":"duchenne spierdystrofie|spierdystrofie van duchenne|duchenne","option_only":true},"spinale musculaire atrofie (sma) type 1":{"title":"Spinale musculaire atrofie","short":"SMA is een erfelijke ziekte van de motorische voorhoorncellen, door een defect in het SMN1-gen, met progressieve spierzwakte.","definition":"<p>Bij <strong>SMA type 1</strong> ontstaan in de eerste levensmaanden ernstige hypotonie (‘floppy infant’), zwakte en ademhalings- en slikproblemen, terwijl het kind alert is. Nieuwe behandelingen (nusinersen, gentherapie) verbeteren de prognose sterk, vooral bij vroege start; SMA zit inmiddels in de hielprik.</p>","image_url":"","wiki_title":"Spinal muscular atrophy","match":"spinale musculaire atrofie (sma) type 1|spinale musculaire atrofie|sma","option_only":true},"drusen":{"title":"Drusen","short":"Drusen zijn gele afzettingen onder het netvlies; ze zijn een vroeg kenmerk van leeftijdsgebonden maculadegeneratie.","definition":"<p>Kleine harde <strong>drusen</strong> komen vaak voor bij ouderen. Grote, zachte drusen in de macula verhogen het risico op progressie naar droge of natte maculadegeneratie. Drusen van de papil zijn iets anders: verkalkingen in de oogzenuwkop.</p>","image_url":"","wiki_title":"Drusen","match":"drusen","option_only":true},"hersentumor":{"title":"Hersentumor","short":"Een hersentumor is een gezwel in de schedel, primair uitgaand van hersenweefsel of hersenvliezen, of een uitzaaiing.","definition":"<p>Bij volwassenen zijn <strong>hersenmetastasen</strong>, meningeomen en gliomen (waaronder het glioblastoom) het meest voorkomend; bij kinderen vooral tumoren in de achterste schedelgroeve (medulloblastoom, pilocytair astrocytoom). Klachten: hoofdpijn, epilepsie, focale uitval, cognitieve en gedragsveranderingen en tekenen van verhoogde intracraniële druk.</p>","image_url":"","wiki_title":"Brain tumor","match":"hersentumor|hersentumoren","option_only":true},"uveïtis anterior":{"title":"Uveïtis anterior","short":"Uveïtis anterior is een ontsteking van iris en corpus ciliare, met een pijnlijk rood oog, lichtschuwheid en wazig zien.","definition":"<p>Bij <strong>uveïtis anterior</strong> zijn er cellen en flare in de voorste oogkamer, ciliaire injectie en soms een nauwe of onregelmatige pupil (synechieën). Het kan samenhangen met HLA-B27-gerelateerde ziekten, sarcoïdose, JIA of infecties. Behandeling met corticosteroïd- en pupilverwijdende druppels.</p>","image_url":"","wiki_title":"Uveitis","match":"uveïtis anterior","option_only":true},"bacteri&euml;le conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"bacteri&euml;le conjunctivitis","option_only":true},"bacteriële conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"bacteriële conjunctivitis","option_only":true},"virale/banale conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"virale/banale conjunctivitis","option_only":true},"achterste glasvocht membraan loslating":{"title":"Achterste glasvochtloslating","short":"Bij een achterste glasvochtloslating laat het verschrompelende glasvocht los van het netvlies, met lichtflitsen en mouches volantes.","definition":"<p>Met het ouder worden vervloeit het glasvocht en trekt het samen. Bij de <strong>achterste glasvochtloslating</strong> komt het los van de retina, wat lichtflitsen en zwevende vlekjes geeft. Meestal onschuldig, maar de trekkracht kan een netvliesscheur veroorzaken, met risico op netvliesloslating; daarom wordt het netvlies gecontroleerd.</p>","image_url":"","wiki_title":"Posterior vitreous detachment","match":"achterste glasvocht membraan loslating","option_only":true},"natte macula degeneratie":{"title":"Leeftijdsgebonden maculadegeneratie","short":"Bij maculadegeneratie raakt de gele vlek (het centrum van het netvlies) beschadigd, met verlies van het centrale zien.","definition":"<p>Bij <strong>LMD</strong> is er een droge vorm (drusen en atrofie) en een natte vorm (nieuwvorming van lekkende vaatjes onder het netvlies). Klachten zijn vervormd zien (rechte lijnen lijken krom), een vlek in het centrum en moeite met lezen en gezichten herkennen; het perifere zien blijft bewaard. Risicofactoren: leeftijd, roken en erfelijkheid. De natte vorm wordt met anti-VEGF-injecties behandeld.</p>","image_url":"","wiki_title":"Macular degeneration","match":"natte macula degeneratie","option_only":true},"droge maculadegeneratie":{"title":"Leeftijdsgebonden maculadegeneratie","short":"Bij maculadegeneratie raakt de gele vlek (het centrum van het netvlies) beschadigd, met verlies van het centrale zien.","definition":"<p>Bij <strong>LMD</strong> is er een droge vorm (drusen en atrofie) en een natte vorm (nieuwvorming van lekkende vaatjes onder het netvlies). Klachten zijn vervormd zien (rechte lijnen lijken krom), een vlek in het centrum en moeite met lezen en gezichten herkennen; het perifere zien blijft bewaard. Risicofactoren: leeftijd, roken en erfelijkheid. De natte vorm wordt met anti-VEGF-injecties behandeld.</p>","image_url":"","wiki_title":"Macular degeneration","match":"droge maculadegeneratie","option_only":true},"bloeding bij een maculadegeneratie":{"title":"Leeftijdsgebonden maculadegeneratie","short":"Bij maculadegeneratie raakt de gele vlek (het centrum van het netvlies) beschadigd, met verlies van het centrale zien.","definition":"<p>Bij <strong>LMD</strong> is er een droge vorm (drusen en atrofie) en een natte vorm (nieuwvorming van lekkende vaatjes onder het netvlies). Klachten zijn vervormd zien (rechte lijnen lijken krom), een vlek in het centrum en moeite met lezen en gezichten herkennen; het perifere zien blijft bewaard. Risicofactoren: leeftijd, roken en erfelijkheid. De natte vorm wordt met anti-VEGF-injecties behandeld.</p>","image_url":"","wiki_title":"Macular degeneration","match":"bloeding bij een maculadegeneratie","option_only":true},"amyotrofische laterale sclerose (als)":{"title":"Amyotrofische laterale sclerose (ALS)","short":"ALS is een progressieve, dodelijke ziekte van zowel het bovenste als het onderste motorneuron.","definition":"<p>Bij <strong>ALS</strong> ontstaan asymmetrische zwakte, atrofie en fasciculaties (onderste motorneuron) samen met spasticiteit en hyperreflexie (bovenste motorneuron), vaak met slik- en spraakproblemen. Gevoel, oogbewegingen en blaasfunctie blijven meestal gespaard. Een deel heeft ook frontotemporale dementie. Riluzol vertraagt het beloop iets.</p>","image_url":"","wiki_title":"Amyotrophic lateral sclerosis","match":"amyotrofische laterale sclerose (als)","option_only":true},"elektrocardiografie (ecg)":{"title":"ECG (elektrocardiogram)","short":"Een ECG registreert de elektrische activiteit van het hart via elektroden op de huid.","definition":"<p>Een standaard <strong>12-afleidingen-ECG</strong> laat de P-top (boezemdepolarisatie), het QRS-complex (kamerdepolarisatie) en de T-top (repolarisatie) zien. Het wordt gebruikt om ritmestoornissen, geleidingsstoornissen, ischemie en infarct, hypertrofie en elektrolytstoornissen (bijv. hyperkaliëmie) op te sporen.</p>","image_url":"","wiki_title":"Electrocardiography","match":"elektrocardiografie (ecg)","option_only":true},"cornea-erosie":{"title":"Cornea-erosie","short":"Een cornea-erosie is een oppervlakkig defect in het hoornvliesepitheel, met pijn, tranen en lichtschuwheid.","definition":"<p>Een <strong>cornea-erosie</strong> ontstaat vaak door een krasje (vingernagel, tak) of contactlens. Met fluoresceïne kleurt het defect groen aan. Het geneest meestal binnen enkele dagen; bij contactlensdragers moet aan een bacteriële keratitis worden gedacht.</p>","image_url":"","wiki_title":"Corneal abrasion","match":"cornea-erosie","option_only":true},"ankyloserende spondylitis":{"title":"Ziekte van Bechterew (spondylitis ankylopoetica)","short":"De ziekte van Bechterew is een chronische ontsteking van de wervelkolom en SI-gewrichten, vaak bij jonge mannen met HLA-B27, met ochtendstijfheid en lage rugpijn.","definition":"<p>De <strong>ziekte van Bechterew</strong> is een axiale spondyloartritis: een chronische ontsteking van de <em>sacro-iliacale gewrichten</em> en de wervelkolom, met name de aanhechtingen van banden en pezen (enthesitis).</p><p>Ze begint meestal voor het 40e jaar met inflammatoire lage rugpijn: ochtendstijfheid, verbetering bij bewegen, ’s nachts pijn. Er is een sterke associatie met <em>HLA-B27</em>. Op termijn kan verbening de wervelkolom verstijven (‘bamboo spine’). Extra-articulair: uveïtis anterior, IBD en psoriasis.</p>","image_url":"","wiki_title":"Ankylosing spondylitis","match":"ankyloserende spondylitis","option_only":true},"bacteriële meningitis":{"title":"Meningitis","short":"Meningitis is een ontsteking van de hersenvliezen, met hoofdpijn, koorts, nekstijfheid en verminderd bewustzijn; bacteriële meningitis is een spoedgeval.","definition":"<p><strong>Meningitis</strong> is een ontsteking van de leptomeningen (pia en arachnoidea) en de liquor. Oorzaken zijn bacteriën (bij volwassenen vooral pneumokok en meningokok), virussen (vaak milder) en zelden schimmels.</p><p>Klassieke symptomen: hoofdpijn, koorts, nekstijfheid en een verlaagd bewustzijn; bij meningokokken soms petechiën. Diagnose via lumbaalpunctie (liquoronderzoek). Bacteriële meningitis vereist direct antibiotica en dexamethason.</p>","image_url":"","wiki_title":"Meningitis","match":"bacteriële meningitis","option_only":true},"benzodiazepines":{"title":"Oxazepam","short":"Oxazepam is een kortwerkend benzodiazepine dat angst vermindert en sederend werkt.","definition":"<p><strong>Benzodiazepinen</strong> versterken het effect van GABA op de GABA-A-receptor (vaker openen van het chloridekanaal). Oxazepam heeft geen actieve metabolieten en wordt via glucuronidering geklaard, waardoor het relatief geschikt is bij ouderen en leverfunctiestoornissen. Bijwerkingen: sufheid, vallen, geheugenstoornissen en afhankelijkheid bij langdurig gebruik. Antidotum: flumazenil.</p>","image_url":"","wiki_title":"Oxazepam","match":"benzodiazepines","option_only":true},"refractie afwijking":{"title":"Refractieafwijking","short":"Een refractieafwijking betekent dat het oog licht niet scherp op het netvlies focust: bijziendheid, verziendheid of astigmatisme.","definition":"<p>Bij <strong>myopie</strong> (bijziendheid) valt het brandpunt vóór de retina, bij <strong>hypermetropie</strong> (verziendheid) erachter, en bij <strong>astigmatisme</strong> is de breking niet in alle richtingen gelijk. Presbyopie is leeftijdsgebonden verlies van accommodatie. Verbetering van het zicht met een stenopeïsche opening wijst op een refractieprobleem. Correctie met bril, lenzen of refractiechirurgie.</p>","image_url":"","wiki_title":"Refractive error","match":"refractie afwijking","option_only":true},"meningeoom":{"title":"Meningeoom","short":"Een meningeoom is een meestal goedaardige, langzaam groeiende tumor uitgaande van de hersenvliezen.","definition":"<p>Een <strong>meningeoom</strong> gaat uit van arachnoïdale cellen en zit vast aan de dura. Het komt vaker voor bij vrouwen en na schedelbestraling, groeit langzaam en drukt het hersenweefsel weg. Op MRI kleurt het egaal aan, vaak met een ‘dural tail’.</p>","image_url":"","wiki_title":"Meningioma","match":"meningeoom|meningeomen","option_only":true},"striatum":{"title":"Striatum","short":"Het striatum (nucleus caudatus en putamen) is het belangrijkste inputstation van de basale kernen.","definition":"<p>Het <strong>striatum</strong> ontvangt projecties uit vrijwel de hele cortex en dopaminerge input uit de substantia nigra. Via de directe en indirecte route stuurt het de output van de basale kernen. Het ventrale deel (nucleus accumbens) speelt een rol bij beloning en motivatie.</p>","image_url":"","wiki_title":"Striatum","match":"striatum|corpus striatum","option_only":true},"ventrale striatum":{"title":"Striatum","short":"Het striatum (nucleus caudatus en putamen) is het belangrijkste inputstation van de basale kernen.","definition":"<p>Het <strong>striatum</strong> ontvangt projecties uit vrijwel de hele cortex en dopaminerge input uit de substantia nigra. Via de directe en indirecte route stuurt het de output van de basale kernen. Het ventrale deel (nucleus accumbens) speelt een rol bij beloning en motivatie.</p>","image_url":"","wiki_title":"Striatum","match":"ventrale striatum","option_only":true},"n. tibialis":{"title":"N. tibialis","short":"De n. tibialis is een eindtak van de n. ischiadicus die de kuitspieren en de voetzool innerveert.","definition":"<p>De <strong>n. tibialis</strong> loopt door de knieholte en achter de malleolus medialis door de tarsale tunnel naar de voetzool. Hij innerveert de plantairflexoren en de kleine voetspieren en sensibel de voetzool. Beknelling achter de malleolus heet het tarsaletunnelsyndroom.</p>","image_url":"","wiki_title":"Tibial nerve","match":"n. tibialis|nervus tibialis","option_only":true},"horner syndroom":{"title":"Syndroom van Horner","short":"Het syndroom van Horner is uitval van de sympathische innervatie van het oog, met ptosis, miosis en soms verminderd zweten.","definition":"<p>Bij <strong>Horner</strong> is de pupil kleiner (vooral zichtbaar in het donker), hangt het bovenooglid iets en zweet de gezichtshelft soms minder. Oorzaken liggen ergens langs de lange sympathische baan: hersenstam (bijv. infarct), ruggenmerg, longtop (Pancoast-tumor) of rond de a. carotis (dissectie, met pijn).</p>","image_url":"","wiki_title":"Horner's syndrome","match":"horner syndroom|syndroom van horner|horner","option_only":true},"hsv keratitis":{"title":"Herpes simplex-keratitis","short":"Herpes simplex-keratitis is een virale hoornvliesinfectie met een kenmerkende boomvormige (dendritische) afwijking bij fluoresceïnekleuring.","definition":"<p><strong>HSV-keratitis</strong> geeft een rood, pijnlijk, lichtschuw oog, vaak recidiverend. De gevoeligheid van het hoornvlies is verminderd. Behandeling met antivirale middelen; corticosteroïddruppels zonder antivirale dekking kunnen het ernstig verergeren.</p>","image_url":"","wiki_title":"Herpes simplex keratitis","match":"hsv keratitis|herpes simplex keratitis|herpeskeratitis","option_only":true},"parenchymateuze bloeding":{"title":"Intracerebrale bloeding","short":"Een intracerebrale bloeding is een bloeding in het hersenweefsel zelf, meestal door hypertensie of amyloïdangiopathie.","definition":"<p><strong>Hypertensieve bloedingen</strong> liggen vaak diep (basale kernen, thalamus, pons, cerebellum); <strong>lobaire bloedingen</strong> bij ouderen passen bij amyloïdangiopathie. Andere oorzaken: antistolling, vaatmalformaties en tumoren. Klachten ontstaan plotseling, vaak met hoofdpijn en braken. Diagnose met CT.</p>","image_url":"","wiki_title":"Intracerebral hemorrhage","match":"parenchymateuze bloeding|intracerebrale bloeding|hersenbloeding","option_only":true},"n. peroneus":{"title":"N. fibularis (peroneus) communis","short":"De n. fibularis communis loopt om het collum fibulae en splitst in een diepe en oppervlakkige tak; uitval geeft een klapvoet.","definition":"<p>De <strong>n. fibularis communis</strong> ligt oppervlakkig rond de fibulakop en raakt daar makkelijk bekneld (benen over elkaar slaan, gips, gewichtsverlies, fractuur). Uitval geeft een voetheffersparese met klapvoet en gevoelsstoornis aan de voetrug. Het onderscheid met een L5-radiculopathie: bij een peroneusletsel is de inversie (m. tibialis posterior) intact.</p>","image_url":"","wiki_title":"Common fibular nerve","match":"n. peroneus","option_only":true},"amoxycilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline","option_only":true},"amoxycilline oraal":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline oraal","option_only":true},"hydrocephalus":{"title":"Hydrocefalus","short":"Bij hydrocefalus hoopt liquor zich op in de ventrikels door een stoornis in productie, doorstroming of resorptie.","definition":"<p>Bij een <strong>obstructieve</strong> hydrocefalus is de doorstroming geblokkeerd (bijv. aquaductstenose, tumor); bij een <strong>communicerende</strong> de resorptie (na bloeding of meningitis). Bij zuigelingen groeit de schedelomtrek snel en is de fontanel bol; bij volwassenen ontstaan hoofdpijn, braken en sufheid. Normaledrukhydrocefalus geeft loopstoornis, incontinentie en dementie.</p>","image_url":"","wiki_title":"Hydrocephalus","match":"hydrocephalus|hydrocefalus|waterhoofd","option_only":true},"subarachnoïdale bloeding":{"title":"Subarachnoïdale bloeding (SAB)","short":"Een subarachnoïdale bloeding is een bloeding tussen de hersenvliezen, meestal door een gescheurd aneurysma, met plotselinge zeer hevige hoofdpijn.","definition":"<p>Een <strong>SAB</strong> geeft binnen seconden de ergste hoofdpijn ooit (‘donderslag’), vaak met braken, nekstijfheid en bewustzijnsdaling. Diagnose met CT, zo nodig gevolgd door een lumbaalpunctie (xanthochromie). Complicaties: nabloeding, vasospasme met infarcten en hydrocefalus. Het aneurysma wordt gecoild of geclipt.</p>","image_url":"","wiki_title":"Subarachnoid hemorrhage","match":"subarachnoïdale bloeding|sab|subarachnoidale bloeding","option_only":true},"arterioveneuze fistels":{"title":"Arterioveneuze fistel","short":"Een arterioveneuze fistel is een directe verbinding tussen een slagader en een ader, zonder capillairbed.","definition":"<p>Een <strong>AV-fistel</strong> kan aangeboren zijn (malformatie), door trauma ontstaan of chirurgisch worden aangelegd als toegang voor hemodialyse. Grote shunts kunnen high-output hartfalen geven. Arterioveneuze malformaties in het brein kunnen bloeden of epilepsie veroorzaken.</p>","image_url":"","wiki_title":"Arteriovenous fistula","match":"arterioveneuze fistels|arterioveneuze fistel|av-fistel|arterioveneuze anastomosen|arterioveneuze malformatie","option_only":true},"propranolol":{"title":"Propranolol","short":"Propranolol is een niet-selectieve, lipofiele bètablokker, gebruikt o.a. bij tremor, migraineprofylaxe, angstklachten, hyperthyreoïdie en portale hypertensie.","definition":"<p>Doordat <strong>propranolol</strong> ook β2-receptoren blokkeert, kan het bronchospasme geven en is het gecontra-indiceerd bij astma. Het werkt goed tegen lichamelijke angstverschijnselen (trillen, hartkloppingen) en tegen infantiele hemangiomen bij baby's.</p>","image_url":"","wiki_title":"Propranolol","match":"propranolol","option_only":true},"ziekte van meniere":{"title":"Ziekte van Ménière","short":"De ziekte van Ménière geeft aanvallen van draaiduizeligheid met oorsuizen, een vol gevoel in het oor en schommelend gehoorverlies.","definition":"<p>Bij <strong>Ménière</strong> is er waarschijnlijk een ophoping van endolymfe in het binnenoor (endolymfatische hydrops). Aanvallen duren 20 minuten tot uren. Het gehoorverlies is aanvankelijk laagfrequent en wisselend, later blijvend. In late stadia kunnen otolietcrises van Tumarkin optreden.</p>","image_url":"","wiki_title":"Ménière's disease","match":"ziekte van meniere|ziekte van ménière|ménière","option_only":true},"scleritis":{"title":"Scleritis","short":"Scleritis is een ernstige, pijnlijke ontsteking van het oogwit, vaak bij systemische auto-immuunziekten.","definition":"<p>Bij <strong>scleritis</strong> is er een diepe, borende oogpijn die ’s nachts erger is, met een paarsrode verkleuring die niet verbleekt bij druppelen met fenylefrine (anders dan episcleritis). Ze komt voor bij reumatoïde artritis en GPA en kan het oog ernstig beschadigen; systemische behandeling is nodig.</p>","image_url":"","wiki_title":"Scleritis","match":"scleritis","option_only":true},"uveitis posterior":{"title":"Uveïtis posterior","short":"Uveïtis posterior is een ontsteking van het achterste deel van het oog (choroidea en/of retina), met wazig zien en vlekken, meestal zonder pijn of rood oog.","definition":"<p>Oorzaken van <strong>uveïtis posterior</strong> zijn o.a. toxoplasmose (meest voorkomend), CMV (bij afweerstoornissen), sarcoïdose, syfilis, tuberculose en de ziekte van Behçet. Diagnose met fundoscopie; behandeling van de oorzaak, eventueel met corticosteroïden.</p>","image_url":"","wiki_title":"Uveitis","match":"uveitis posterior|uveïtis posterior|chorioretinitis","option_only":true},"allergische conjunctivitis":{"title":"Allergische conjunctivitis","short":"Allergische conjunctivitis is een allergische ontsteking van het bindvlies, met jeukende, tranende en rode ogen aan beide kanten.","definition":"<p>De <strong>allergische conjunctivitis</strong> is vaak seizoensgebonden (pollen) of het hele jaar door (huisstofmijt, huisdieren), meestal samen met allergische rhinitis. Jeuk is het belangrijkste onderscheid met infectieuze conjunctivitis. Behandeling met antihistaminica of mestcelstabiliserende oogdruppels.</p>","image_url":"","wiki_title":"Allergic conjunctivitis","match":"allergische conjunctivitis|jeukende en tranende ogen|jeuk in de ogen","option_only":true},"adenovirale conjunctivitis":{"title":"Adenovirale conjunctivitis","short":"Adenovirale conjunctivitis is een zeer besmettelijke virale bindvliesontsteking met tranen, rood oog en vaak een gezwollen preauriculaire lymfeklier.","definition":"<p>Bij <strong>adenovirale conjunctivitis</strong> begint het vaak aan één oog en volgt het andere enkele dagen later. Bij keratoconjunctivitis epidemica kunnen hoornvliesinfiltraten weken tot maanden wazig zien geven. Strikte handhygiëne is belangrijk, ook in de spreekkamer.</p>","image_url":"","wiki_title":"Adenoviral conjunctivitis","match":"adenovirale conjunctivitis|keratoconjunctivitis epidemica","option_only":true},"hypopyon":{"title":"Hypopyon","short":"Een hypopyon is een laagje pus onderin de voorste oogkamer, bij een ernstige ontsteking of infectie van het oog.","definition":"<p>Een <strong>hypopyon</strong> komt voor bij een bacteriële of schimmelkeratitis, endoftalmitis en ernstige uveïtis anterior (o.a. bij HLA-B27 en de ziekte van Behçet). Het vraagt om dringende oogheelkundige beoordeling.</p>","image_url":"","wiki_title":"Hypopyon","match":"hypopyon","option_only":true},"post-punctionele hoofdpijn":{"title":"Postpunctionele hoofdpijn","short":"Postpunctionele hoofdpijn ontstaat na een lumbaalpunctie of spinale anesthesie door lekkage van liquor; de hoofdpijn verergert bij rechtop staan.","definition":"<p>De <strong>postpunctionele hoofdpijn</strong> begint meestal binnen enkele dagen en verdwijnt bij liggen. Het risico is kleiner bij dunnere, atraumatische naalden. Bij aanhoudende klachten kan een epidurale bloodpatch het lek dichten.</p>","image_url":"","wiki_title":"Post-dural-puncture headache","match":"post-punctionele hoofdpijn|postpunctionele hoofdpijn","option_only":true},"motorische afasie":{"title":"Afasie van Broca (motorische afasie)","short":"Bij een motorische (Broca-)afasie is het spreken moeizaam en telegramstijl, terwijl het begrip relatief goed is.","definition":"<p>Een <strong>Broca-afasie</strong> ontstaat bij schade aan de inferieure frontale gyrus van de dominante hemisfeer, vaak met een rechtszijdige hemiparese. Bij een sensorische (Wernicke-)afasie is de spraak vloeiend maar inhoudsloos en het begrip slecht. Bij een globale of gemengde afasie zijn beide gestoord.</p>","image_url":"","wiki_title":"Expressive aphasia","match":"motorische afasie|broca-afasie|expressieve afasie","option_only":true},"gemengde afasie":{"title":"Globale (gemengde) afasie","short":"Bij een globale afasie zijn zowel het spreken als het begrijpen van taal ernstig gestoord, door uitgebreide schade in de taalgebieden.","definition":"<p>Een <strong>globale afasie</strong> ontstaat meestal bij een groot infarct in het stroomgebied van de linker a. cerebri media. Bij een Wernicke-afasie (temporaal) is de spraak vloeiend met veel parafasieën, maar het taalbegrip ernstig gestoord.</p>","image_url":"","wiki_title":"Global aphasia","match":"gemengde afasie|globale afasie|wernicke-afasie|sensorische afasie","option_only":true},"spinocerebellaire ataxie van friedreich":{"title":"Ataxie van Friedreich","short":"De ataxie van Friedreich is een autosomaal recessieve neurodegeneratieve ziekte met progressieve ataxie, beginnend in de jeugd.","definition":"<p>Bij <strong>Friedreich</strong> (GAA-repeatexpansie in het frataxine-gen) ontstaan in de kindertijd of adolescentie loopataxie, dysartrie, areflexie, verlies van positiezin, Babinski-reflexen, scoliose en holvoeten. Hypertrofische cardiomyopathie en diabetes bepalen mede de prognose.</p>","image_url":"","wiki_title":"Friedreich's ataxia","match":"spinocerebellaire ataxie van friedreich|ataxie van friedreich|friedreich","option_only":true},"area postremasyndroom":{"title":"Area postrema-syndroom","short":"Het area postrema-syndroom is onbedwingbaar hikken, misselijkheid en braken door een laesie in de area postrema, kenmerkend voor neuromyelitis optica.","definition":"<p>De <strong>area postrema</strong> in de bodem van de vierde ventrikel is het braakcentrum (chemoreceptor triggerzone) en heeft geen bloed-hersenbarrière. Aanhoudend braken en hikken zonder andere verklaring kan wijzen op neuromyelitis optica.</p>","image_url":"","wiki_title":"Area postrema","match":"area postremasyndroom|area postrema","option_only":true},"m. masseter":{"title":"M. masseter","short":"De m. masseter is de krachtige kauwspier die de kaak sluit; geïnnerveerd door de n. mandibularis (V3).","definition":"<p>De <strong>m. masseter</strong> loopt van de jukboog naar de buitenzijde van de onderkaak. Samen met de m. temporalis en mm. pterygoidei zorgt hij voor het kauwen. Kaakklem (trismus) komt voor bij tetanus, een peritonsillair abces en tandinfecties.</p>","image_url":"","wiki_title":"Masseter muscle","match":"m. masseter|musculus masseter|kauwspier","option_only":true},"m. trapezius":{"title":"M. trapezius","short":"De m. trapezius is de grote, oppervlakkige rug- en nekspier die de schouder optrekt en de scapula draait; geïnnerveerd door de n. accessorius.","definition":"<p>Uitval van de <strong>m. trapezius</strong> (bijv. na letsel van de n. accessorius bij een halsklierbiopt) geeft een afhangende schouder, moeite met het heffen van de arm boven het hoofd en een lichte scapula alata.</p>","image_url":"","wiki_title":"Trapezius muscle","match":"m. trapezius|musculus trapezius|monnikskapspier","option_only":true},"positieve test van lasègue":{"title":"Proef van Lasègue","short":"Bij de proef van Lasègue wordt het gestrekte been geheven; uitstralende pijn in het been tussen 30 en 70° wijst op prikkeling van een lumbosacrale zenuwwortel.","definition":"<p>Een positieve <strong>Lasègue</strong> past bij een lumbosacraal radiculair syndroom (meestal L5 of S1, door een hernia). De gekruiste Lasègue (pijn in het aangedane been bij heffen van het andere) is specifieker.</p>","image_url":"","wiki_title":"Straight leg raise","match":"positieve test van lasègue|proef van lasègue|lasègue|straight leg raise","option_only":true},"macula-oedeem":{"title":"Maculopathie","short":"Maculopathie is een aandoening van de macula, het centrum van het netvlies, met verlies van het scherpe zien.","definition":"<p>Voorbeelden zijn leeftijdsgebonden maculadegeneratie, <strong>diabetisch maculaoedeem</strong> (lekkage uit beschadigde vaatjes), maculaoedeem na een veneuze occlusie of operatie, en erfelijke maculadystrofieën. Behandeling van oedeem vaak met anti-VEGF-injecties.</p>","image_url":"","wiki_title":"Macular edema","match":"macula-oedeem","option_only":true},"subconjunctivale bloeding":{"title":"Hyposfagma","short":"Een hyposfagma is een onschuldige bloeding onder het bindvlies van het oog: een scherp begrensde felrode vlek, zonder pijn of visusklachten.","definition":"<p>Bij een <strong>hyposfagma</strong> knapt een bloedvaatje onder de conjunctiva. Het oog krijgt een scherp begrensde, felrode vlek op het oogwit, zonder pijn, afscheiding of slechter zien.</p><p>Oorzaken: hoesten, persen, niezen, wrijven, hypertensie of antistolling; vaak is er geen oorzaak. Het verdwijnt vanzelf binnen 1–3 weken. Alleen bij trauma, herhaling of bloedingsneiging is verder onderzoek nodig.</p>","image_url":"","wiki_title":"Subconjunctival bleeding","match":"subconjunctivale bloeding","option_only":true},"trombocyt-aggregatieremmers":{"title":"Clopidogrel","short":"Clopidogrel is een plaatjesremmer die de ADP-receptor P2Y12 op bloedplaatjes onomkeerbaar blokkeert.","definition":"<p><strong>Clopidogrel</strong> is een prodrug die via CYP2C19 in de lever wordt geactiveerd. De actieve metaboliet blokkeert de P2Y12-receptor, zodat ADP de plaatjes niet meer kan activeren. Het wordt gebruikt na een acuut coronair syndroom en stentplaatsing (vaak samen met acetylsalicylzuur) en bij herseninfarct en perifeer vaatlijden. Bijwerking: bloedingen.</p>","image_url":"","wiki_title":"Clopidogrel","match":"trombocyt-aggregatieremmers","option_only":true},"thiazide-diuretica":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazide-diuretica","option_only":true},"wervelkanaalstenose":{"title":"Lumbale kanaalstenose","short":"Bij lumbale kanaalstenose is het wervelkanaal in de lage rug vernauwd, met pijn in de benen bij lopen die verbetert bij voorover buigen.","definition":"<p>Typisch voor <strong>neurogene claudicatio</strong> is dat de klachten verbeteren bij zitten of voorover buigen (fietsen gaat beter dan lopen), in tegenstelling tot vasculaire claudicatio, die bij stilstaan al verbetert. Behandeling: fysiotherapie, pijnstilling en eventueel decompressie.</p>","image_url":"","wiki_title":"Lumbar spinal stenosis","match":"wervelkanaalstenose","option_only":true},"wortel l5":{"title":"Wortel L5","short":"Een L5-radiculopathie geeft pijn en gevoelsstoornis over de buitenkant van het onderbeen en de voetrug en zwakte van de grote-teenextensie.","definition":"<p>Bij uitval van de <strong>wortel L5</strong> (vaak door een hernia L4–L5) zijn de m. extensor hallucis longus en de voetheffers zwak, en soms de heupabductoren. De reflexen zijn meestal normaal. Bij een S1-radiculopathie zijn juist de achillespeesreflex en de plantairflexie verminderd, met gevoelsstoornis aan de buitenkant van de voet.</p>","image_url":"","wiki_title":"Radiculopathy","match":"wortel l5|l5-radiculopathie","option_only":true},"wortel s1":{"title":"Wortel S1","short":"Een S1-radiculopathie geeft pijn over de achterkant van het been naar de buitenkant van de voet, zwakte van de plantairflexie en een verlaagde achillespeesreflex.","definition":"<p>Uitval van de <strong>wortel S1</strong> ontstaat meestal door een hernia L5–S1. Patiënten kunnen moeilijk op de tenen lopen. Bij uitval van meerdere sacrale wortels met blaasstoornis en rijbroekanesthesie moet aan een caudasyndroom worden gedacht (spoed).</p>","image_url":"","wiki_title":"Radiculopathy","match":"wortel s1|s1-radiculopathie","option_only":true},"omgekeerde lasègue":{"title":"Omgekeerde Lasègue (femoralis-rektest)","short":"Bij de omgekeerde Lasègue wordt in buikligging de knie gebogen; pijn aan de voorkant van de dij wijst op prikkeling van een hoge lumbale wortel (L2–L4).","definition":"<p>De <strong>omgekeerde Lasègue</strong> rekt de n. femoralis en de wortels L2–L4. Een positieve test past bij een hoge lumbale hernia; de gewone Lasègue test vooral L5 en S1.</p>","image_url":"","wiki_title":"","match":"omgekeerde lasègue|femoralis-rektest","option_only":true},"globus pallidus":{"title":"Globus pallidus","short":"De globus pallidus is een kern van de basale ganglia met een externe en interne kern, die vooral remmende (GABA-erge) output geeft.","definition":"<p>De <strong>globus pallidus interna</strong> is samen met de substantia nigra pars reticulata de uitgangskern van de basale ganglia; de externa is een schakel in de indirecte route.</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus","option_only":true},"bitemporale hemianopsie":{"title":"Bitemporale hemianopsie","short":"Bij bitemporale hemianopsie vallen de buitenste (temporale) gezichtsvelden van beide ogen uit, door compressie van het chiasma opticum.","definition":"<p>In het chiasma kruisen de vezels van de nasale netvlieshelften, die het temporale gezichtsveld zien. Een <strong>bitemporale hemianopsie</strong> ontstaat daarom bij druk van onderaf (hypofyseadenoom) of bovenaf (craniofaryngioom).</p>","image_url":"","wiki_title":"Bitemporal hemianopsia","match":"bitemporale hemianopsie","option_only":true},"arteria carotis interna":{"title":"A. carotis interna","short":"De a. carotis interna voorziet het grootste deel van de grote hersenen en het oog; ze geeft geen takken af in de hals.","definition":"<p>De <strong>a. carotis interna</strong> loopt door het rotsbeen en de sinus cavernosus en splitst in de a. cerebri anterior en media; de eerste tak is de a. ophthalmica. Een stenose of dissectie kan een TIA, herseninfarct of amaurosis fugax geven.</p>","image_url":"","wiki_title":"Internal carotid artery","match":"arteria carotis interna|a. carotis interna|carotis interna","option_only":true},"natalizumab":{"title":"Natalizumab","short":"Natalizumab is een antistof tegen het integrine α4, die het binnendringen van lymfocyten in het brein remt; gebruikt bij actieve MS.","definition":"<p><strong>Natalizumab</strong> is zeer effectief bij MS, maar kan bij dragers van het JC-virus progressieve multifocale leuko-encefalopathie (PML) veroorzaken; daarom wordt het risico vooraf ingeschat.</p>","image_url":"","wiki_title":"Natalizumab","match":"natalizumab","option_only":true},"candida-infectie":{"title":"Candida albicans","short":"Candida albicans is een gist die normaal op slijmvliezen voorkomt en bij verminderde weerstand spruw, vaginale schimmelinfectie of invasieve infecties geeft.","definition":"<p><strong><em>Candida albicans</em></strong> is een gist (schimmel) die bij veel mensen in mond, darm en vagina voorkomt. Hij kan zowel als ronde gistcel als met (pseudo)hyfen groeien.</p><p>Bij een verstoorde flora (antibiotica) of verminderde afweer veroorzaakt hij oppervlakkige infecties zoals spruw (orale candidiasis), vaginale candidiasis en intertrigo. Bij ernstig immuungecompromitteerden of patiënten met lijnen kan een invasieve candidemie ontstaan.</p>","image_url":"","wiki_title":"Candida albicans","match":"candida-infectie","option_only":true},"vitamine b12 deficiëntie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b12 deficiëntie","option_only":true},"metformine (biguanide)":{"title":"Metformine","short":"Metformine is het eerstekeusmiddel bij diabetes mellitus type 2; het remt vooral de glucoseproductie door de lever.","definition":"<p><strong>Metformine</strong> is een biguanide dat de <em>gluconeogenese in de lever</em> remt en de insulinegevoeligheid van spier verbetert. Het stimuleert de insulineafgifte niet en geeft daarom op zichzelf geen hypoglykemie.</p><p>Het is eerste keus bij diabetes type 2 en is gewichtsneutraal. Bijwerkingen zijn vooral maag-darmklachten; zeldzaam is lactaatacidose (risico bij ernstige nierfunctiestoornis). Langdurig gebruik kan vitamine B12-tekort geven.</p>","image_url":"","wiki_title":"Metformin","match":"metformine (biguanide)","option_only":true},"adenovirusinfectie":{"title":"Adenovirus","short":"Adenovirussen zijn niet-omhulde DNA-virussen die verkoudheid, keelontsteking, conjunctivitis en gastro-enteritis veroorzaken.","definition":"<p><strong>Adenovirussen</strong> zijn niet-omhulde, dubbelstrengs DNA-virussen. Omdat ze geen envelop hebben, zijn ze stabiel in de omgeving en lastig te inactiveren.</p><p>Ze veroorzaken vooral bij kinderen infecties van de bovenste luchtwegen (faryngitis), conjunctivitis (o.a. faryngoconjunctivale koorts), gastro-enteritis en soms pneumonie. Ze worden ook gebruikt als vector in vaccins en gentherapie.</p>","image_url":"","wiki_title":"Adenoviridae","match":"adenovirusinfectie","option_only":true},"uveitis":{"title":"Uveïtis anterior","short":"Uveïtis anterior is een ontsteking van iris en corpus ciliare, met een pijnlijk rood oog, lichtschuwheid en wazig zien.","definition":"<p>Bij <strong>uveïtis anterior</strong> zijn er cellen en flare in de voorste oogkamer, ciliaire injectie en soms een nauwe of onregelmatige pupil (synechieën). Het kan samenhangen met HLA-B27-gerelateerde ziekten, sarcoïdose, JIA of infecties. Behandeling met corticosteroïd- en pupilverwijdende druppels.</p>","image_url":"","wiki_title":"Uveitis","match":"uveitis","option_only":true},"migraine":{"title":"Migraine","short":"Aanvalsgewijze, vaak eenzijdige kloppende hoofdpijn met misselijkheid, foto- en fonofobie, soms met aura. Duurt uren tot een dag.","definition":"<p><b>Migraine</b>-aanvallen worden verergerd door inspanning; de patiënt zoekt rust in een donkere kamer. Aanvalsbehandeling met triptanen bij onvoldoende effect van NSAID's.</p>","image_url":"","wiki_title":"Migraine","match":"migraine","option_only":true},"acetylcholinereceptor":{"title":"Acetylcholinereceptor-antistoffen","short":"Antistoffen tegen de acetylcholinereceptor van de neuromusculaire overgang, kenmerkend voor myasthenia gravis. Geven wisselende, ergonome spierzwakte.","definition":"<p>Bij <b>myasthenia gravis</b> blokkeren <b>acetylcholinereceptor</b>-antistoffen de prikkeloverdracht, met belastingsafhankelijke zwakte (o.a. dubbelzien, zwakte 's avonds).</p>","image_url":"","wiki_title":"Myasthenia gravis","match":"acetylcholinereceptor","option_only":true},"progressieve supranucleaire paralyse (psp)":{"title":"Progressieve supranucleaire paralyse (PSP)","short":"Atypisch parkinsonisme met vroege vallen en verticale blikparese (niet naar beneden kunnen kijken).","definition":"<p>Neurodegeneratief atypisch parkinsonsyndroom (tauopathie) met symmetrisch parkinsonisme, vroege posturele instabiliteit met achterovervallen en een supranucleaire verticale blikparese.</p>","image_url":"","wiki_title":"Progressive supranuclear palsy","match":"progressieve supranucleaire paralyse (psp)","option_only":true},"polyneuropathie":{"title":"Polyneuropathie","short":"Diffuse aandoening van perifere zenuwen, vaak symmetrisch distaal, met sensibiliteitsstoornissen en verlaagde reflexen.","definition":"<p><b>Polyneuropathie</b> is een diffuse aantasting van perifere zenuwen, meestal symmetrisch en distaal (sok-handschoenpatroon), met sensibiliteitsstoornissen, verlaagde reflexen en soms spierzwakte. Frequente oorzaken: diabetes en alcohol.</p>","image_url":"","wiki_title":"Polyneuropathy","match":"polyneuropathie","option_only":true},"verhoogde oogboldruk (glaucoom)":{"title":"Glaucoom","short":"Beschadiging van de oogzenuw, vaak door verhoogde oogdruk, met blijvend gezichtsvelduitval.","definition":"<p>Glaucoom is een progressieve beschadiging van de nervus opticus, vaak samenhangend met een verhoogde oogboldruk. Het veroorzaakt onomkeerbare gezichtsvelduitval en kan onbehandeld tot blindheid leiden.</p>","image_url":"","wiki_title":"Glaucoma","match":"verhoogde oogboldruk (glaucoom)","option_only":true},"substantia nigra":{"title":"Substantia nigra","short":"Dopaminerge kern in het mesencephalon, deel van de basale ganglia.","definition":"<p>De <b>substantia nigra</b> zendt dopaminerge projecties naar het striatum; degeneratie leidt tot de ziekte van Parkinson.</p>","image_url":"","wiki_title":"Substantia nigra","match":"substantia nigra","option_only":true},"corticobasale degeneratie (cbd)":{"title":"Corticobasale degeneratie (CBD)","short":"Atypisch parkinsonisme, meestal asymmetrisch, met apraxie en corticale sensibele stoornissen.","definition":"<p>Zeldzaam atypisch parkinsonsyndroom met sterk asymmetrische rigiditeit, apraxie, corticale sensibele uitval en soms het alien-limb fenomeen.</p>","image_url":"","wiki_title":"Corticobasal degeneration","match":"corticobasale degeneratie (cbd)","option_only":true},"rivastigmine":{"title":"Rivastigmine","short":"Cholinesteraseremmer voor de ziekte van Alzheimer en de dementie bij de ziekte van Parkinson.","definition":"<p><b>Rivastigmine</b> remt zowel acetylcholinesterase als butyrylcholinesterase en is ook als pleister verkrijgbaar. Cholinerge bijwerkingen zoals misselijkheid en braken komen vaak voor.</p>","image_url":"","wiki_title":"Rivastigmine","match":"rivastigmine","option_only":true},"carbamazepine":{"title":"Carbamazepine","short":"Carbamazepine is een anti-epilepticum dat ook tegen neuropathische pijn wordt ingezet; het wordt gemetaboliseerd door CYP3A4 en is gevoelig voor interacties.","definition":"<p><strong>Carbamazepine</strong> is een anti-epilepticum en stemmingsstabilisator dat ook bij neuropathische pijn wordt gebruikt. Het wordt voornamelijk afgebroken door het lever-enzym <em>CYP3A4</em>. Remmers van CYP3A4 (zoals macrolide-antibiotica) verlagen de afbraak, waardoor de bloedspiegel en de kans op bijwerkingen stijgen.</p>","image_url":"","wiki_title":"Carbamazepine","match":"carbamazepine","option_only":true},"donepezil":{"title":"Donepezil","short":"Cholinesteraseremmer voor de symptomatische behandeling van de ziekte van Alzheimer.","definition":"<p><b>Donepezil</b>, galantamine en rivastigmine remmen de afbraak van acetylcholine. Donepezil wordt eenmaal daags als tablet ingenomen. Bijwerkingen zijn cholinerg: misselijkheid, braken, bradycardie en slapeloosheid.</p>","image_url":"","wiki_title":"Donepezil","match":"donepezil","option_only":true},"ectropion":{"title":"Ectropion","short":"Naar buiten gekantelde stand van het (onder)ooglid, waardoor het oog niet goed sluit en gaat tranen.","definition":"<p><b>Ectropion</b> is een uitwaartse rotatie van de ooglidrand, meestal senieel/atonisch. Het geeft epifora (tranen), expositiekeratopathie en irritatie.</p>","image_url":"","wiki_title":"Ectropion","match":"ectropion","option_only":true},"ulcus corneae":{"title":"Ulcus corneae","short":"Defect (zweer) van het hoornvlies-epitheel, vaak infectieus. Riscofactor is contactlensdracht; toont aankleuring met fluoresceïne.","definition":"<p>Een <b>ulcus corneae</b> is een pijnlijk, rood oog met een fluoresceïne-aankleurend corneadefect; een oogheelkundige spoedsituatie bij contactlensdragers.</p>","image_url":"","wiki_title":"Corneal ulcer","match":"ulcus corneae","option_only":true},"drop attack":{"title":"Drop attack","short":"Plotselinge val zonder bewustzijnsverlies door een korte verslapping van de benen. Meestal bij oudere vrouwen, oorzaak vaak onduidelijk.","definition":"<p>Een <b>drop attack</b> is een onverwachte val op de knieën zonder bewustzijnsverlies of prodromen; de patiënt kan direct weer opstaan. Het onderscheidt zich van syncope door het ontbreken van bewustzijnsverlies.</p>","image_url":"","wiki_title":"Drop attack","match":"drop attack","option_only":true},"syndroom van wallenberg":{"title":"Syndroom van Wallenberg","short":"Lateraal medullair infarct met o.a. gekruiste sensibiliteitsuitval van gelaat en lichaam.","definition":"<p>Het <b>syndroom van Wallenberg</b> (lateraal medullair infarct) geeft ipsilaterale gelaatsuitval van pijn/temperatuur en contralaterale uitval van het lichaam, plus vertigo, dysfagie en Horner.</p>","image_url":"","wiki_title":"Lateral medullary syndrome","match":"syndroom van wallenberg","option_only":true},"dermatomyositis":{"title":"Dermatomyositis","short":"Dermatomyositis is een auto-immune ontsteking van spieren en huid, met proximale spierzwakte, een heliotrope rash rond de ogen en Gottron-papels op de vingers.","definition":"<p><strong>Dermatomyositis</strong> is een idiopathische inflammatoire myopathie. Kenmerkend zijn symmetrische proximale spierzwakte, verhoogde spierenzymen (CK, aldolase, LDH) en typische huidafwijkingen: <em>heliotrope rash</em> (paars-rood rond de ogen) en <em>Gottron-papels</em> op de knokkels.</p>","image_url":"","wiki_title":"Dermatomyositis","match":"dermatomyositis","option_only":true},"multipele sclerose":{"title":"Multipele sclerose (MS)","short":"Chronische inflammatoire demyeliniserende ziekte van het centrale zenuwstelsel met haarden verspreid in tijd en plaats.","definition":"<p>Auto-immuunziekte met demyelinisatie in hersenen en ruggenmerg. Diagnose berust op dissociatie in tijd en plaats (MRI-lesies: periventriculair, juxtacorticaal, infratentorieel, spinaal). Beloopsvormen: relapsing-remitting, secundair progressief, primair progressief.</p>","image_url":"","wiki_title":"Multiple sclerosis","match":"multipele sclerose","option_only":true},"ulcus cornea":{"title":"Ulcus cornea (cornea-ulcus)","short":"Defect van het hoornvliesepitheel met onderliggende infiltratie/infectie. Geeft een rood, pijnlijk oog met pus en visusdaling; spoedeisend.","definition":"<p><b>Ulcus cornea</b> is een (vaak bacterieel) infiltraat met epitheeldefect, aankleurend met fluoresceïne. Risico's zijn contactlensdracht en trauma. Onbehandeld dreigt perforatie en blijvende litteken/visusverlies.</p>","image_url":"","wiki_title":"Corneal ulcer","match":"ulcus cornea","option_only":true},"cataract":{"title":"Cataract","short":"Vertroebeling van de ooglens (staar), een behandelbare (reversibele) oorzaak van slechtziendheid.","definition":"<p>Cataract (staar) is een vertroebeling van de ooglens, waardoor het zicht geleidelijk verslechtert. Het is de meest voorkomende, maar goed behandelbare (reversibele) oorzaak van slechtziendheid; een staaroperatie herstelt het zicht.</p>","image_url":"","wiki_title":"Cataract","match":"cataract","option_only":true},"multipele sclerose (ms)":{"title":"Multipele sclerose (MS)","short":"Chronische inflammatoire demyeliniserende ziekte van het centrale zenuwstelsel met haarden verspreid in tijd en plaats.","definition":"<p>Auto-immuunziekte met demyelinisatie in hersenen en ruggenmerg. Diagnose berust op dissociatie in tijd en plaats (MRI-lesies: periventriculair, juxtacorticaal, infratentorieel, spinaal). Beloopsvormen: relapsing-remitting, secundair progressief, primair progressief.</p>","image_url":"","wiki_title":"Multiple sclerosis","match":"multipele sclerose (ms)","option_only":true},"natte maculadegeneratie":{"title":"Leeftijdsgebonden maculadegeneratie","short":"Bij maculadegeneratie raakt de gele vlek (het centrum van het netvlies) beschadigd, met verlies van het centrale zien.","definition":"<p>Bij <strong>LMD</strong> is er een droge vorm (drusen en atrofie) en een natte vorm (nieuwvorming van lekkende vaatjes onder het netvlies). Klachten zijn vervormd zien (rechte lijnen lijken krom), een vlek in het centrum en moeite met lezen en gezichten herkennen; het perifere zien blijft bewaard. Risicofactoren: leeftijd, roken en erfelijkheid. De natte vorm wordt met anti-VEGF-injecties behandeld.</p>","image_url":"","wiki_title":"Macular degeneration","match":"natte maculadegeneratie","option_only":true},"ankervene":{"title":"Ankervene (brugvene)","short":"Overbruggende venen die van het hersenoppervlak door de subdurale ruimte naar de durale sinussen lopen.","definition":"<p><b>Ankervenen</b> (brugvenen) voeren bloed van de corticale venen naar de sinus sagittalis superior en andere durale sinussen. Ze zijn dunwandig en worden opgerekt bij bewegingen van het brein ten opzichte van de schedel, vooral bij ouderen met hersenatrofie, alcoholisten en jonge kinderen.</p>","image_url":"","wiki_title":"Bridging vein","match":"ankervene","option_only":true},"bellse parese":{"title":"Bellse parese","short":"Idiopathische perifere aangezichtsverlamming; diagnose per exclusionem van andere oorzaken van facialisparese.","definition":"<p>Een <b>Bellse parese</b> is een acute, <b>idiopathische</b> perifere verlamming van de nervus facialis (aangezichtszenuw). Het is een uitsluitingsdiagnose: andere oorzaken zoals herpes zoster (Ramsay Hunt), CVA, borreliose en tumoren moeten zijn uitgesloten.</p>","image_url":"","wiki_title":"Bell's palsy","match":"bellse parese","option_only":true},"neovasculair glaucoom":{"title":"Neovasculair glaucoom","short":"Secundair glaucoom door nieuwvatvorming in de kamerhoek, vaak na ischemische retina-aandoeningen.","definition":"<p>Ernstige, pijnlijke vorm van glaucoom waarbij ischemie (bv. diabetes, veneuze occlusie) neovascularisatie van iris en kamerhoek uitlokt, met sterk verhoogde oogdruk en visusdaling.</p>","image_url":"","wiki_title":"Neovascular glaucoma","match":"neovasculair glaucoom","option_only":true},"status epilepticus":{"title":"Status epilepticus","short":"Langdurige of opeenvolgende epileptische aanvallen zonder herstel tussendoor.","definition":"<p><b>Status epilepticus</b> is een neurologische spoedsituatie; behandeling verloopt o.a. via benzodiazepinen zoals midazolam.</p>","image_url":"","wiki_title":"Status epilepticus","match":"status epilepticus","option_only":true},"metoclopramide":{"title":"Metoclopramide","short":"Dopamine-antagonist met anti-emetische en prokinetische werking; bij migraine ingezet tegen misselijkheid en om opname van pijnstillers te bevorderen.","definition":"<p>Metoclopramide blokkeert dopamine-D2-receptoren, remt misselijkheid/braken en versnelt de maaglediging. Bij een migraineaanval verbetert het de resorptie van orale analgetica.</p>","image_url":"","wiki_title":"Metoclopramide","match":"metoclopramide","option_only":true},"cmv-retinitis":{"title":"CMV-retinitis","short":"CMV-retinitis is een cytomegalovirus-infectie van het netvlies bij ernstig immuungecompromitteerden (aids, lage CD4), die onbehandeld tot blindheid leidt.","definition":"<p><b>CMV-retinitis</b> is een aids-definiërende opportunistische infectie; een patiënt met CMV-pneumonie loopt ook risico op retinitis.</p>","image_url":"","wiki_title":"Cytomegalovirus_retinitis","match":"cmv-retinitis","option_only":true},"metamorfopsie":{"title":"Metamorfopsie","short":"Vervormd zien van rechte lijnen; klassiek symptoom van maculapathologie.","definition":"<p><b>Metamorfopsie</b> is het waarnemen van rechte lijnen als golvend of vervormd, opgespoord met het Amslerkaartje.</p>","image_url":"","wiki_title":"Metamorphopsia","match":"metamorfopsie","option_only":true},"bloedonderzoek (calcium)":{"title":"Calcium","short":"Mineraal dat essentieel is voor botmineralisatie, spiercontractie en zenuwgeleiding. Opname in de darm wordt bevorderd door 1,25-OH-vitamine D (calcitriol).","definition":"<p><strong>Calcium</strong> wordt in de dunne darm actief opgenomen onder invloed van 1,25-dihydroxyvitamine D. Het grootste deel van het lichaamscalcium ligt opgeslagen in het skelet als hydroxyapatiet.</p>","image_url":"","wiki_title":"Calcium in biology","match":"bloedonderzoek (calcium)","option_only":true},"sinus cavernosustrombose":{"title":"Sinus-cavernosustrombose","short":"Sinus-cavernosustrombose is een zeldzame, levensbedreigende trombose van de sinus cavernosus, o.a. als complicatie van gezichtsinfecties (furunkels rond de neus).","definition":"<p><strong>Sinus-cavernosustrombose</strong> is een stolsel in de veneuze sinus aan de schedelbasis, vaak septisch na een gezichtsinfectie. Kenmerken zijn koorts, oogklachten (proptose, oftalmoplegie) en uitval van hersenzenuwen die door de sinus lopen.</p>","image_url":"","wiki_title":"Cavernous sinus thrombosis","match":"sinus cavernosustrombose","option_only":true},"foramen van luschka":{"title":"Foramen van Luschka","short":"Paarsgewijze laterale opening van het vierde ventrikel waardoor liquor de subarachnoïdale ruimte bereikt.","definition":"<p>De <b>foramina van Luschka</b> (lateraal) en het <b>foramen van Magendie</b> (mediaan) verbinden het vierde ventrikel met de subarachnoïdale ruimte; hierlangs verlaat de liquor het ventrikelsysteem.</p>","image_url":"","wiki_title":"Lateral aperture","match":"foramen van luschka","option_only":true},"kniepeesreflex":{"title":"Kniepeesreflex","short":"Monosynaptische rekkingsreflex van de m. quadriceps femoris (wortel L3-L4), opgewekt door slaan op de patellapees.","definition":"De <b>kniepeesreflex</b> is een monosynaptische reflex: rek van spierspoeltjes in de m. quadriceps femoris leidt direct tot contractie.","image_url":"","wiki_title":"Patellar reflex","match":"kniepeesreflex","option_only":true},"n infraorbitalis":{"title":"N. infraorbitalis","short":"De n. infraorbitalis is een tak van de n. maxillaris (V2) die de huid van wang, onderooglid, zijkant neus en bovenlip verzorgt.","definition":"<p>De <strong>n. infraorbitalis</strong> loopt over de orbitabodem door de canalis infraorbitalis en komt via het foramen infraorbitale op het gezicht. Bij een orbitabodemfractuur (blow-out) kan de zenuw beschadigd raken, met gevoelloosheid van wang en bovenlip als gevolg.</p>","image_url":"","wiki_title":"Infraorbital nerve","match":"n infraorbitalis","option_only":true},"hooggradig glioom":{"title":"Hooggradig glioom","short":"Agressieve hersentumor uit gliacellen (o.a. glioblastoom, WHO graad III-IV) met slechte prognose.","definition":"Een <b>hooggradig glioom</b> (bv. glioblastoom) heeft van de genoemde hersentumoren de slechtste overlevingsprognose.","image_url":"","wiki_title":"Glioma","match":"hooggradig glioom","option_only":true},"tubereuze sclerose":{"title":"Tubereuze sclerose","short":"Erfelijke aandoening met goedaardige tumoren in meerdere organen; geassocieerd met lymfangioleiomyomatose.","definition":"<p>Tubereuze sclerose is een autosomaal dominante multisysteemziekte (TSC1/TSC2) met hamartomen in hersenen, huid, nieren en longen. In de long kan het lymfangioleiomyomatose veroorzaken.</p>","image_url":"","wiki_title":"Tuberous sclerosis","match":"tubereuze sclerose","option_only":true},"cotton wool spots":{"title":"Cotton wool spots","short":"Witte, wollige vlekjes in de retina door micro-infarcten van de zenuwvezellaag.","definition":"<p><b>Cotton wool spots</b> zijn ophopingen van geblokkeerd axoplasmatisch transport door ischemie van de retinale zenuwvezellaag. Ze komen o.a. voor bij (pre)proliferatieve diabetische retinopathie en hypertensie.</p>","image_url":"","wiki_title":"Cotton wool spots","match":"cotton wool spots","option_only":true},"microaneurysmata":{"title":"Microaneurysmata","short":"Kleine uitstulpingen van retinale capillairen; vroeg kenmerk van non-proliferatieve diabetische retinopathie.","definition":"<p>Microaneurysmata zijn de eerste zichtbare afwijkingen bij diabetische retinopathie: kleine puntvormige verwijdingen van de netvliescapillairen, die kunnen lekken en bloeden.</p>","image_url":"","wiki_title":"Microaneurysm","match":"microaneurysmata","option_only":true},"brughoektumor (schwannoom)":{"title":"Acusticusneurinoom (vestibulair schwannoom)","short":"Een acusticusneurinoom is een goedaardige tumor van de Schwann-cellen van de n. vestibularis, in de inwendige gehoorgang of brughoek.","definition":"<p>Een <strong>vestibulair schwannoom</strong> groeit langzaam vanuit de n. vestibularis (VIII). Klassiek begint het met eenzijdig, geleidelijk perceptief gehoorverlies en oorsuizen; grotere tumoren in de brughoek kunnen de n. facialis, n. trigeminus en het cerebellum en de hersenstam drukken. Dubbelzijdige schwannomen passen bij neurofibromatose type 2. Diagnose met MRI.</p>","image_url":"","wiki_title":"Vestibular schwannoma","match":"brughoektumor (schwannoom)","option_only":true},"vitamine b-12 deficiëntie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b-12 deficiëntie","option_only":true},"multipele systeem atrofie (msa)":{"title":"Multipele systeem atrofie (MSA)","short":"Atypisch parkinsonisme met vroege, ernstige autonome uitval (orthostatische hypotensie, blaasstoornissen) en/of cerebellaire kenmerken.","definition":"<p>MSA is een alfa-synucleïnopathie waarbij parkinsonisme wordt gecombineerd met prominente autonome dysfunctie en/of ataxie. De respons op levodopa is beperkt.</p>","image_url":"","wiki_title":"Multiple system atrophy","match":"multipele systeem atrofie (msa)","option_only":true},"immuunglobulines":{"title":"Immuunglobulines (IVIG)","short":"Intraveneuze immuunglobulines zijn gepoolde antistoffen van donoren, gebruikt als immuunmodulerende therapie, o.a. bij de ziekte van Kawasaki.","definition":"<p><strong>Immuunglobulines (IVIG)</strong> zijn geconcentreerde IgG-antistoffen uit donorplasma. Bij de ziekte van Kawasaki dempen ze de vaatontsteking en verlagen ze het risico op coronaire aneurysmata.</p>","image_url":"","wiki_title":"Immunoglobulin therapy","match":"immuunglobulines","option_only":true},"plasmaferese":{"title":"Plasmaferese","short":"Techniek waarbij plasma van de patiënt wordt gescheiden en vervangen; gebruikt bij o.a. TTP.","definition":"<p>Bij plasmaferese wordt patiëntenplasma verwijderd en vervangen door donorplasma; essentieel bij trombotische trombocytopenische purpura (aanvulling van ADAMTS-13).</p>","image_url":"","wiki_title":"Plasmapheresis","match":"plasmaferese","option_only":true},"fingolimod":{"title":"Fingolimod","short":"Oraal immunomodulerend middel (sfingosine-1-fosfaatreceptormodulator) voor relapsing-remitting MS. Voorkeur boven natalizumab bij JC-virusdragers vanwege lager PML-risico.","definition":"<p><b>Fingolimod</b> houdt lymfocyten vast in de lymfeklieren en vermindert zo MS-exacerbaties. Bij een JC-virus-positieve patiënt is het een veiliger tweedelijnskeuze dan natalizumab, dat progressieve multifocale leuko-encefalopathie (PML) kan geven.</p>","image_url":"","wiki_title":"Fingolimod","match":"fingolimod","option_only":true},"hla-b27+":{"title":"HLA-B27","short":"HLA-B27 is een MHC klasse I-variant die sterk geassocieerd is met spondyloartritiden zoals de ziekte van Bechterew.","definition":"<p>Dragers van <strong>HLA-B27</strong> hebben een sterk verhoogd risico op axiale spondyloartritis, reactieve artritis, uveïtis anterior en artritis bij IBD of psoriasis. Toch krijgt de grote meerderheid van de dragers nooit een van deze ziekten, en een deel van de patiënten is HLA-B27-negatief: de test ondersteunt de diagnose, maar bewijst haar niet.</p>","image_url":"","wiki_title":"HLA-B27","match":"hla-b27+","option_only":true},"vitamine b-12 deficientie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b-12 deficientie","option_only":true},"thiazidediureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazidediureticum","option_only":true},"papiloedeem":{"title":"Papiloedeem","short":"Zwelling van de oogzenuwkop door verhoogde intracraniële druk; zichtbaar bij fundoscopie en teken van maligne hypertensie.","definition":"<p><b>Papiloedeem</b> is zwelling van de papil (oogzenuwkop) door verhoogde hersendruk. Bij zeer hoge bloeddruk (maligne hypertensie) is het een teken van eindorgaanschade.</p>","image_url":"","wiki_title":"Papilledema","match":"papiloedeem","option_only":true},"wortel l4":{"title":"Wortel L4","short":"Een L4-radiculopathie geeft pijn en gevoelsstoornis aan de voorkant van de dij en de binnenkant van het onderbeen, met een verlaagde kniepeesreflex.","definition":"<p>Bij uitval van de <strong>wortel L4</strong> is vooral de m. quadriceps en m. tibialis anterior zwak. Een hernia op niveau L3–L4 of een laterale hernia L4–L5 kan deze wortel aantasten.</p>","image_url":"","wiki_title":"Radiculopathy","match":"wortel l4|l4-radiculopathie","option_only":true},"wortel c7":{"title":"Wortel C7","short":"Een C7-radiculopathie geeft uitstraling naar de middelvinger, zwakte van de triceps en een verlaagde tricepspeesreflex.","definition":"<p>Een cervicale radiculopathie ontstaat door een hernia of artrose van de halswervels. Kenmerken per wortel: <strong>C6</strong> duim, biceps/brachioradialis en bicepspeesreflex; <strong>C7</strong> middelvinger, triceps; <strong>C8</strong> pink en zwakte van de handspieren.</p>","image_url":"","wiki_title":"Radiculopathy","match":"wortel c7|c7-radiculopathie|wortel c6","option_only":true},"n. plantaris":{"title":"N. plantaris medialis en lateralis","short":"De nn. plantares zijn eindtakken van de n. tibialis in de voetzool, voor de voetspieren en het gevoel van de voetzool.","definition":"<p>De n. tibialis loopt achter de mediale malleolus door de tarsale tunnel en splitst zich dan in de <strong>n. plantaris medialis en lateralis</strong>. Beknelling in de tunnel geeft het tarsaletunnelsyndroom, met tintelingen in de voetzool.</p>","image_url":"","wiki_title":"Medial plantar nerve","match":"n. plantaris|nervus plantaris","option_only":true},"4-aminopyridine":{"title":"4-aminopyridine (fampridine)","short":"4-aminopyridine blokkeert kaliumkanalen in gedemyeliniseerde zenuwvezels, waardoor de geleiding verbetert.","definition":"<p><strong>Fampridine</strong> wordt gebruikt om de loopsnelheid bij MS te verbeteren. Een belangrijke bijwerking is een verlaagde drempel voor epileptische aanvallen.</p>","image_url":"","wiki_title":"Fampridine","match":"4-aminopyridine|fampridine","option_only":true},"ependymoom":{"title":"Ependymoom","short":"Een ependymoom is een tumor uitgaande van de ependymcellen die de ventrikels en het centraal kanaal bekleden.","definition":"<p>Bij kinderen zit een <strong>ependymoom</strong> vaak in de vierde ventrikel (met hydrocefalus), bij volwassenen vaker in het ruggenmerg. Behandeling: chirurgie en radiotherapie.</p>","image_url":"","wiki_title":"Ependymoma","match":"ependymoom","option_only":true},"indomethacine":{"title":"Indometacine","short":"Indometacine is een sterk NSAID, o.a. gebruikt bij jicht, bepaalde hoofdpijnsyndromen en vroeger om een open ductus arteriosus bij prematuren te sluiten.","definition":"<p>Bepaalde hoofdpijnsoorten (paroxismale hemicranie, hemicrania continua) reageren per definitie op <strong>indometacine</strong>. Bijwerkingen zijn die van NSAID's: maag-darmklachten, nierfunctiestoornis en vochtretentie.</p>","image_url":"","wiki_title":"Indometacin","match":"indomethacine|indometacine","option_only":true},"syndroom van west":{"title":"Syndroom van West","short":"Het syndroom van West is een epilepsiesyndroom bij zuigelingen met salaamkrampjes, een hypsaritmie op het EEG en een ontwikkelingsachterstand.","definition":"<p>Het <strong>syndroom van West</strong> begint meestal tussen 3 en 12 maanden. Een bekende oorzaak is tubereuze sclerose. Behandeling met ACTH, prednisolon of vigabatrine. Het kan overgaan in het syndroom van Lennox-Gastaut.</p>","image_url":"","wiki_title":"Infantile spasms","match":"syndroom van west|infantiele spasmen","option_only":true},"stenose arteria basilaris":{"title":"Basilaris- en vertebralisstenose","short":"Vernauwingen van de a. vertebralis of a. basilaris verminderen de bloedtoevoer naar hersenstam, cerebellum en occipitaalkwab.","definition":"<p>Klachten van het <strong>vertebrobasilaire</strong> stroomgebied zijn duizeligheid, dubbelzien, dysartrie, ataxie, gezichtsvelduitval en uitval aan beide kanten. Een basilaristrombose is levensbedreigend.</p>","image_url":"","wiki_title":"Vertebrobasilar insufficiency","match":"stenose arteria basilaris|stenose arteria vertebralis links|vertebrobasilaire insufficiëntie","option_only":true},"ziekte van pompe":{"title":"Ziekte van Pompe","short":"De ziekte van Pompe is een erfelijke stapelingsziekte door een tekort aan het lysosomale enzym zure α-glucosidase, met stapeling van glycogeen in spieren.","definition":"<p>De infantiele vorm van de <strong>ziekte van Pompe</strong> geeft hypotonie en cardiomyopathie; bij latere vormen staan spierzwakte en ademhalingsproblemen op de voorgrond. Er is enzymvervangingstherapie.</p>","image_url":"","wiki_title":"Glycogen storage disease type II","match":"ziekte van pompe|glycogeenstapelingsziekte type ii","option_only":true},"galantamine":{"title":"Galantamine","short":"Galantamine is een cholinesteraseremmer die ook de nicotinereceptor moduleert; gebruikt bij de ziekte van Alzheimer.","definition":"<p><strong>Galantamine</strong> hoort met donepezil en rivastigmine bij de cholinesteraseremmers. Bijwerkingen zijn cholinerg: misselijkheid, braken, diarree en bradycardie.</p>","image_url":"","wiki_title":"Galantamine","match":"galantamine","option_only":true},"tacrine":{"title":"Tacrine","short":"Tacrine was de eerste cholinesteraseremmer voor de ziekte van Alzheimer, maar is door leverschade van de markt gehaald.","definition":"<p><strong>Tacrine</strong> moest vaak per dag worden ingenomen en gaf bij veel patiënten verhoogde leverenzymen. Het is vervangen door donepezil, rivastigmine en galantamine.</p>","image_url":"","wiki_title":"Tacrine","match":"tacrine","option_only":true},"mitoxantron":{"title":"Mitoxantron","short":"Mitoxantron is een cytostaticum (topo-isomerase II-remmer), vroeger ook gebruikt bij agressieve MS.","definition":"<p><strong>Mitoxantron</strong> kan cardiotoxiciteit en secundaire leukemie veroorzaken, waardoor de cumulatieve dosis beperkt is.</p>","image_url":"","wiki_title":"Mitoxantrone","match":"mitoxantron","option_only":true},"relapsing remitting ms":{"title":"Beloopsvormen van MS","short":"MS kan verlopen in aanvallen met (gedeeltelijk) herstel (relapsing-remitting), of met geleidelijke achteruitgang vanaf het begin (primair progressief) of na een periode met aanvallen (secundair progressief).","definition":"<p>De meeste patiënten beginnen met <strong>relapsing-remitting MS</strong>; een deel gaat na jaren over in een secundair progressieve vorm. Ziektemodulerende middelen werken vooral goed bij de vorm met aanvallen. Primair progressieve MS begint vaak later en gaat vaak met een progressieve paraparese gepaard.</p>","image_url":"","wiki_title":"Multiple sclerosis","match":"relapsing remitting ms|rrms|primair progressieve ms|secundair progressieve ms","option_only":true},"gliadine":{"title":"Gliadine","short":"Gliadine is een deel van het glutene-eiwit in tarwe; bij coeliakie lokt het een T-celreactie uit tegen de dunne darm.","definition":"<p>Bij <strong>coeliakie</strong> wordt gliadine door het enzym weefseltransglutaminase gedeamideerd en gepresenteerd via HLA-DQ2/DQ8. De diagnose wordt gesteld met anti-tTG-antistoffen en zo nodig een dunnedarmbiopt (vlokatrofie).</p>","image_url":"","wiki_title":"Gliadin","match":"gliadine|gluten","option_only":true},"ganglioside":{"title":"Gangliosiden","short":"Gangliosiden zijn glycosfingolipiden in zenuwmembranen; antistoffen ertegen spelen een rol bij varianten van het Guillain-Barré-syndroom.","definition":"<p>Antistoffen tegen <strong>GQ1b</strong> passen bij het Miller-Fisher-syndroom (oftalmoplegie, ataxie, areflexie), tegen <strong>GM1</strong> bij axonale vormen van Guillain-Barré en multifocale motorische neuropathie. Stapeling van gangliosiden komt voor bij de ziekte van Tay-Sachs.</p>","image_url":"","wiki_title":"Ganglioside","match":"ganglioside|gangliosiden|anti-gm1","option_only":true},"trombose arteria spinalis anterior":{"title":"Arteria spinalis anterior-syndroom","short":"Bij afsluiting van de a. spinalis anterior vallen de voorste twee derde van het ruggenmerg uit: verlamming en pijn- en temperatuurverlies, maar behouden gevoel van tast en positie.","definition":"<p>Het <strong>spinalis anterior-syndroom</strong> ontstaat o.a. na aortachirurgie of door hypotensie. De achterstrengen (fijne tast, positiezin) worden apart verzorgd door de aa. spinales posteriores en blijven gespaard.</p>","image_url":"","wiki_title":"Anterior spinal artery syndrome","match":"trombose arteria spinalis anterior|arteria spinalis anterior syndroom","option_only":true},"interferon-bèta":{"title":"Interferon-bèta","short":"Interferon-bèta is een immuunmodulerend middel dat bij relapsing-remitting MS het aantal aanvallen vermindert.","definition":"<p><strong>Interferon-bèta</strong> wordt subcutaan of intramusculair gespoten. Bijwerkingen zijn griepachtige klachten, reacties op de injectieplaats, depressie en verhoogde leverenzymen.</p>","image_url":"","wiki_title":"Interferon beta","match":"interferon-bèta|interferon beta","option_only":true},"albinisme":{"title":"Albinisme","short":"Albinisme is een erfelijke stoornis in de aanmaak van melanine, met een lichte huid, haar en ogen, verminderd zicht en nystagmus.","definition":"<p>Bij oculocutaan <strong>albinisme</strong> is de aanmaak van melanine door een enzymdefect (vaak tyrosinase) verstoord. De melanocyten zelf zijn er wel. Er is een sterk verhoogd risico op zonverbranding en huidkanker.</p>","image_url":"","wiki_title":"Albinism","match":"albinisme","option_only":true},"congenitaal cataract":{"title":"Congenitaal cataract","short":"Bij een congenitaal cataract is de ooglens bij de geboorte troebel, met een witte pupil en het risico op een lui oog.","definition":"<p>Oorzaken zijn o.a. erfelijkheid, intra-uteriene infecties (rubella, toxoplasmose, CMV), galactosemie en chromosomale afwijkingen. Daarom wordt bij pasgeborenen de rode fundusreflex gecontroleerd. Snel opereren is nodig om amblyopie te voorkomen.</p>","image_url":"","wiki_title":"Congenital cataract","match":"congenitaal cataract|aangeboren staar","option_only":true},"retinoblastoom":{"title":"Retinoblastoom","short":"Een retinoblastoom is een kwaadaardige netvliestumor bij jonge kinderen, vaak door een mutatie in het RB1-gen.","definition":"<p>Het eerste teken is vaak een witte pupilreflex (leukocorie) of scheelzien. Bij een erfelijke vorm (kiembaanmutatie) zijn vaak beide ogen betrokken en is er later een verhoogd risico op andere tumoren (o.a. osteosarcoom). RB1 is het klassieke voorbeeld van Knudsons ‘two-hit’-hypothese.</p>","image_url":"","wiki_title":"Retinoblastoma","match":"retinoblastoom|rb1","option_only":true},"lasercoagulatie":{"title":"Lasercoagulatie (oog)","short":"Bij lasercoagulatie wordt met een laser netvliesweefsel dichtgeschroeid, bijv. rond een scheur of bij nieuwe vaatvorming.","definition":"<p><strong>Panretinale fotocoagulatie</strong> remt de vaatnieuwvorming bij proliferatieve diabetische retinopathie en na veneuze afsluitingen. Rond een netvliesscheur voorkomt laser een netvliesloslating.</p>","image_url":"","wiki_title":"Photocoagulation","match":"lasercoagulatie|panretinale fotocoagulatie|laserbehandeling","option_only":true},"bradykinesie":{"title":"Bradykinesie","short":"Bradykinesie is traagheid van bewegingen met een afnemende amplitude bij herhaling, het kernsymptoom van parkinsonisme.","definition":"<p>Voor de diagnose <strong>parkinsonisme</strong> moet er bradykinesie zijn, met rigiditeit en/of rusttremor. Voorbeelden van bradykinesie zijn een maskergelaat, micrografie, kleinere passen en minder meebewegen van de armen.</p>","image_url":"","wiki_title":"Bradykinesia","match":"bradykinesie|hypokinesie|akinesie","option_only":true},"houdingsinstabiliteit":{"title":"Houdingsinstabiliteit","short":"Houdingsinstabiliteit is het niet goed kunnen corrigeren van een verstoring van het evenwicht, met valneiging.","definition":"<p>Bij de <strong>trektest</strong> trekt de onderzoeker de patiënt aan de schouders naar achteren. Bij de ziekte van Parkinson ontstaat houdingsinstabiliteit meestal pas later; vroege instabiliteit en vallen passen eerder bij atypisch parkinsonisme (PSP, MSA).</p>","image_url":"","wiki_title":"Postural instability","match":"houdingsinstabiliteit|posturale instabiliteit|retropulsie","option_only":true},"get up and go-test":{"title":"Timed Up and Go-test","short":"Bij de Timed Up and Go-test staat iemand op uit een stoel, loopt 3 meter, draait om en gaat weer zitten; de tijd voorspelt het valrisico.","definition":"<p>Een tijd van meer dan 12–14 seconden wijst bij ouderen op een verhoogd <strong>valrisico</strong>. De test wordt gebruikt in de geriatrie en de huisartsenpraktijk.</p>","image_url":"","wiki_title":"Timed Up and Go test","match":"get up and go-test|timed up and go|tug","option_only":true},"test van romberg":{"title":"Test van Romberg","short":"Bij de test van Romberg staat de patiënt met de voeten bij elkaar; als hij met de ogen dicht gaat vallen, wijst dat op een stoornis van de positiezin.","definition":"<p>Een positieve <strong>Romberg</strong> past bij een sensibele ataxie (achterstrengen, polyneuropathie, vitamine B12-tekort). Bij een cerebellaire ataxie is het evenwicht ook met de ogen open slecht. Bij de <strong>test van Unterberger</strong> stapt de patiënt met gesloten ogen op de plaats; draaien naar één kant wijst op een vestibulaire uitval aan die kant.</p>","image_url":"","wiki_title":"Romberg's test","match":"test van romberg|romberg|test van unterberger","option_only":true},"ergotamine":{"title":"Ergotamine","short":"Ergotamine is een oud migrainemiddel dat bloedvaten vernauwt via serotonine- en andere receptoren.","definition":"<p><strong>Ergotamine</strong> is grotendeels vervangen door triptanen. Bij overmatig gebruik kunnen ernstige vaatvernauwing (ergotisme) en medicatieafhankelijke hoofdpijn ontstaan. Het is gecontra-indiceerd bij zwangerschap en hart- en vaatziekten.</p>","image_url":"","wiki_title":"Ergotamine","match":"ergotamine|ergotalkaloïden","option_only":true},"rotatoire nystagmus":{"title":"Nystagmus","short":"Nystagmus is een ritmische beweging van de ogen met een langzame en een snelle fase; de richting wordt benoemd naar de snelle fase.","definition":"<p>Een perifere (vestibulaire) <strong>nystagmus</strong> is horizontaal-rotatoir, slaat één kant op en wordt minder bij fixatie. Een zuiver verticale of richtingveranderende nystagmus wijst op een centrale oorzaak. Bij BPPV van het achterste kanaal is er een rotatoire nystagmus in de Dix-Hallpike-positie.</p>","image_url":"","wiki_title":"Nystagmus","match":"rotatoire nystagmus|horizontale nystagmus|verticale nystagmus","option_only":true},"lichtstijve pupil":{"title":"Lichtstijve pupil","short":"Een lichtstijve pupil reageert niet meer op licht; dat kan liggen aan de aanvoer (n. opticus) of de afvoer (n. oculomotorius) van de reflex.","definition":"<p>Bij een afwijking in de <strong>afvoer</strong> (bijv. een oculomotoriusparese) is de pupil wijd en lichtstijf. Bij een afwijking van de <strong>aanvoer</strong> aan één kant zijn de pupillen even groot, maar is er een relatief afferent pupildefect bij de swinging-flashlighttest.</p>","image_url":"","wiki_title":"Pupillary light reflex","match":"lichtstijve pupil|pupilreflex|relatief afferent pupildefect","option_only":true},"retinale vasculaire occlusie":{"title":"Retinale vaatafsluiting","short":"Bij een afsluiting van een netvliesader of -slagader ontstaat plotseling pijnloos verlies van zicht in (een deel van) het gezichtsveld.","definition":"<p>Bij een <strong>arterieafsluiting</strong> is het netvlies bleek met een kersrode vlek; bij arteriitis temporalis moet direct prednison worden gestart. Bij een <strong>veneuze afsluiting</strong> zijn er veel bloedingen. Risicofactoren zijn hypertensie, diabetes en atherosclerose.</p>","image_url":"","wiki_title":"Retinal vein occlusion","match":"retinale vasculaire occlusie|retinale arterieafsluiting|retinale veneuze occlusie|centrale arterie occlusie","option_only":true},"proliferatieve diabetische retinopathie":{"title":"Diabetische retinopathie","short":"Bij proliferatieve diabetische retinopathie groeien door zuurstofgebrek nieuwe, kwetsbare bloedvaten in het netvlies.","definition":"<p>De niet-proliferatieve vorm geeft microaneurysmata, puntbloedinkjes, harde exsudaten en cotton-wool spots. Bij de <strong>proliferatieve vorm</strong> dreigen glasvochtbloedingen, tractie-netvliesloslating en neovasculair glaucoom. Behandeling met laser en anti-VEGF. Jaarlijkse screening bij diabetes is nodig.</p>","image_url":"","wiki_title":"Diabetic retinopathy","match":"proliferatieve diabetische retinopathie|diabetische retinopathie","option_only":true},"een neerwaartse verticale blikparese":{"title":"Verticale blikparese","short":"Bij een verticale blikparese kunnen beide ogen niet goed omhoog of omlaag kijken, door een afwijking in het mesencephalon.","definition":"<p>Een beperking van het <strong>naar beneden kijken</strong> is vroeg kenmerkend voor progressieve supranucleaire parese (PSP). Een beperking van het omhoog kijken past bij het syndroom van Parinaud (bijv. een pinealistumor).</p>","image_url":"","wiki_title":"Progressive supranuclear palsy","match":"een neerwaartse verticale blikparese|verticale blikparese","option_only":true},"medicatie-afhankelijke hoofdpijn":{"title":"Medicatieovergebruikshoofdpijn","short":"Medicatieovergebruikshoofdpijn is chronische hoofdpijn door te vaak gebruiken van pijnstillers of migrainemiddelen.","definition":"<p>Er is sprake van overgebruik bij gewone pijnstillers op 15 of meer dagen per maand, of triptanen, opiaten of combinatiepreparaten op 10 of meer dagen per maand. Behandeling: stoppen met de middelen (onttrekking), daarna eventueel profylaxe.</p>","image_url":"","wiki_title":"Medication overuse headache","match":"medicatie-afhankelijke hoofdpijn|medicatieovergebruikshoofdpijn","option_only":true},"ct-angiografie hersenen":{"title":"CT-angiografie","short":"Bij een CT-angiografie worden bloedvaten met contrast in beeld gebracht, bijv. om een afsluiting of aneurysma op te sporen.","definition":"<p>Bij een acuut herseninfarct toont <strong>CTA</strong> of er een groot vat is afgesloten dat in aanmerking komt voor trombectomie. Bij een subarachnoïdale bloeding wordt met CTA naar een aneurysma gezocht.</p>","image_url":"","wiki_title":"CT angiography","match":"ct-angiografie hersenen|cta|ct-angiografie","option_only":true},"kanteltafeltest (tilt table test)":{"title":"Kanteltafeltest","short":"Bij een kanteltafeltest wordt iemand liggend op een tafel rechtop gekanteld, terwijl bloeddruk en hartslag worden gemeten, om de oorzaak van wegrakingen te onderzoeken.","definition":"<p>De <strong>kanteltafeltest</strong> kan vasovagale syncope, orthostatische hypotensie en POTS aantonen.</p>","image_url":"","wiki_title":"Tilt table test","match":"kanteltafeltest (tilt table test)|kanteltafeltest|tilt table test","option_only":true},"stabilometrie":{"title":"Posturografie (stabilometrie)","short":"Bij stabilometrie wordt met een krachtplaat gemeten hoeveel iemand in stand zwaait, om het evenwicht objectief te beoordelen.","definition":"<p>Met <strong>posturografie</strong> kan de bijdrage van zicht, gevoel en evenwichtsorgaan aan de balans worden onderzocht.</p>","image_url":"","wiki_title":"","match":"stabilometrie|posturografie","option_only":true},"virale conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies met een rood oog, waterig, slijmerig of etterig vocht, en een normale visus.","definition":"<p>Een <strong>virale conjunctivitis</strong> (vaak adenovirus) is zeer besmettelijk, met waterig vocht en een gezwollen klier voor het oor. Een bacteriële vorm geeft meer pus en dichtgeplakte ogen; een allergische vorm jeuk. Pijn, lichtschuwheid en verminderde visus wijzen op een ernstigere oorzaak.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"virale conjunctivitis|bacteriële conjunctivitis|allergische conjunctivitis","option_only":true},"natriumkanaalblokkers":{"title":"Natriumkanaalblokkers","short":"Natriumkanaalblokkers remmen spanningsafhankelijke natriumkanalen; ze worden gebruikt als anti-epileptica, lokale anesthetica en antiaritmica.","definition":"<p>Voorbeelden zijn <strong>carbamazepine, fenytoïne, lamotrigine</strong> (epilepsie), lidocaïne (lokaal anestheticum en antiaritmicum klasse I) en flecaïnide. Bij absences en myoclonieën kunnen sommige natriumkanaalblokkers aanvallen juist verergeren.</p>","image_url":"","wiki_title":"Sodium channel blocker","match":"natriumkanaalblokkers|natriumkanaalblokker","option_only":true},"barbituraten":{"title":"Barbituraten","short":"Barbituraten versterken de werking van GABA op de GABA-A-receptor en werken sederend en anti-epileptisch.","definition":"<p><strong>Fenobarbital</strong> wordt nog gebruikt bij status epilepticus en neonatale aanvallen. Barbituraten hebben een smalle therapeutische breedte, geven ademhalingsdepressie en sterke enzyminductie, en zijn als slaapmiddel vervangen door benzodiazepinen.</p>","image_url":"","wiki_title":"Barbiturate","match":"barbituraten|fenobarbital","option_only":true},"essentiële tremor":{"title":"Essentiële tremor","short":"Een essentiële tremor is een vaak erfelijke houdings- en bewegingstremor van handen en soms hoofd of stem, die verbetert met alcohol.","definition":"<p>Een <strong>essentiële tremor</strong> is symmetrisch en treedt op bij handelingen (bekertje vasthouden, schrijven). Een parkinsontremor is juist een rusttremor. Een <strong>cerebellaire tremor</strong> is een intentietremor die toeneemt naarmate het doel dichterbij komt; een <strong>dystone tremor</strong> is onregelmatig en gaat samen met dystonie. Behandeling van essentiële tremor: propranolol of primidon.</p>","image_url":"","wiki_title":"Essential tremor","match":"essentiële tremor|cerebellaire tremor|dystone tremor","option_only":true},"bicepspeesreflex":{"title":"Peesreflexen van de arm","short":"De bicepspeesreflex test C5–C6, de brachioradialisreflex C6 en de tricepspeesreflex C7.","definition":"<p>Verlaagde <strong>peesreflexen</strong> wijzen op een stoornis in de perifere zenuw of zenuwwortel; verhoogde reflexen op een centrale (eerste motorneuron) stoornis.</p>","image_url":"","wiki_title":"Biceps reflex","match":"bicepspeesreflex|tricepspeesreflex|brachioradialisreflex","option_only":true},"exoforie":{"title":"Heteroforie (exoforie, esoforie)","short":"Een heteroforie is een latente afwijking van de oogstand, die alleen zichtbaar wordt als de ogen niet samen kijken (afdektest).","definition":"<p>Bij <strong>exoforie</strong> wijkt het afgedekte oog naar buiten, bij esoforie naar binnen. Een heteroforie is meestal onschuldig, maar kan bij vermoeidheid klachten geven. Een manifeste afwijking heet een heterotropie (scheelzien).</p>","image_url":"","wiki_title":"Heterophoria","match":"exoforie|esoforie|heteroforie","option_only":true},"tumarkin aanvallen":{"title":"Tumarkin-aanvallen","short":"Tumarkin-aanvallen zijn plotselinge valpartijen zonder bewustzijnsverlies bij de ziekte van Ménière, door een plotselinge prikkeling van het otolietorgaan.","definition":"<p>Patiënten met <strong>Tumarkin-aanvallen</strong> hebben het gevoel geduwd te worden en vallen zonder waarschuwing. Ze komen vooral in een later stadium van de ziekte van Ménière voor.</p>","image_url":"","wiki_title":"","match":"tumarkin aanvallen|tumarkin","option_only":true},"dunnevezelneuropathie":{"title":"Dunnevezelneuropathie","short":"Bij een dunnevezelneuropathie zijn de dunne zenuwvezels voor pijn, temperatuur en autonome functies aangedaan, met brandende pijn in de voeten.","definition":"<p>Een EMG is bij een <strong>dunnevezelneuropathie</strong> vaak normaal, omdat alleen dikke vezels worden gemeten; de diagnose wordt gesteld met een huidbiopt (vezeldichtheid) of temperatuurdrempelonderzoek. Oorzaken zijn o.a. diabetes, sarcoïdose en de ziekte van Fabry.</p>","image_url":"","wiki_title":"Small fiber peripheral neuropathy","match":"dunnevezelneuropathie|small fiber neuropathy","option_only":true},"lumbaalpunctie":{"title":"Lumbaalpunctie","short":"Bij een lumbaalpunctie wordt met een naald tussen de lendenwervels liquor afgenomen, voor onderzoek of drukmeting.","definition":"<p>Een <strong>lumbaalpunctie</strong> wordt gedaan bij verdenking op meningitis, een subarachnoïdale bloeding met normale CT, Guillain-Barré, MS en idiopathische intracraniële hypertensie. Bij tekenen van verhoogde druk of een ruimte-innemend proces moet eerst een CT worden gemaakt. Een bekende complicatie is postpunctionele hoofdpijn.</p>","image_url":"","wiki_title":"Lumbar puncture","match":"lumbaalpunctie|liquoronderzoek|ruggenprik","option_only":true},"liquorkweek":{"title":"Liquorkweek","short":"Bij een liquorkweek wordt liquor op voedingsbodems gezet om bacteriën of schimmels aan te tonen en hun gevoeligheid voor antibiotica te bepalen.","definition":"<p>Bij bacteriële meningitis is de liquor troebel, met veel granulocyten, een hoog eiwit en een laag glucose. De <strong>kweek</strong> kan negatief zijn als al antibiotica zijn gegeven; een Gramkleuring en PCR geven sneller een uitslag.</p>","image_url":"","wiki_title":"","match":"liquorkweek","option_only":true},"bloedkweek":{"title":"Bloedkweek","short":"Een bloedkweek onderzoekt of er bacteriën of schimmels in het bloed zitten (bacteriëmie).","definition":"<p>Bij verdenking op sepsis of endocarditis worden minimaal twee sets <strong>bloedkweken</strong> afgenomen vóór het starten van antibiotica. Een kweek met huidbacteriën (bijv. coagulasenegatieve stafylokokken) in één fles is vaak een verontreiniging.</p>","image_url":"","wiki_title":"Blood culture","match":"bloedkweek|bloedkweken","option_only":true},"mimetherapie":{"title":"Mimetherapie","short":"Mimetherapie is oefentherapie voor de gezichtsspieren bij een aangezichtsverlamming, om de functie en symmetrie te verbeteren.","definition":"<p><strong>Mimetherapie</strong> wordt gegeven door een gespecialiseerde fysiotherapeut, bijv. bij een onvolledig herstel na een perifere aangezichtsverlamming, en helpt ook tegen synkinesieën.</p>","image_url":"","wiki_title":"","match":"mimetherapie","option_only":true},"operatie volgens jannetta":{"title":"Microvasculaire decompressie (operatie van Jannetta)","short":"Bij de operatie van Jannetta wordt een bloedvat dat tegen een hersenzenuw drukt van de zenuw losgemaakt, bijv. bij trigeminusneuralgie.","definition":"<p><strong>Microvasculaire decompressie</strong> is een behandeling voor trigeminusneuralgie of hemifaciale spasmen die niet op medicatie (carbamazepine) reageren. Er wordt een stukje teflon tussen vat en zenuw gelegd.</p>","image_url":"","wiki_title":"Microvascular decompression","match":"operatie volgens jannetta|microvasculaire decompressie|jannetta","option_only":true},"dyschromatopsie":{"title":"Dyschromatopsie (kleurzienstoornis)","short":"Dyschromatopsie is een stoornis in het zien van kleuren, aangeboren of verworven.","definition":"<p>Aangeboren rood-groen<strong>kleurenblindheid</strong> is X-gebonden en komt bij ongeveer 8% van de mannen voor. Een verworven kleurzienstoornis, vooral voor rood, is een vroeg teken van een aandoening van de n. opticus (bijv. neuritis optica of ethambutoltoxiciteit). Onderzoek met Ishihara-kaarten.</p>","image_url":"","wiki_title":"Color blindness","match":"dyschromatopsie|kleurzienstoornis|kleurenblindheid","option_only":true},"apoplexie van de hypofyse":{"title":"Hypofyse-apoplexie","short":"Bij een hypofyse-apoplexie ontstaat een plotselinge bloeding of infarct in (meestal) een hypofyseadenoom.","definition":"<p>Er is plotseling hevige hoofdpijn, dubbelzien en gezichtsvelduitval, en vaak acute bijnierinsufficiëntie door uitval van ACTH. Behandeling: direct hydrocortison, zo nodig chirurgische decompressie. Na een bevalling met groot bloedverlies kan een vergelijkbaar infarct optreden (syndroom van Sheehan).</p>","image_url":"","wiki_title":"Pituitary apoplexy","match":"apoplexie van de hypofyse|hypofyse-apoplexie|hypofyseapoplexie","option_only":true},"chemosis van de conjunctiva":{"title":"Chemosis","short":"Chemosis is zwelling van het bindvlies door oedeem, waardoor het als een glazig blaasje over het oogwit ligt.","definition":"<p><strong>Chemosis</strong> komt voor bij allergische reacties, ernstige conjunctivitis, orbitale cellulitis, sinus cavernosustrombose en de oogziekte van Graves.</p>","image_url":"","wiki_title":"Chemosis","match":"chemosis van de conjunctiva|chemosis","option_only":true},"harde exsudaten":{"title":"Harde exsudaten","short":"Harde exsudaten zijn scherp begrensde gele vlekjes in het netvlies door lekkage van eiwit en vet uit beschadigde vaten.","definition":"<p><strong>Harde exsudaten</strong> en puntbloedinkjes passen bij diabetische en hypertensieve retinopathie. Liggen ze in de macula, dan kan de visus afnemen (maculaoedeem).</p>","image_url":"","wiki_title":"Hard exudate","match":"harde exsudaten|puntbloedinkjes|retinale bloedingen","option_only":true},"x-linked recessief":{"title":"Overervingspatronen","short":"Een X-gebonden recessieve ziekte treft vooral mannen en wordt via draagster-moeders doorgegeven; een mitochondriale ziekte wordt alleen via de moeder doorgegeven.","definition":"<p>Bij <strong>X-gebonden recessief</strong> (bijv. hemofilie, Duchenne) is er geen overdracht van vader op zoon. Bij <strong>mitochondriale overerving</strong> geeft de moeder de ziekte aan al haar kinderen, met wisselende ernst door heteroplasmie.</p>","image_url":"","wiki_title":"Mendelian inheritance","match":"x-linked recessief|x-gebonden recessief|mitochondriale overerving|autosomaal dominant|autosomaal recessief","option_only":true},"parotitis":{"title":"Parotitis","short":"Parotitis is een ontsteking van de oorspeekselklier, viraal (bof) of bacterieel.","definition":"<p><strong>Bof</strong> (mumps) geeft een pijnlijke zwelling van de parotis aan een of beide kanten; complicaties zijn orchitis, meningitis en pancreatitis. Een bacteriële parotitis (vaak <em>S. aureus</em>) komt vooral voor bij uitgedroogde ouderen, met pus uit de afvoergang.</p>","image_url":"","wiki_title":"Parotitis","match":"parotitis|bof","option_only":true},"propanolol":{"title":"Propranolol","short":"Propranolol is een niet-selectieve bètablokker, o.a. gebruikt bij portale hypertensie, migraineprofylaxe, essentiële tremor en de lichamelijke kant van angst.","definition":"<p>Door blokkade van β1 en β2 verlaagt <strong>propranolol</strong> de hartminuutvolume en vernauwt het de splanchnische vaten, wat de poortaderdruk verlaagt. Het kan bronchospasmen geven bij astma en de symptomen van een hypoglykemie maskeren.</p>","image_url":"","wiki_title":"Propranolol","match":"propanolol|propranolol","option_only":true},"downslant":{"title":"Dysmorfe kenmerken van het gezicht","short":"Dysmorfe kenmerken zijn afwijkingen in vorm of maat, zoals de stand van de oogspleten (up- of downslant) en de afstand tussen de ogen (hypo- of hypertelorisme).","definition":"<p>Een <strong>upslant</strong> (oogspleten schuin omhoog) en epicanthus passen bij het syndroom van Down; een downslant komt bij andere syndromen voor. Een enkel dysmorf kenmerk komt ook bij gezonde mensen voor; een combinatie kan op een syndroom wijzen.</p>","image_url":"","wiki_title":"Dysmorphic feature","match":"downslant|upslant|hypotelorisme|hypertelorisme|epicanthus","option_only":true},"floaters":{"title":"Mouches volantes","short":"Mouches volantes zijn zwevende vlekjes of draadjes in het gezichtsveld, door troebelingen in het glasvocht.","definition":"<p>Mouches volantes zijn meestal onschuldig. Een plotselinge toename, vooral met lichtflitsen of een schaduw, kan wijzen op een glasvochtloslating met netvliesscheur en vraagt om onderzoek.</p>","image_url":"","wiki_title":"Floater","match":"floaters","option_only":true},"primair progressieve ms":{"title":"Beloopsvormen van MS","short":"MS kan verlopen in aanvallen met (gedeeltelijk) herstel (relapsing-remitting), of met geleidelijke achteruitgang vanaf het begin (primair progressief) of na een periode met aanvallen (secundair progressief).","definition":"<p>De meeste patiënten beginnen met <strong>relapsing-remitting MS</strong>; een deel gaat na jaren over in een secundair progressieve vorm. Ziektemodulerende middelen werken vooral goed bij de vorm met aanvallen. Primair progressieve MS begint vaak later en gaat vaak met een progressieve paraparese gepaard.</p>","image_url":"","wiki_title":"Multiple sclerosis","match":"primair progressieve ms","option_only":true},"secundair progressieve ms":{"title":"Beloopsvormen van MS","short":"MS kan verlopen in aanvallen met (gedeeltelijk) herstel (relapsing-remitting), of met geleidelijke achteruitgang vanaf het begin (primair progressief) of na een periode met aanvallen (secundair progressief).","definition":"<p>De meeste patiënten beginnen met <strong>relapsing-remitting MS</strong>; een deel gaat na jaren over in een secundair progressieve vorm. Ziektemodulerende middelen werken vooral goed bij de vorm met aanvallen. Primair progressieve MS begint vaak later en gaat vaak met een progressieve paraparese gepaard.</p>","image_url":"","wiki_title":"Multiple sclerosis","match":"secundair progressieve ms","option_only":true},"wortel c8":{"title":"Wortel C7","short":"Een C7-radiculopathie geeft uitstraling naar de middelvinger, zwakte van de triceps en een verlaagde tricepspeesreflex.","definition":"<p>Een cervicale radiculopathie ontstaat door een hernia of artrose van de halswervels. Kenmerken per wortel: <strong>C6</strong> duim, biceps/brachioradialis en bicepspeesreflex; <strong>C7</strong> middelvinger, triceps; <strong>C8</strong> pink en zwakte van de handspieren.</p>","image_url":"","wiki_title":"Radiculopathy","match":"wortel c8","option_only":true},"tricepspeesreflex":{"title":"Peesreflexen van de arm","short":"De bicepspeesreflex test C5–C6, de brachioradialisreflex C6 en de tricepspeesreflex C7.","definition":"<p>Verlaagde <strong>peesreflexen</strong> wijzen op een stoornis in de perifere zenuw of zenuwwortel; verhoogde reflexen op een centrale (eerste motorneuron) stoornis.</p>","image_url":"","wiki_title":"Biceps reflex","match":"tricepspeesreflex","option_only":true},"test van unterberger":{"title":"Test van Romberg","short":"Bij de test van Romberg staat de patiënt met de voeten bij elkaar; als hij met de ogen dicht gaat vallen, wijst dat op een stoornis van de positiezin.","definition":"<p>Een positieve <strong>Romberg</strong> past bij een sensibele ataxie (achterstrengen, polyneuropathie, vitamine B12-tekort). Bij een cerebellaire ataxie is het evenwicht ook met de ogen open slecht. Bij de <strong>test van Unterberger</strong> stapt de patiënt met gesloten ogen op de plaats; draaien naar één kant wijst op een vestibulaire uitval aan die kant.</p>","image_url":"","wiki_title":"Romberg's test","match":"test van unterberger","option_only":true},"dystone tremor":{"title":"Essentiële tremor","short":"Een essentiële tremor is een vaak erfelijke houdings- en bewegingstremor van handen en soms hoofd of stem, die verbetert met alcohol.","definition":"<p>Een <strong>essentiële tremor</strong> is symmetrisch en treedt op bij handelingen (bekertje vasthouden, schrijven). Een parkinsontremor is juist een rusttremor. Een <strong>cerebellaire tremor</strong> is een intentietremor die toeneemt naarmate het doel dichterbij komt; een <strong>dystone tremor</strong> is onregelmatig en gaat samen met dystonie. Behandeling van essentiële tremor: propranolol of primidon.</p>","image_url":"","wiki_title":"Essential tremor","match":"dystone tremor","option_only":true},"cerebellaire tremor":{"title":"Essentiële tremor","short":"Een essentiële tremor is een vaak erfelijke houdings- en bewegingstremor van handen en soms hoofd of stem, die verbetert met alcohol.","definition":"<p>Een <strong>essentiële tremor</strong> is symmetrisch en treedt op bij handelingen (bekertje vasthouden, schrijven). Een parkinsontremor is juist een rusttremor. Een <strong>cerebellaire tremor</strong> is een intentietremor die toeneemt naarmate het doel dichterbij komt; een <strong>dystone tremor</strong> is onregelmatig en gaat samen met dystonie. Behandeling van essentiële tremor: propranolol of primidon.</p>","image_url":"","wiki_title":"Essential tremor","match":"cerebellaire tremor","option_only":true},"analgetica afhankelijke hoofdpijn":{"title":"Medicatieovergebruikshoofdpijn","short":"Medicatieovergebruikshoofdpijn is chronische hoofdpijn door te vaak gebruiken van pijnstillers of migrainemiddelen.","definition":"<p>Er is sprake van overgebruik bij gewone pijnstillers op 15 of meer dagen per maand, of triptanen, opiaten of combinatiepreparaten op 10 of meer dagen per maand. Behandeling: stoppen met de middelen (onttrekking), daarna eventueel profylaxe.</p>","image_url":"","wiki_title":"Medication overuse headache","match":"analgetica afhankelijke hoofdpijn","option_only":true},"bloedonderzoek: vitamine b12":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"bloedonderzoek: vitamine b12","option_only":true},"de ziekte van parkinson":{"title":"Ziekte van Parkinson","short":"De ziekte van Parkinson is een neurodegeneratieve ziekte door verlies van dopaminerge neuronen in de substantia nigra, met rusttremor, bradykinesie en rigiditeit.","definition":"<p>Bij de <strong>ziekte van Parkinson</strong> gaan dopaminerge neuronen in de substantia nigra pars compacta verloren, met Lewy-lichaampjes (alfa-synucleïne). Kernsymptomen zijn bradykinesie, rigiditeit, rusttremor en later houdingsinstabiliteit; vaak ook niet-motorische klachten zoals reukverlies, obstipatie, depressie en slaapstoornissen. Behandeling met levodopa en dopamine-agonisten.</p>","image_url":"","wiki_title":"Parkinson's disease","match":"de ziekte van parkinson","option_only":true},"bloedkweken":{"title":"Bloedkweek","short":"Een bloedkweek onderzoekt of er bacteriën of schimmels in het bloed zitten (bacteriëmie).","definition":"<p>Bij verdenking op sepsis of endocarditis worden minimaal twee sets <strong>bloedkweken</strong> afgenomen vóór het starten van antibiotica. Een kweek met huidbacteriën (bijv. coagulasenegatieve stafylokokken) in één fles is vaak een verontreiniging.</p>","image_url":"","wiki_title":"Blood culture","match":"bloedkweken","option_only":true},"stafylokok":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"stafylokok","option_only":true},"streptokok":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"streptokok","option_only":true},"primair openkamerhoekglaucoom":{"title":"Primair openkamerhoekglaucoom","short":"Bij primair openkamerhoekglaucoom wordt de oogzenuw langzaam beschadigd, meestal bij een verhoogde oogdruk, met sluipend verlies van het gezichtsveld.","definition":"<p>Het <strong>openkamerhoekglaucoom</strong> geeft lang geen klachten; het centrale zien blijft tot laat behouden. Risicofactoren zijn leeftijd, familie, myopie en een hoge oogdruk. Bij oogspiegelen is een vergrote excavatie van de papil te zien. Behandeling met druppels (prostaglandineanaloga, bètablokkers), laser of een operatie.</p>","image_url":"","wiki_title":"Primary open-angle glaucoma","match":"primair openkamerhoekglaucoom|primair open kamerhoek glaucoom|poag","option_only":true},"rolandische epilepsie":{"title":"Rolandische epilepsie (benigne epilepsie met centrotemporale pieken)","short":"Rolandische epilepsie is een goedaardige kinderepilepsie met aanvallen tijdens de slaap, waarbij één kant van gezicht en mond trekt en het kind niet kan praten.","definition":"<p>De aanvallen beginnen tussen 3 en 13 jaar en verdwijnen meestal in de puberteit. Het EEG toont centrotemporale pieken, vooral tijdens de slaap. Behandeling is vaak niet nodig.</p>","image_url":"","wiki_title":"Benign Rolandic epilepsy","match":"rolandische epilepsie|benigne rolandische epilepsie|selflimited epilepsy with centrotemporal spikes","option_only":true},"lennox-gastaut syndroom":{"title":"Syndroom van Lennox-Gastaut","short":"Lennox-Gastaut is een ernstig epilepsiesyndroom bij kinderen met meerdere aanvalstypen (vooral tonische aanvallen en valaanvallen) en een verstandelijke beperking.","definition":"<p>Het EEG toont trage piek-golfcomplexen. Het syndroom kan ontstaan na het syndroom van West. De aanvallen zijn vaak moeilijk te behandelen; middelen zijn o.a. valproaat, lamotrigine, rufinamide en clobazam, soms een ketogeen dieet of nervus vagusstimulatie.</p>","image_url":"","wiki_title":"Lennox–Gastaut syndrome","match":"lennox-gastaut syndroom|syndroom van lennox-gastaut|syndroom van lennox-gastaux","option_only":true},"myasthenia gravis":{"title":"Myasthenia gravis","short":"Myasthenia gravis is een auto-immuunziekte waarbij antistoffen de acetylcholinereceptoren van de motorische eindplaat blokkeren, met een spierzwakte die toeneemt bij inspanning.","definition":"<p>Vaak begint <strong>myasthenia gravis</strong> met ptosis en dubbelzien; later kunnen slikken, praten en ademhalen zwak worden (myasthene crisis). Naast anti-AChR komen anti-MuSK-antistoffen voor. Er is een samenhang met een thymoom. Behandeling: pyridostigmine, immunosuppressie, thymectomie.</p>","image_url":"","wiki_title":"Myasthenia gravis","match":"myasthenia gravis|antistoffen tegen acetylcholinereceptor|anti-achr","option_only":true},"antistoffen tegen aquaporine-4":{"title":"Neuromyelitis optica","short":"Neuromyelitis optica is een auto-immuunziekte met ernstige ontsteking van oogzenuwen en ruggenmerg, door antistoffen tegen aquaporine-4.","definition":"<p>Bij <strong>NMO</strong> ontstaan ernstige opticus-neuritiden en een uitgebreide myelitis over drie of meer segmenten, soms een area postrema-syndroom (onbedwingbaar braken en hikken). Het onderscheid met MS is belangrijk, omdat sommige MS-middelen NMO verergeren.</p>","image_url":"","wiki_title":"Neuromyelitis optica","match":"antistoffen tegen aquaporine-4","option_only":true},"neuromyelitis optica spectrum disease":{"title":"Neuromyelitis optica","short":"Neuromyelitis optica is een auto-immuunziekte met ernstige ontsteking van oogzenuwen en ruggenmerg, door antistoffen tegen aquaporine-4.","definition":"<p>Bij <strong>NMO</strong> ontstaan ernstige opticus-neuritiden en een uitgebreide myelitis over drie of meer segmenten, soms een area postrema-syndroom (onbedwingbaar braken en hikken). Het onderscheid met MS is belangrijk, omdat sommige MS-middelen NMO verergeren.</p>","image_url":"","wiki_title":"Neuromyelitis optica","match":"neuromyelitis optica spectrum disease","option_only":true},"primair open kamerhoek glaucoom":{"title":"Primair openkamerhoekglaucoom","short":"Bij primair openkamerhoekglaucoom wordt de oogzenuw langzaam beschadigd, meestal bij een verhoogde oogdruk, met sluipend verlies van het gezichtsveld.","definition":"<p>Het <strong>openkamerhoekglaucoom</strong> geeft lang geen klachten; het centrale zien blijft tot laat behouden. Risicofactoren zijn leeftijd, familie, myopie en een hoge oogdruk. Bij oogspiegelen is een vergrote excavatie van de papil te zien. Behandeling met druppels (prostaglandineanaloga, bètablokkers), laser of een operatie.</p>","image_url":"","wiki_title":"Primary open-angle glaucoma","match":"primair open kamerhoek glaucoom","option_only":true},"benigne rolandische epilepsie":{"title":"Rolandische epilepsie (benigne epilepsie met centrotemporale pieken)","short":"Rolandische epilepsie is een goedaardige kinderepilepsie met aanvallen tijdens de slaap, waarbij één kant van gezicht en mond trekt en het kind niet kan praten.","definition":"<p>De aanvallen beginnen tussen 3 en 13 jaar en verdwijnen meestal in de puberteit. Het EEG toont centrotemporale pieken, vooral tijdens de slaap. Behandeling is vaak niet nodig.</p>","image_url":"","wiki_title":"Benign Rolandic epilepsy","match":"benigne rolandische epilepsie","option_only":true},"syndroom van lennox-gastaux":{"title":"Syndroom van Lennox-Gastaut","short":"Lennox-Gastaut is een ernstig epilepsiesyndroom bij kinderen met meerdere aanvalstypen (vooral tonische aanvallen en valaanvallen) en een verstandelijke beperking.","definition":"<p>Het EEG toont trage piek-golfcomplexen. Het syndroom kan ontstaan na het syndroom van West. De aanvallen zijn vaak moeilijk te behandelen; middelen zijn o.a. valproaat, lamotrigine, rufinamide en clobazam, soms een ketogeen dieet of nervus vagusstimulatie.</p>","image_url":"","wiki_title":"Lennox–Gastaut syndrome","match":"syndroom van lennox-gastaux","option_only":true},"antistoffen tegen acetylcholinereceptor":{"title":"Myasthenia gravis","short":"Myasthenia gravis is een auto-immuunziekte waarbij antistoffen de acetylcholinereceptoren van de motorische eindplaat blokkeren, met een spierzwakte die toeneemt bij inspanning.","definition":"<p>Vaak begint <strong>myasthenia gravis</strong> met ptosis en dubbelzien; later kunnen slikken, praten en ademhalen zwak worden (myasthene crisis). Naast anti-AChR komen anti-MuSK-antistoffen voor. Er is een samenhang met een thymoom. Behandeling: pyridostigmine, immunosuppressie, thymectomie.</p>","image_url":"","wiki_title":"Myasthenia gravis","match":"antistoffen tegen acetylcholinereceptor","option_only":true},"colorectaal carcinoom":{"title":"Colorectaal carcinoom","short":"Het colorectaal carcinoom is een adenocarcinoom van de dikke darm, meestal ontstaan uit een adenoom.","definition":"<p>Een tumor <strong>links</strong> geeft vaak een veranderd ontlastingspatroon en bloed bij de ontlasting; een tumor <strong>rechts</strong> vaker een ijzergebreksanemie. Risicofactoren: leeftijd, familie, IBD, Lynch-syndroom en FAP. In Nederland is er een bevolkingsonderzoek met een FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"colorectaal carcinoom|darmkanker|coloncarcinoom|rectumcarcinoom","option_only":true},"leukemie":{"title":"Leukemie","short":"Leukemie is een kwaadaardige ziekte van bloedvormende cellen, met afwijkende cellen in beenmerg en bloed.","definition":"<p>Bij <strong>acute leukemie</strong> (AML, ALL) verdringen onrijpe blasten de normale bloedaanmaak, met anemie, infecties en bloedingen. Chronische vormen (CML, CLL) verlopen langzamer. ALL is de meest voorkomende kanker bij kinderen.</p>","image_url":"","wiki_title":"Leukemia","match":"leukemie|acute leukemie|chronische leukemie","option_only":true},"hoofd-halstumor":{"title":"Hoofd-halskanker","short":"Hoofd-halskanker zijn meestal plaveiselcelcarcinomen van mond, keel, strottenhoofd of neusbijholten.","definition":"<p>De belangrijkste risicofactoren zijn <strong>roken en alcohol</strong>; voor orofarynxtumoren ook HPV (betere prognose). Aanhoudende heesheid, een niet-genezende wond in de mond, slikklachten of een halszwelling moeten worden onderzocht.</p>","image_url":"","wiki_title":"Head and neck cancer","match":"hoofd-halstumor|hoofd-halskanker|hoofd-halscarcinoom","option_only":true},"hersenstaminfarct":{"title":"Hersenstaminfarct","short":"Een hersenstaminfarct ontstaat door afsluiting van een tak van de a. vertebralis of a. basilaris en geeft vaak ‘gekruiste’ uitval.","definition":"<p>Kenmerkend is uitval van hersenzenuwen aan de ene kant met verlamming of gevoelsstoornis van het lichaam aan de andere kant, en vaak dubbelzien, duizeligheid, slikstoornissen en ataxie. Voorbeelden zijn het syndroom van Wallenberg en een locked-in syndroom.</p>","image_url":"","wiki_title":"Brainstem stroke","match":"hersenstaminfarct|hersenstamberoerte","option_only":true},"cervicogene duizeligheid":{"title":"Cervicogene duizeligheid","short":"Cervicogene duizeligheid is een onvast gevoel dat samenhangt met nekklachten, door een verstoorde informatie uit de nekreceptoren.","definition":"<p>Het is een diagnose bij uitsluiting: eerst moeten vestibulaire en centrale oorzaken, zoals BPPV en vertebrobasilaire problemen, worden uitgesloten.</p>","image_url":"","wiki_title":"","match":"cervicogene duizeligheid","option_only":true},"postcoïtale hoofdpijn":{"title":"Hoofdpijn bij seksuele activiteit","short":"Hoofdpijn bij seksuele activiteit kan dof opbouwen of plotseling heftig zijn rond het orgasme.","definition":"<p>Bij een eerste <strong>plotselinge, heftige hoofdpijn</strong> moet altijd een subarachnoïdale bloeding of een reversibel vasoconstrictiesyndroom worden uitgesloten, ook als de context seksuele activiteit is.</p>","image_url":"","wiki_title":"","match":"postcoïtale hoofdpijn|orgasmehoofdpijn","option_only":true},"audiologisch onderzoek":{"title":"Audiologisch onderzoek","short":"Bij audiologisch onderzoek wordt het gehoor gemeten, o.a. met een toonaudiogram en spraakaudiometrie.","definition":"<p>Een <strong>toonaudiogram</strong> onderscheidt geleidingsverlies (verschil tussen lucht- en beengeleiding) van perceptief verlies. Een eenzijdig perceptief verlies of oorsuizen vraagt om een MRI om een brughoektumor uit te sluiten.</p>","image_url":"","wiki_title":"Audiometry","match":"audiologisch onderzoek|audiogram|toonaudiogram","option_only":true}};
